INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群众组织", "is_correct": true, "explanation": "群众组织：由广大民众组成的团体，如工会，与“工会是一种……”相符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是用来演奏的器具，工会不是乐器，不能这样说。"}, {"text": "行政机关", "is_correct": false, "explanation": "语义：“行政机关”是政府系统的机构，工会不属于政府行政机构。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物是生物的一类，工会是人组成的团体，二者性质完全不同。"}], "explanations": {"群众组织": "群众组织：由广大民众组成的团体，如工会，与“工会是一种……”相符。", "乐器": "语义：乐器是用来演奏的器具，工会不是乐器，不能这样说。", "行政机关": "语义：“行政机关”是政府系统的机构，工会不属于政府行政机构。", "动物": "语义：动物是生物的一类，工会是人组成的团体，二者性质完全不同。"}, "sentence_index": 0, "correct_answer": "群众组织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个群众组织是国家机关的一部分。", "explanation": "这里应该用〈政府部门〉。群众组织是民众自愿组成的团体，不属于国家机关系统，二者不能等同。"}, {"text": "这个群众组织每天生产很多汽车。", "explanation": "这里应该用〈汽车厂〉。群众组织是民众自愿组成的团体，不以生产为目的，不会每天生产汽车。"}, {"text": "这家群众组织的产品卖得很好。", "explanation": "这里应该用〈公司〉。群众组织是民众自愿组成的团体，不以生产、销售产品为主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群众组织", "is_correct": true, "explanation": "群众组织：由民众组成的团体，与“工人们的……”相符。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库用来存放货物，不是工人们组织起来的团体。"}, {"text": "寺庙", "is_correct": false, "explanation": "语义：寺庙是宗教场所，不是工人们组成的团体。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地是埋葬逝者的地方，与工会的性质完全不符。"}], "explanations": {"群众组织": "群众组织：由民众组成的团体，与“工人们的……”相符。", "仓库": "语义：仓库用来存放货物，不是工人们组织起来的团体。", "寺庙": "语义：寺庙是宗教场所，不是工人们组成的团体。", "墓地": "语义：墓地是埋葬逝者的地方，与工会的性质完全不符。"}, "sentence_index": 6, "correct_answer": "群众组织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这个群众组织送给了朋友。", "explanation": "群众组织是团体，不是可以送给别人的物品，这样说不通。"}, {"text": "这个群众组织每天早上都要吃早饭。", "explanation": "群众组织是团体，不是人，不会吃东西，这样说不通。"}, {"text": "我们班的群众组织跑得很快。", "explanation": "群众组织不是人，不能用来描述跑步的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工会、妇联这几个群众组织们都很重要。", "corrected_sentence": "工会、妇联这几个群众组织都很重要。", "error_description": "错误：“们”只能加在指人的名词后，“群众组织”是团体，不能加“们”，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们社区有一座群众组织，专门照顾独居老人。", "corrected_sentence": "我们社区有一个群众组织，专门照顾独居老人。", "error_description": "错误：“座”用于山、桥、楼等大型固定物，群众组织应该用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96439, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96439, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96439, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "和朋友轻松地说话。", "primary_collocate": null, "pronunciation": "liáo", "ipa": "ljɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "周末我和朋友在咖啡馆聊了一下午。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们聊得很开心，忘了时间。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢跟好朋友聊电影。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们坐在院子里聊着往事。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你聊聊最近的生活。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在公园里一边走一边聊。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，我们去喝茶聊一聊吧。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我和老同学聊到很晚。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和室友常常聊学校的事。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天有空吗？我们找个地方聊。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聊聊", "label": "重叠"}, {"form": "聊了", "label": "体标"}, {"form": "聊着", "label": "体标"}, {"form": "聊过", "label": "体标"}, {"form": "聊天", "label": "复合"}], "register": "口语", "sense_fingerprint": "动作：和朋友轻松地说话交流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，在咖啡馆“洗了一下午”与和朋友交谈的场景不符。"}, {"text": "聊", "is_correct": true, "explanation": "聊：指和朋友轻松地说话，与“和朋友在咖啡馆”及“一下午”的语境相符。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，与坐在咖啡馆的情境不符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指搬运东西，与和朋友坐在咖啡馆的情境不符。"}], "explanations": {"洗": "语义：“洗”指清洁，在咖啡馆“洗了一下午”与和朋友交谈的场景不符。", "聊": "聊：指和朋友轻松地说话，与“和朋友在咖啡馆”及“一下午”的语境相符。", "跑": "语义：“跑”指快速移动，与坐在咖啡馆的情境不符。", "搬": "语义：“搬”指搬运东西，与和朋友坐在咖啡馆的情境不符。"}, "sentence_index": 0, "correct_answer": "聊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对我聊了一声谢谢。", "explanation": "这里应该用〈说〉。聊指两人轻松地交谈，说一句话要用〈说〉，不能用“聊”。"}, {"text": "他做错了事，老师聊了他一顿。", "explanation": "这里应该用〈训〉。聊是轻松交谈，批评训斥要用〈训〉，不能用“聊”。"}, {"text": "我昨天聊了一场电影。", "explanation": "这里应该用〈看〉。聊指交谈，看电影要用〈看〉，不能用“聊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡", "is_correct": false, "explanation": "搭配：“喝茶”之后不能接“睡”，与交谈的情境不符。"}, {"text": "聊", "is_correct": true, "explanation": "聊：指随意交谈，与“喝茶”和“聊一聊吧”的语境相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书面记录，与喝茶时的轻松交谈不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，“去喝茶修一聊吧”没有合理的修理对象，句意不通。"}], "explanations": {"睡": "搭配：“喝茶”之后不能接“睡”，与交谈的情境不符。", "聊": "聊：指随意交谈，与“喝茶”和“聊一聊吧”的语境相符。", "写": "语义：“写”指书面记录，与喝茶时的轻松交谈不符。", "修": "语义：“修”指修理，“去喝茶修一聊吧”没有合理的修理对象，句意不通。"}, "sentence_index": 6, "correct_answer": "聊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给朋友聊了一封信。", "explanation": "这里应该用〈写〉。聊指交谈，写信要用〈写〉，不能用“聊”。"}, {"text": "我给朋友聊了一杯咖啡。", "explanation": "这里应该用〈倒〉。聊指交谈，给人倒饮料要用〈倒〉，不能用“聊”。"}, {"text": "他昨天聊了一双鞋。", "explanation": "这里应该用〈买〉。聊指交谈，买东西要用〈买〉，不能用“聊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们聊很投机。", "corrected_sentence": "我们聊得很投机。", "error_description": "错误形式：“聊很投机”；正确形式：“聊得很投机”。描述动作结果的补语须用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐下来了聊一会儿。", "corrected_sentence": "我们坐下来聊了一会儿。", "error_description": "错误形式：“了聊”；正确形式：“聊了”。“了”表示完成，应放在动词之后，不能放在动词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96440, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96440, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96440, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "闲谈；随意地交谈。", "primary_collocate": null, "pronunciation": "liáo", "ipa": "ljɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "老人们坐在树下聊家常。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们随便聊，不用太认真。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们聊起了小时候的故事。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，同事们在办公室里聊几句。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车上，我和旁边的人聊了很久。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喜欢跟邻居聊足球。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们聊了半天，也没聊出结果。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们坐下来聊一会儿吧。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨很大，我们待在家里聊了一天。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们边喝茶边聊，气氛很轻松。", "target_word": "聊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聊聊", "label": "重叠"}, {"form": "聊了", "label": "体标"}, {"form": "聊着", "label": "体标"}, {"form": "聊过", "label": "体标"}, {"form": "聊天", "label": "复合"}], "register": "口语", "sense_fingerprint": "动作：没有目的地闲谈、随意交谈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修", "is_correct": false, "explanation": "搭配：“修”多接机器、房屋等，不说“修家常”。"}, {"text": "聊", "is_correct": true, "explanation": "聊：指随意交谈，“聊家常”是常见搭配，与“坐在树下”的场景相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不说“煮家常”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去污物，与坐在树下闲谈的情境不符。"}], "explanations": {"修": "搭配：“修”多接机器、房屋等，不说“修家常”。", "聊": "聊：指随意交谈，“聊家常”是常见搭配，与“坐在树下”的场景相符。", "煮": "搭配：“煮”的对象是食物，不说“煮家常”。", "擦": "语义：“擦”指抹去污物，与坐在树下闲谈的情境不符。"}, "sentence_index": 0, "correct_answer": "聊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈聊了一桌子饭。", "explanation": "这里应该用〈做〉。聊指随意交谈，做饭要用〈做〉，不能用“聊”。"}, {"text": "昨晚我聊了一个好觉。", "explanation": "这里应该用〈睡〉。聊指随意交谈，“睡了一个好觉”要用〈睡〉，不能用“聊”。"}, {"text": "他在纸上聊了一个字。", "explanation": "这里应该用〈写〉。聊指随意交谈，在纸上写字要用〈写〉，不能用“聊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡", "is_correct": false, "explanation": "语义：“睡”指休息，与她们交谈的情境无关。"}, {"text": "聊", "is_correct": true, "explanation": "聊：指随意交谈，与“没聊出结果”的后半句形成呼应。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不与“聊出结果”搭配。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，与交谈无关。"}], "explanations": {"睡": "语义：“睡”指休息，与她们交谈的情境无关。", "聊": "聊：指随意交谈，与“没聊出结果”的后半句形成呼应。", "吃": "搭配：“吃”的对象是食物，不与“聊出结果”搭配。", "跑": "语义：“跑”指快速移动，与交谈无关。"}, "sentence_index": 6, "correct_answer": "聊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们聊了一场篮球。", "explanation": "这里应该用〈打〉。聊指随意交谈，打篮球要用〈打〉，不能用“聊”。"}, {"text": "朋友聊了我一顿饭。", "explanation": "这里应该用〈请〉。聊指随意交谈，请客吃饭要用〈请〉，不能用“聊”。"}, {"text": "我们聊了一次课。", "explanation": "这里应该用〈上〉。聊指随意交谈，上课要用〈上〉，不能用“聊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们了聊一会儿天。", "corrected_sentence": "他们聊了一会儿天。", "error_description": "错误形式：“了聊”；正确形式：“聊了”。“了”是体标，应紧跟在动词“聊”之后，不能放在“聊”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前过聊这个问题。", "corrected_sentence": "我们以前聊过这个问题。", "error_description": "错误形式：“过聊”；正确形式：“聊过”。“过”是动词后的体标，应紧接在“聊”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机或船只定期航行的路线。", "primary_collocate": null, "pronunciation": "háng xiàn", "ipa": "xɑŋ˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司新开了一条北京到巴黎的航线。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为台风，这条航线今天停飞了。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条海上航线连接两个大港口。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都乘这条航线的飞机去上海出差。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算增加几条国际航线。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天这条航线的乘客比较少。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新航线开通后，两地的飞行时间缩短了一半。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司有二十多条国内航线。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雪，飞机改变了原来的航线。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，商船沿着这条航线运送茶叶。", "target_word": "航线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "国际航线", "label": "复合"}], "register": "中性", "sense_fingerprint": "飞机或船只定期航行的路线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5192d602-4ef9-4f05-9da9-5f33ac684468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "航线", "is_correct": true, "explanation": "正确：航线（háng xiàn）指飞机或船定期航行的路线。"}, {"text": "横线", "is_correct": false, "explanation": "横线（héng xiàn）与航线只差第一个字的韵母（eng 与 ang），声调相同，意思是横向的线。"}, {"text": "防线", "is_correct": false, "explanation": "防线（fáng xiàn）与航线只差第一个字的声母（f 与 h），声调相同，意思是防御的界线。"}, {"text": "航向", "is_correct": false, "explanation": "航向（háng xiàng）与航线只差第二个字的韵母（xiàng 与 xiàn），意思是船或飞机的行进方向，不是固定路线。"}], "explanations": {"航线": "正确：航线（háng xiàn）指飞机或船定期航行的路线。", "横线": "横线（héng xiàn）与航线只差第一个字的韵母（eng 与 ang），声调相同，意思是横向的线。", "防线": "防线（fáng xiàn）与航线只差第一个字的声母（f 与 h），声调相同，意思是防御的界线。", "航向": "航向（háng xiàng）与航线只差第二个字的韵母（xiàng 与 xiàn），意思是船或飞机的行进方向，不是固定路线。"}, "sentence_index": null, "correct_answer": "航线"}, "level_3": {"options": [{"text": "航线", "is_correct": true, "explanation": "正确：新开的是一条北京到巴黎的航线，指飞机定期往返的路线。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是自然水道，不能说“新开”，也不是北京到巴黎的运输路线。"}, {"text": "公交线", "is_correct": false, "explanation": "搭配：“公交线”只指城市内部的公共汽车路线，不能说“北京到巴黎的公交线”。"}, {"text": "街", "is_correct": false, "explanation": "语义：街是城市里的道路，不能连接两个国家的城市。"}], "explanations": {"航线": "正确：新开的是一条北京到巴黎的航线，指飞机定期往返的路线。", "河": "语义：河是自然水道，不能说“新开”，也不是北京到巴黎的运输路线。", "公交线": "搭配：“公交线”只指城市内部的公共汽车路线，不能说“北京到巴黎的公交线”。", "街": "语义：街是城市里的道路，不能连接两个国家的城市。"}, "sentence_index": 0, "correct_answer": "航线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天沿着这条航线走路去上班。", "explanation": "这里应当用〈路线〉。航线指飞机或船定期航行的路线，走路上班的路不叫航线。"}, {"text": "这次航线晚点了两个小时。", "explanation": "这里应当用〈航班〉。晚点的是某个班次的飞机，航线只是路线本身，不会晚点。"}, {"text": "这条航线经过三个公交车站。", "explanation": "这里应当用〈线路〉。航线在空中或水上，不经过公交车站；公交车站属于陆上线路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航线", "is_correct": true, "explanation": "正确：航线开通后，两地的飞行时间才会缩短。"}, {"text": "地铁线", "is_correct": false, "explanation": "语义：地铁线在城市内运行，不能缩短两地之间的飞行时间。"}, {"text": "餐厅", "is_correct": false, "explanation": "搭配：“开通”用于线路或服务，不说“开通餐厅”。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话开通与两地的飞行时间无关，句意不通。"}], "explanations": {"航线": "正确：航线开通后，两地的飞行时间才会缩短。", "地铁线": "语义：地铁线在城市内运行，不能缩短两地之间的飞行时间。", "餐厅": "搭配：“开通”用于线路或服务，不说“开通餐厅”。", "电话": "语义：电话开通与两地的飞行时间无关，句意不通。"}, "sentence_index": 6, "correct_answer": "航线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "航线正在滑行，请系好安全带。", "explanation": "这里应当用〈飞机〉。滑行是飞机在跑道上移动，航线是路线，不能滑行。"}, {"text": "这条航线从早到晚都有列车经过。", "explanation": "这里应当用〈铁路〉。列车经过的是陆上铁路，航线在空中或水上，不能有列车经过。"}, {"text": "航线很好听，大家都喜欢唱。", "explanation": "这里应当用〈歌曲〉。好听、能唱的是歌曲，航线是路线，不能唱，也不能说好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座航线下个月正式开通。", "corrected_sentence": "这条航线下个月正式开通。", "error_description": "错误形式“这座航线”，正确形式“这条航线”。“座”用于山、桥、楼房等大型固定物，航线是线状的路线，量词应当用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条航线终于通开了。", "corrected_sentence": "这条航线终于开通了。", "error_description": "错误形式“通开了”，正确形式“开通了”。“开通”中“通”是补语，两者顺序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96443, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "“幸福”与“苦难”意思相反，是反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是具体的家具，与“苦难”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是自然事物，与“苦难”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "“天气”指一时的气候状况，与“苦难”没有反义关系。"}], "correct_answer": "幸福", "explanations": {"幸福": "“幸福”与“苦难”意思相反，是反义词。", "桌子": "“桌子”是具体的家具，与“苦难”没有反义关系。", "河流": "“河流”是自然事物，与“苦难”没有反义关系。", "天气": "“天气”指一时的气候状况，与“苦难”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
