INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96443, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人受到的很大的痛苦和不幸。", "primary_collocate": null, "pronunciation": "kǔ nàn", "ipa": "kʰu˨˩ nan˥˩", "syllable_count": 2, "sentences": [{"text": "战争给无数百姓带来了深重的苦难。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民经历过漫长的苦难。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一个民族的苦难。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，农民长期生活在苦难之中。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震让灾区的群众陷入了深深的苦难。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本书，记录战争年代人们的苦难。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对苦难，这些村民互相帮助，没有放弃。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人常给孙子讲起那段苦难的岁月。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，人们终于告别了多年的苦难。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座纪念馆让我们记住那一段苦难的历史。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "众人共同遭受的巨大痛苦和不幸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苦难", "is_correct": true, "explanation": "苦难：指很多人遭受的巨大痛苦和不幸，与“深重”搭配，符合句意。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：“深重”只修饰灾祸、痛苦一类的负面事物，不能修饰“幸福”。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”是赠送的东西，句中说的是战争给百姓带来的遭遇，不能是礼物。"}, {"text": "荣誉", "is_correct": false, "explanation": "搭配：“深重”形容痛苦或灾难，不能修饰“荣誉”。"}], "explanations": {"苦难": "苦难：指很多人遭受的巨大痛苦和不幸，与“深重”搭配，符合句意。", "幸福": "搭配：“深重”只修饰灾祸、痛苦一类的负面事物，不能修饰“幸福”。", "礼物": "语义：“礼物”是赠送的东西，句中说的是战争给百姓带来的遭遇，不能是礼物。", "荣誉": "搭配：“深重”形容痛苦或灾难，不能修饰“荣誉”。"}, "sentence_index": 0, "correct_answer": "苦难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们的笑声给大家带来了很多苦难。", "explanation": "这里应该用〈快乐〉。“苦难”指痛苦和不幸，孩子们的笑声带来的应是“快乐”。"}, {"text": "他为工作上的苦难整晚睡不着。", "explanation": "这里应该用〈烦恼〉。“苦难”指很大的痛苦和不幸，工作上的小烦心用“烦恼”。"}, {"text": "他这次考试取得了很好的苦难。", "explanation": "这里应该用〈成绩〉。“苦难”指痛苦和不幸，不能说“取得很好的”，考试的结果应说“成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苦难", "is_correct": true, "explanation": "苦难：指很多人共同遭受的痛苦和不幸，符合“面对”和“互相帮助、没有放弃”的语境。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：“面对”接的是需要直面的困境或事件，“节日”不能被“面对”；“没有放弃”也与节日无关。"}, {"text": "富贵", "is_correct": false, "explanation": "语境：“互相帮助，没有放弃”说的是对困境的坚持，“富贵”不是需要坚持去克服的处境，与句意不合。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：句中“互相帮助，没有放弃”说的是困境中的坚持，与“欢乐”的语境不符。"}], "explanations": {"苦难": "苦难：指很多人共同遭受的痛苦和不幸，符合“面对”和“互相帮助、没有放弃”的语境。", "节日": "搭配：“面对”接的是需要直面的困境或事件，“节日”不能被“面对”；“没有放弃”也与节日无关。", "富贵": "语境：“互相帮助，没有放弃”说的是对困境的坚持，“富贵”不是需要坚持去克服的处境，与句意不合。", "欢乐": "语义：句中“互相帮助，没有放弃”说的是困境中的坚持，与“欢乐”的语境不符。"}, "sentence_index": 6, "correct_answer": "苦难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在学习中遇到了一些苦难。", "explanation": "这里应该用〈困难〉。“苦难”指很大的痛苦和不幸，学习中的一般问题用“困难”。"}, {"text": "这次比赛的苦难让他很难过。", "explanation": "这里应该用〈失败〉。“苦难”指很大的痛苦和不幸，比赛输了用“失败”。"}, {"text": "他在那场比赛中夺得了苦难。", "explanation": "这里应该用〈冠军〉。“苦难”指痛苦和不幸，不能“夺得”，夺得的应是“冠军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多人忘不了那些苦难们。", "corrected_sentence": "很多人忘不了那些苦难。", "error_description": "“苦难”是抽象名词，不能加“们”表示复数。应去掉“们”，说“那些苦难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母亲生病以后，全家人苦难就开始了。", "corrected_sentence": "母亲生病以后，全家人的苦难就开始了。", "error_description": "名词“苦难”前的定语需要加“的”。漏掉“的”，句子就不通，应说“全家人的苦难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
