INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生活中遭受的痛苦和灾难。", "primary_collocate": null, "pronunciation": "kǔ nàn", "ipa": "kʰu˨˩ nan˥˩", "syllable_count": 2, "sentences": [{"text": "他的童年充满了苦难。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一生经历过很多苦难，却总是笑着面对。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲独自承受着生活的苦难。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苦难没有打倒他，反而让他更坚强。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家把自己的苦难写进了小说里。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期的苦难让他的头发早早白了。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从苦难中走出来，开了一家小店。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人说，苦难是一所最好的学校。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没见过像她这样不怕苦难的人。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲病倒以后，一家人的苦难开始了。", "target_word": "苦难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "个人生活中经历的痛苦和灾难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苦难", "is_correct": true, "explanation": "苦难：指生活中遭受的痛苦和灾难，可以充满一个人的童年，符合句意。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“童年充满了……”说的是生活的内容，“雨伞”是物品，不能用来充满童年。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“充满”不能接“桌子”这样的具体物体。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：“夜晚”是时间，不是能够充满童年的内容。"}], "explanations": {"苦难": "苦难：指生活中遭受的痛苦和灾难，可以充满一个人的童年，符合句意。", "雨伞": "语义：“童年充满了……”说的是生活的内容，“雨伞”是物品，不能用来充满童年。", "桌子": "搭配：“充满”不能接“桌子”这样的具体物体。", "夜晚": "语义：“夜晚”是时间，不是能够充满童年的内容。"}, "sentence_index": 0, "correct_answer": "苦难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈的拥抱给了我很多苦难。", "explanation": "这里应该用〈温暖〉。“苦难”指痛苦和灾难，拥抱带给人的应是“温暖”。"}, {"text": "他一生获得了很多苦难。", "explanation": "这里应该用〈荣誉〉。“苦难”指痛苦和灾难，不能说“获得”，获得的应是“荣誉”。"}, {"text": "他这次参加了一场重要的苦难。", "explanation": "这里应该用〈考试〉。“苦难”指痛苦和灾难，不能用来“参加”，参加的应是“考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苦难", "is_correct": true, "explanation": "苦难：指生活中遭受的痛苦和灾难，“从……中走出来”指摆脱这种处境，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“从……中走出来”指摆脱某种处境，“冰箱”是物品，不能作为可以走出来的处境。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：“从……中走出来”指摆脱某种处境，“晚饭”不是可以走出来的处境。"}, {"text": "账本", "is_correct": false, "explanation": "语义：“账本”是记账的本子，不是人生中可以走出来的境况。"}], "explanations": {"苦难": "苦难：指生活中遭受的痛苦和灾难，“从……中走出来”指摆脱这种处境，符合句意。", "冰箱": "语义：“从……中走出来”指摆脱某种处境，“冰箱”是物品，不能作为可以走出来的处境。", "晚饭": "语义：“从……中走出来”指摆脱某种处境，“晚饭”不是可以走出来的处境。", "账本": "语义：“账本”是记账的本子，不是人生中可以走出来的境况。"}, "sentence_index": 6, "correct_answer": "苦难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父亲病倒以后，全家人做出了一个苦难。", "explanation": "这里应该用〈决定〉。“苦难”指痛苦和灾难，不能“做出”，做出的应是“决定”。"}, {"text": "两家人的苦难开始了，谁也不让谁。", "explanation": "这里应该用〈纠纷〉。“苦难”指很大的痛苦和不幸，两家之间的争执用“纠纷”。"}, {"text": "这次的苦难让大家很兴奋。", "explanation": "这里应该用〈成功〉。“苦难”指痛苦和灾难，不能让人“兴奋”，让人兴奋的应是“成功”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那些年的苦难们让他变得很沉默。", "corrected_sentence": "那些年的苦难让他变得很沉默。", "error_description": "“苦难”是抽象名词，不能加“们”表示复数。应去掉“们”，说“那些年的苦难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲住院以后，全家人苦难就来了。", "corrected_sentence": "父亲住院以后，全家人的苦难就来了。", "error_description": "名词“苦难”前的定语需要加“的”。漏掉“的”，句子就不通，应说“全家人的苦难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96445, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96445, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你现在遇到的是什么样的情况。", "primary_collocate": null, "pronunciation": "chǔ jìng", "ipa": "ʈʂʰu˨˩˦ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我理解你现在的处境。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道自己的处境有多危险。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这种处境下，你打算怎么办？", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都很关心她的处境。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先看清自己的处境，再做决定。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有工作又没有钱，他的处境很困难。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我也曾有过和你一样的处境。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对这样的处境，他一点也不害怕。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我现在的处境怎么样。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你现在的处境，我来帮你。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "抽象名词：某人当前遇到的具体情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96445, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处境", "is_correct": true, "explanation": "正确。处境指个人当前所处的境况。"}, {"text": "出境", "is_correct": false, "explanation": "chūjìng（第一声）与 chǔjìng（第三声）首字声调不同，意思是离开国境。"}, {"text": "出镜", "is_correct": false, "explanation": "chūjìng（第一声）与 chǔjìng（第三声）首字声调不同，意思是出现在镜头前。"}, {"text": "除净", "is_correct": false, "explanation": "chújìng（第二声）与 chǔjìng（第三声）首字声调不同，意思是全部去掉。"}], "explanations": {"处境": "正确。处境指个人当前所处的境况。", "出境": "chūjìng（第一声）与 chǔjìng（第三声）首字声调不同，意思是离开国境。", "出镜": "chūjìng（第一声）与 chǔjìng（第三声）首字声调不同，意思是出现在镜头前。", "除净": "chújìng（第二声）与 chǔjìng（第三声）首字声调不同，意思是全部去掉。"}, "sentence_index": null, "correct_answer": "处境"}, "level_3": {"options": [{"text": "处境", "is_correct": true, "explanation": "正确。处境指你当前所处的情况，与“理解”搭配自然。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不是需要理解的境况，句子读不通。"}, {"text": "存款", "is_correct": false, "explanation": "搭配：“理解”可以接“情况”“心情”，不能接“存款”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只指外形，不能指当前遇到的境况。"}], "explanations": {"处境": "正确。处境指你当前所处的情况，与“理解”搭配自然。", "体重": "语义：“体重”指身体的重量，不是需要理解的境况，句子读不通。", "存款": "搭配：“理解”可以接“情况”“心情”，不能接“存款”。", "身材": "体貌：“身材”只指外形，不能指当前遇到的境况。"}, "sentence_index": 0, "correct_answer": "处境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司的处境很高，大家都很尊敬他。", "explanation": "这里应该用〈地位〉。处境指所处的境况，没有高低之分；说人在组织中的高低要用〈地位〉。"}, {"text": "我们要保护这个处境。", "explanation": "这里应该用〈环境〉。处境指人所处的情况，不指周围的自然或社会条件，不能说“保护这个处境”。"}, {"text": "这幅画的处境很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，处境指人所处的境况，不能用来形容画的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96445, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "处境", "is_correct": true, "explanation": "正确。处境指个人当前所处的境况。"}, {"text": "处警", "is_correct": false, "explanation": "chǔjǐng 与 chǔjìng 首字相同，末字声调不同（第三声与第四声），意思是处理报警事件。"}, {"text": "触景", "is_correct": false, "explanation": "chùjǐng 与 chǔjìng 两个字声调都不同（chù 第四声，jǐng 第三声），意思是接触到眼前的景物，如“触景生情”。"}, {"text": "出警", "is_correct": false, "explanation": "chūjǐng 与 chǔjìng 首字声调不同（第一声与第三声），末字也不同（jǐng 第三声与 jìng 第四声），意思是警察出动。"}], "explanations": {"处境": "正确。处境指个人当前所处的境况。", "处警": "chǔjǐng 与 chǔjìng 首字相同，末字声调不同（第三声与第四声），意思是处理报警事件。", "触景": "chùjǐng 与 chǔjìng 两个字声调都不同（chù 第四声，jǐng 第三声），意思是接触到眼前的景物，如“触景生情”。", "出警": "chūjǐng 与 chǔjìng 首字声调不同（第一声与第三声），末字也不同（jǐng 第三声与 jìng 第四声），意思是警察出动。"}, "sentence_index": null, "correct_answer": "处境"}, "level_3": {"options": [{"text": "处境", "is_correct": true, "explanation": "正确。处境指你所处的境况，可以用“有过和你一样的”来修饰。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”是天体，不是个人经历的境况，“有过和你一样的月亮”说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“有过”不能接“脚步”，“脚步”不是可以拥有或经历的东西。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”是天体，不能表示个人的遭遇，句子不通。"}], "explanations": {"处境": "正确。处境指你所处的境况，可以用“有过和你一样的”来修饰。", "月亮": "语义：“月亮”是天体，不是个人经历的境况，“有过和你一样的月亮”说不通。", "脚步": "搭配：“有过”不能接“脚步”，“脚步”不是可以拥有或经历的东西。", "太阳": "语义：“太阳”是天体，不能表示个人的遭遇，句子不通。"}, "sentence_index": 6, "correct_answer": "处境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事的处境很坚定。", "explanation": "这里应该用〈立场〉。立场指对问题的态度，可以“坚定”；处境指所处的情况，不能用“坚定”来形容。"}, {"text": "他的处境是一名老师。", "explanation": "这里应该用〈身份〉。身份指人的社会角色，可以说“是一名老师”；处境指所处的境况，不能这样下定义。"}, {"text": "他最近的处境很积极。", "explanation": "这里应该用〈状态〉。“积极”可以形容人的精神状态，处境指所处的境况，不能用“积极”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都很担心他这只处境。", "corrected_sentence": "我们都很担心他这种处境。", "error_description": "量词错误：“处境”应该用量词“种”，这里误用“只”。“只”用于动物等，不能用来数“处境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面对这座困难的处境，他没有放弃。", "corrected_sentence": "面对这种困难的处境，他没有放弃。", "error_description": "量词错误：“处境”应该用量词“种”，这里误用“座”。“座”用于山、房屋等大型固定物，不能用来数“处境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96446, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96446, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人所处的境况和环境。", "primary_collocate": null, "pronunciation": "chǔ jìng", "ipa": "ʈʂʰu˨˩˦ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小王刚来这座城市，处境不太容易。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些孩子的处境让大家很担心。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论处境多么差，她都不放弃。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司里的处境越来越糟。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人独自生活的处境需要社会关注。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到农村以后，他们家的处境好多了。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者写出了小人物的处境。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了工作，处境比以前好了。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对尴尬的处境，她笑了笑。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难民的处境让很多人难过。", "target_word": "处境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "抽象名词：个人所处的境况和环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处境", "is_correct": true, "explanation": "正确。处境指个人所处的境况和环境。"}, {"text": "出镜", "is_correct": false, "explanation": "chūjìng（第一声）与 chǔjìng（第三声）首字声调不同，意思是出现在镜头前。"}, {"text": "出境", "is_correct": false, "explanation": "chūjìng（第一声）与 chǔjìng（第三声）首字声调不同，意思是离开国境。"}, {"text": "除净", "is_correct": false, "explanation": "chújìng（第二声）与 chǔjìng（第三声）首字声调不同，意思是全部去掉。"}], "explanations": {"处境": "正确。处境指个人所处的境况和环境。", "出镜": "chūjìng（第一声）与 chǔjìng（第三声）首字声调不同，意思是出现在镜头前。", "出境": "chūjìng（第一声）与 chǔjìng（第三声）首字声调不同，意思是离开国境。", "除净": "chújìng（第二声）与 chǔjìng（第三声）首字声调不同，意思是全部去掉。"}, "sentence_index": null, "correct_answer": "处境"}, "level_3": {"options": [{"text": "处境", "is_correct": true, "explanation": "正确。处境指个人所处的境况，“不太容易”可以用来形容它。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“不太容易”说的是事情的难度，不能用来形容年龄。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：“嗓音”指声音的特点，与“容易”无关，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是外形，不能用“不太容易”来形容。"}], "explanations": {"处境": "正确。处境指个人所处的境况，“不太容易”可以用来形容它。", "年龄": "搭配：“不太容易”说的是事情的难度，不能用来形容年龄。", "嗓音": "语义：“嗓音”指声音的特点，与“容易”无关，句子不通。", "身高": "体貌：“身高”是外形，不能用“不太容易”来形容。"}, "sentence_index": 0, "correct_answer": "处境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对工作的处境很认真。", "explanation": "这里应该用〈态度〉。“认真”形容人对事情的态度，处境不能“认真”。"}, {"text": "他的处境很高，常常帮助别人。", "explanation": "这里应该用〈境界〉。“高”可以形容思想、修养的境界；处境指所处的境况，不能用“高”来形容。"}, {"text": "这个班的处境增加了很多。", "explanation": "这里应该用〈人数〉。“增加”用于人数等可以计量的数量，处境指所处的境况，不能用“增加”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96446, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "处境", "is_correct": true, "explanation": "正确。处境指个人所处的境况和环境。"}, {"text": "处警", "is_correct": false, "explanation": "chǔjǐng 与 chǔjìng 首字相同，末字声调不同（第三声与第四声），意思是处理报警事件。"}, {"text": "触景", "is_correct": false, "explanation": "chùjǐng 与 chǔjìng 两个字声调都不同（chù 第四声，jǐng 第三声），意思是接触到眼前的景物，如“触景生情”。"}, {"text": "出警", "is_correct": false, "explanation": "chūjǐng 与 chǔjìng 首字声调不同（第一声与第三声），末字也不同（jǐng 第三声与 jìng 第四声），意思是警察出动。"}], "explanations": {"处境": "正确。处境指个人所处的境况和环境。", "处警": "chǔjǐng 与 chǔjìng 首字相同，末字声调不同（第三声与第四声），意思是处理报警事件。", "触景": "chùjǐng 与 chǔjìng 两个字声调都不同（chù 第四声，jǐng 第三声），意思是接触到眼前的景物，如“触景生情”。", "出警": "chūjǐng 与 chǔjìng 首字声调不同（第一声与第三声），末字也不同（jǐng 第三声与 jìng 第四声），意思是警察出动。"}, "sentence_index": null, "correct_answer": "处境"}, "level_3": {"options": [{"text": "处境", "is_correct": true, "explanation": "正确。处境指人所处的境况，“写出”人物的处境在语义上通顺。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不是小人物的境况，句子读不通。"}, {"text": "存款", "is_correct": false, "explanation": "搭配：“写出”可以接“故事”“心情”，不能接“存款”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的热度，不能用来描述人物的遭遇。"}], "explanations": {"处境": "正确。处境指人所处的境况，“写出”人物的处境在语义上通顺。", "体重": "语义：“体重”指身体的重量，不是小人物的境况，句子读不通。", "存款": "搭配：“写出”可以接“故事”“心情”，不能接“存款”。", "体温": "语义：“体温”指身体的热度，不能用来描述人物的遭遇。"}, "sentence_index": 6, "correct_answer": "处境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的观点很新颖，处境也很新颖。", "explanation": "这里应该用〈想法〉。“新颖”可以形容想法、作品，处境指所处的境况，不能用“新颖”来形容。"}, {"text": "这道菜的处境很好。", "explanation": "这里应该用〈味道〉。“好”可以评价味道，处境指人或群体的境况，不能用来说菜。"}, {"text": "她的处境很开朗，朋友很多。", "explanation": "这里应该用〈性格〉。“开朗”形容人的性格，处境指所处的境况，不能用“开朗”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这颗处境感到很无奈。", "corrected_sentence": "他对这种处境感到很无奈。", "error_description": "量词错误：“处境”应该用量词“种”，这里误用“颗”。“颗”用于小而圆的东西，不能用来数“处境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他陷入了这条处境，心里很难过。", "corrected_sentence": "他陷入了这种处境，心里很难过。", "error_description": "量词错误：“处境”应该用量词“种”，这里误用“条”。“条”用于细长的东西，不能用来数“处境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
