INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96447, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家都要照着做的话和办法。", "primary_collocate": null, "pronunciation": "guī ju", "ipa": "kwei̯˥ tɕy", "syllable_count": 2, "sentences": [{"text": "妈妈给我们定了一个规矩：饭前洗手。", "target_word": "规矩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班有个规矩，迟到要打扫教室。", "target_word": "规矩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁都得照规矩办事。", "target_word": "规矩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条规矩大家都要记住。", "target_word": "规矩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "游泳池的规矩写在门口。", "target_word": "规矩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他立了一个规矩：晚上不玩手机。", "target_word": "规矩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你来之前，先听听这里的规矩。", "target_word": "规矩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家的规矩是先让老人吃。", "target_word": "规矩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都要照着规矩做，不能乱来。", "target_word": "规矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "破了规矩的人要向大家道歉。", "target_word": "规矩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "老规矩", "label": "复合"}], "register": "通用", "sense_fingerprint": "大家都要照着做的话和办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96447, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规矩", "is_correct": true, "explanation": "规矩：规定的做法，与“定”搭配，符合句意。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送人的东西，不能被“定”，后文“饭前洗手”也不是礼物的内容。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用具，不能用“定”表示规定，句子不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“定”搭配的是规则、计划，不说“定窗帘”，应说“装”或“买”。"}], "explanations": {"规矩": "规矩：规定的做法，与“定”搭配，符合句意。", "礼物": "语义：礼物是送人的东西，不能被“定”，后文“饭前洗手”也不是礼物的内容。", "雨伞": "语义：雨伞是用具，不能用“定”表示规定，句子不通。", "窗帘": "搭配：“定”搭配的是规则、计划，不说“定窗帘”，应说“装”或“买”。"}, "sentence_index": 0, "correct_answer": "规矩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班定了一只规矩，迟到要打扫教室。", "explanation": "这里应该用〈条〉。规矩是名词，它的量词是“条”，“只”不能用来量规矩。"}, {"text": "他算数的规矩很快，一会儿就算完了。", "explanation": "这里应该用〈方法〉。规矩指大家都要照着做的准则，形容算数快慢要用“方法”，不能说“规矩很快”。"}, {"text": "这道题有个好规矩，你试试。", "explanation": "这里应该用〈方法〉。规矩指准则，解题的途径要用“方法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规矩", "is_correct": true, "explanation": "规矩：这里的规定，与“听听”搭配，指先了解规矩，符合句意。"}, {"text": "月光", "is_correct": false, "explanation": "搭配：“听”搭配的是声音、意见，不说“听月光”。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋是穿的东西，不能被“听”，句意不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是摆设，不能被“听”，与“先了解”的句意冲突。"}], "explanations": {"规矩": "规矩：这里的规定，与“听听”搭配，指先了解规矩，符合句意。", "月光": "搭配：“听”搭配的是声音、意见，不说“听月光”。", "皮鞋": "语义：皮鞋是穿的东西，不能被“听”，句意不通。", "花瓶": "语义：花瓶是摆设，不能被“听”，与“先了解”的句意冲突。"}, "sentence_index": 6, "correct_answer": "规矩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把规矩放进了书包里。", "explanation": "这里应该用〈文件〉。规矩指大家要照着做的话和办法，不是可以装进书包的实物，实物要用“文件”。"}, {"text": "他用一个规矩赢了比赛。", "explanation": "这里应该用〈招数〉。规矩指准则，比赛中取胜的办法要用“招数”。"}, {"text": "这盘规矩很好吃，一看就很新鲜。", "explanation": "这里应该用〈菜〉。规矩指大家遵守的准则，不能用来指食物，应说“这盘菜很好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都要守这只规矩。", "corrected_sentence": "大家都要守这条规矩。", "error_description": "错误在量词。规矩的量词是“条”，不用“只”，应说“这条规矩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于明白了这里的规矩们。", "corrected_sentence": "他终于明白了这里的规矩。", "error_description": "错误在“规矩”后面加了“们”。“规矩”是抽象名词，不表示复数，应直接说“规矩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96449, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96449, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "眼睛能看到的那么大一片地方。", "primary_collocate": null, "pronunciation": "shì yě", "ipa": "ʂʅ˥˩ jɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "山顶的视野非常好，能看到整个城市。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾挡住了司机的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的窗户大，视野很开阔。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的大树挡住了我的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在最后一排，视野不太好。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从飞机上看，视野里全是白云。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴上眼镜后，视野一下子清楚了。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的后视镜可以扩大司机的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬到山顶，我们的视野一下子变宽了。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖很大，视野里看不到对岸。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "眼睛能看到的范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5192d602-4ef9-4f05-9da9-5f33ac684468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96449, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：视野（shì yě）指眼睛能看到的范围。"}, {"text": "事业", "is_correct": false, "explanation": "事业（shì yè）与视野只差第二个字的声调（yè 与 yě），意思是长期从事的工作或追求。"}, {"text": "失业", "is_correct": false, "explanation": "失业（shī yè）与视野两个字的声调都不同（shī 与 shì，yè 与 yě），意思是没有工作。"}, {"text": "实业", "is_correct": false, "explanation": "实业（shí yè）与视野两个字的声调都不同（shí 与 shì，yè 与 yě），意思是实际的经济事业。"}], "explanations": {"视野": "正确：视野（shì yě）指眼睛能看到的范围。", "事业": "事业（shì yè）与视野只差第二个字的声调（yè 与 yě），意思是长期从事的工作或追求。", "失业": "失业（shī yè）与视野两个字的声调都不同（shī 与 shì，yè 与 yě），意思是没有工作。", "实业": "实业（shí yè）与视野两个字的声调都不同（shí 与 shì，yè 与 yě），意思是实际的经济事业。"}, "sentence_index": null, "correct_answer": "视野"}, "level_3": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：山顶的视野指眼睛能看到的范围，符合“能看到整个城市”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道属于味觉，不能用“能看到整个城市”来描述。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音属于听觉，不能用“能看到整个城市”来描述。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”只说高低，不说“好”，与“看到城市”也不相关。"}], "explanations": {"视野": "正确：山顶的视野指眼睛能看到的范围，符合“能看到整个城市”。", "味道": "语义：味道属于味觉，不能用“能看到整个城市”来描述。", "声音": "语义：声音属于听觉，不能用“能看到整个城市”来描述。", "温度": "搭配：“温度”只说高低，不说“好”，与“看到城市”也不相关。"}, "sentence_index": 0, "correct_answer": "视野"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的视野一直盯着窗外。", "explanation": "这里应当用〈视线〉。“盯着”是目光的动作，视线可以盯着窗外；视野指看到的范围，不能盯。"}, {"text": "那位老师的视野很温和。", "explanation": "这里应当用〈目光〉。温和形容目光，视野是看到的范围，不能说温和。"}, {"text": "他的视野消失在远处。", "explanation": "这里应当用〈身影〉。消失在远处的是人影，视野是看到的范围，不会消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：戴上眼镜后视野变清楚，指看到的范围变清楚。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“清楚”不用来形容心情，心情通常说好或明朗。"}, {"text": "天气", "is_correct": false, "explanation": "语义：戴眼镜不能让天气变清楚，句意不通。"}, {"text": "发音", "is_correct": false, "explanation": "语义：戴眼镜不能让发音变清楚，句意不通。"}], "explanations": {"视野": "正确：戴上眼镜后视野变清楚，指看到的范围变清楚。", "心情": "搭配：“清楚”不用来形容心情，心情通常说好或明朗。", "天气": "语义：戴眼镜不能让天气变清楚，句意不通。", "发音": "语义：戴眼镜不能让发音变清楚，句意不通。"}, "sentence_index": 6, "correct_answer": "视野"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "视野很高大，枝叶茂密。", "explanation": "这里应当用〈大树〉。高大、枝叶茂密形容树木，视野指看到的范围，不能这样描述。"}, {"text": "视野下了一整天，路面都湿了。", "explanation": "这里应当用〈雨〉。下的是雨，视野是看到的范围，不能下。"}, {"text": "视野在窗台上睡觉。", "explanation": "这里应当用〈猫〉。在窗台上睡觉的是动物，视野是看到的范围，不能睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那辆大卡车挡住了我得视野。", "corrected_sentence": "那辆大卡车挡住了我的视野。", "error_description": "错误形式“我得视野”，正确形式“我的视野”。“我的”是定语，修饰“视野”，应当用结构助词“的”，不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座视野很开阔。", "corrected_sentence": "这片视野很开阔。", "error_description": "错误形式“这座视野”，正确形式“这片视野”。“座”用于山、楼、桥等大型固定物，视野应当用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼睛所能看到的空间范围；比喻见识的广度。", "primary_collocate": null, "pronunciation": "shì yě", "ipa": "ʂʅ˥˩ jɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "多读书可以开阔孩子的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国留学让他的视野变得更宽。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的视野很宽，什么新闻都知道。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行能让我们拓宽视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作以后，我才发现自己的视野太小了。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常带学生参观，扩大他们的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去过很多国家，视野很开阔。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书为我打开了新的视野。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和不同领域的人交流，能让人的视野更开阔。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看世界的视野不同，想法也会不同。", "target_word": "视野", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比喻见识的广度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5192d602-4ef9-4f05-9da9-5f33ac684468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：视野（shì yě）此处指见识的广度。"}, {"text": "事业", "is_correct": false, "explanation": "事业（shì yè）与视野只差第二个字的声调（yè 与 yě），意思是长期从事的工作或追求。"}, {"text": "失业", "is_correct": false, "explanation": "失业（shī yè）与视野两个字的声调都不同（shī 与 shì，yè 与 yě），意思是没有工作。"}, {"text": "实业", "is_correct": false, "explanation": "实业（shí yè）与视野两个字的声调都不同（shí 与 shì，yè 与 yě），意思是实际的经济事业。"}], "explanations": {"视野": "正确：视野（shì yě）此处指见识的广度。", "事业": "事业（shì yè）与视野只差第二个字的声调（yè 与 yě），意思是长期从事的工作或追求。", "失业": "失业（shī yè）与视野两个字的声调都不同（shī 与 shì，yè 与 yě），意思是没有工作。", "实业": "实业（shí yè）与视野两个字的声调都不同（shí 与 shì，yè 与 yě），意思是实际的经济事业。"}, "sentence_index": null, "correct_answer": "视野"}, "level_3": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：开阔孩子的视野指扩大见识的广度，符合读书的作用。"}, {"text": "房间", "is_correct": false, "explanation": "语义：读书开阔的是见识，不是房间的大小。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”用“保护”“提高”，不说“开阔”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能说“开阔”，读书也改变不了身高。"}], "explanations": {"视野": "正确：开阔孩子的视野指扩大见识的广度，符合读书的作用。", "房间": "语义：读书开阔的是见识，不是房间的大小。", "视力": "搭配：“视力”用“保护”“提高”，不说“开阔”。", "身高": "搭配：“身高”不能说“开阔”，读书也改变不了身高。"}, "sentence_index": 0, "correct_answer": "视野"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对工作的视野很认真。", "explanation": "这里应当用〈态度〉。“认真”形容人的态度，视野指见识的广度，不能形容认真。"}, {"text": "他的视野很明确。", "explanation": "这里应当用〈目标〉。“明确”用于目标、要求，视野不能说明确。"}, {"text": "他的视野很暴躁。", "explanation": "这里应当用〈脾气〉。“暴躁”形容性情，视野不能用来形容性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视野", "is_correct": true, "explanation": "正确：去过很多国家，视野开阔，指见识广。"}, {"text": "房间", "is_correct": false, "explanation": "语义：去过很多国家与房间大小无关，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“开阔”不用来形容脚步。"}, {"text": "嗓门", "is_correct": false, "explanation": "搭配：“嗓门”用“大”“响亮”，不说“开阔”。"}], "explanations": {"视野": "正确：去过很多国家，视野开阔，指见识广。", "房间": "语义：去过很多国家与房间大小无关，句意不通。", "脚步": "搭配：“开阔”不用来形容脚步。", "嗓门": "搭配：“嗓门”用“大”“响亮”，不说“开阔”。"}, "sentence_index": 6, "correct_answer": "视野"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把视野存进了银行。", "explanation": "这里应当用〈钱〉。存进银行的是钱，视野是抽象的见识，不能存进银行。"}, {"text": "视野开了很多花。", "explanation": "这里应当用〈大树〉。开花的是植物，视野指见识的广度，不能开花。"}, {"text": "视野在树枝上叫个不停。", "explanation": "这里应当用〈鸟〉。在树枝上叫的是鸟，视野指见识的广度，不能叫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次游学让她的视野宽变了。", "corrected_sentence": "这次游学让她的视野变宽了。", "error_description": "错误形式“宽变了”，正确形式“变宽了”。“变宽”是动补结构，补语“宽”必须紧跟“变”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行开阔了我们得视野。", "corrected_sentence": "旅行开阔了我们的视野。", "error_description": "错误形式“我们得视野”，正确形式“我们的视野”。“我们的”是定语，修饰“视野”，这里应用结构助词“的”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
