INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96453, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不知道行不行，先做做看。", "primary_collocate": null, "pronunciation": "shì zhe", "ipa": "ʂɻ̩˥˩ ʈʂə", "syllable_count": 2, "sentences": [{"text": "你可以试着跟他谈谈。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我试着做了一个蛋糕。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕，试着说说看。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她试着打开那扇门。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次滑雪，我试着站起来。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道对不对，先试着做一做吧。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们试着用汉语写日记。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试着给朋友打了电话。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你试着把这些词记下来。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈试着教爷爷用手机。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不确定能不能行，先做一做看看结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试着", "is_correct": true, "explanation": "正确答案：shì zhe，表示先做做看、不确定能不能行。"}, {"text": "使着", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）只差声调，“使着”意思是用、施加，如“使着劲儿”。"}, {"text": "拾着", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）只差声调，“拾着”意思是捡起、拾取。"}, {"text": "试纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhe（轻声）的韵母和声调都不同，“试纸”指用来检测的纸。"}], "explanations": {"试着": "正确答案：shì zhe，表示先做做看、不确定能不能行。", "使着": "shǐ（第三声）与 shì（第四声）只差声调，“使着”意思是用、施加，如“使着劲儿”。", "拾着": "shí（第二声）与 shì（第四声）只差声调，“拾着”意思是捡起、拾取。", "试纸": "zhǐ（第三声）与 zhe（轻声）的韵母和声调都不同，“试纸”指用来检测的纸。"}, "sentence_index": null, "correct_answer": "试着"}, "level_3": {"options": [{"text": "试着", "is_correct": true, "explanation": "正确答案：“试着”表示先试一试，符合“你可以…跟他谈谈”的语境。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”表示击打，不能用来表示为了试探而去跟他谈谈。"}, {"text": "骂", "is_correct": false, "explanation": "搭配：“骂”要带骂的对象，后面不能接“跟他谈谈”这样的动作。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于“跟他谈谈”的语境。"}], "explanations": {"试着": "正确答案：“试着”表示先试一试，符合“你可以…跟他谈谈”的语境。", "打": "语义：“打”表示击打，不能用来表示为了试探而去跟他谈谈。", "骂": "搭配：“骂”要带骂的对象，后面不能接“跟他谈谈”这样的动作。", "吃": "语义：“吃”指进食，不能用于“跟他谈谈”的语境。"}, "sentence_index": 0, "correct_answer": "试着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完步，试着出了一身汗。", "explanation": "“试着”表示有意去尝试某个动作，跑步后身体自然冒汗，并不是能主动去试的事，这里不能用“试着”。"}, {"text": "春天试着来了。", "explanation": "“试着”表示有意去尝试某个动作，季节的更替是自然发生的，人或物都不能去试，这里不能用“试着”。"}, {"text": "她试着生了一场病。", "explanation": "“试着”表示有意去尝试，患病是身体的状况，人不能主动去试，这里不能用“试着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96453, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试着", "is_correct": true, "explanation": "正确答案：shì zhe，表示先做做看、不确定能不能行。"}, {"text": "驶着", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）只差声调，“驶着”意思是（车、船）正在行驶。"}, {"text": "施着", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）只差声调，“施着”意思是施展、施加。"}, {"text": "侍者", "is_correct": false, "explanation": "zhě（第三声）与 zhe（轻声）只差声调，“侍者”指在饭店等地方服务的人。"}], "explanations": {"试着": "正确答案：shì zhe，表示先做做看、不确定能不能行。", "驶着": "shǐ（第三声）与 shì（第四声）只差声调，“驶着”意思是（车、船）正在行驶。", "施着": "shī（第一声）与 shì（第四声）只差声调，“施着”意思是施展、施加。", "侍者": "zhě（第三声）与 zhe（轻声）只差声调，“侍者”指在饭店等地方服务的人。"}, "sentence_index": null, "correct_answer": "试着"}, "level_3": {"options": [{"text": "试着", "is_correct": true, "explanation": "正确答案：“试着”表示先试一试，符合“老师让我们…用汉语写日记”的语境。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“用汉语写日记”连用。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热烹饪，不能用于写日记。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，不能用来指写作这一动作。"}], "explanations": {"试着": "正确答案：“试着”表示先试一试，符合“老师让我们…用汉语写日记”的语境。", "唱": "搭配：“唱”不能与“用汉语写日记”连用。", "煮": "语义：“煮”指加热烹饪，不能用于写日记。", "洗": "语义：“洗”指清洗，不能用来指写作这一动作。"}, "sentence_index": 6, "correct_answer": "试着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他突然试着打了一个喷嚏。", "explanation": "“试着”表示有意去尝试某个动作，喷嚏是身体自然产生的反应，不能有意去试，这里不能用“试着”。"}, {"text": "房子试着倒塌了。", "explanation": "“试着”表示有意去尝试某个动作，倒塌是事物的自然变化，房子没有办法有意去试，这里不能用“试着”。"}, {"text": "他试着变老了。", "explanation": "“试着”表示有意去尝试做某事，衰老是自然过程，不能主动去试，这里不能用“试着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法我没用过，先试着了用一用吧。", "corrected_sentence": "这个办法我没用过，先试着用一用吧。", "error_description": "错误：“试着”是一个整体，后面不能直接接“了”。应改为：这个办法我没用过，先试着用一用吧。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先试着了给她发个消息吧。", "corrected_sentence": "我先试着给她发个消息吧。", "error_description": "错误：“试着”后面不能直接接“了”，“了”表示完成，与“先试着……”表示尝试的语义相悖。应改为：我先试着给她发个消息吧。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
