INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96454, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "尝试着做。", "primary_collocate": null, "pronunciation": "shì zhe", "ipa": "ʂɻ̩˥˩ ʈʂə", "syllable_count": 2, "sentences": [{"text": "孩子试着自己穿衣服。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我试着忘记那些不开心的事。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试着说服爸爸，可是没有成功。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她试着用左手写字。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家试着换一种方法解决问题。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我试着理解他的想法。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟试着骑了一下我的自行车。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你试着多笑一笑，心情会好的。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试着跑了三公里。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们试着从另一个方向去想。", "target_word": "试着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "努力去尝试做某件有些困难的事，后面接动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试着", "is_correct": true, "explanation": "正确答案：shì zhe，表示尝试着做某事。"}, {"text": "使着", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）只差声调，“使着”意思是用、施加，如“使着劲儿”。"}, {"text": "拾着", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）只差声调，“拾着”意思是捡起、拾取。"}, {"text": "试纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhe（轻声）的韵母和声调都不同，“试纸”指用来检测的纸。"}], "explanations": {"试着": "正确答案：shì zhe，表示尝试着做某事。", "使着": "shǐ（第三声）与 shì（第四声）只差声调，“使着”意思是用、施加，如“使着劲儿”。", "拾着": "shí（第二声）与 shì（第四声）只差声调，“拾着”意思是捡起、拾取。", "试纸": "zhǐ（第三声）与 zhe（轻声）的韵母和声调都不同，“试纸”指用来检测的纸。"}, "sentence_index": null, "correct_answer": "试着"}, "level_3": {"options": [{"text": "试着", "is_correct": true, "explanation": "正确答案：“试着”表示尝试去做，符合“孩子…自己穿衣服”的语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复坏了的东西，不能用来指穿衣服这样的动作。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能接“自己穿衣服”。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的对象是场所或物品，后面不能接“穿衣服”这样的动作。"}], "explanations": {"试着": "正确答案：“试着”表示尝试去做，符合“孩子…自己穿衣服”的语境。", "修理": "语义：“修理”指修复坏了的东西，不能用来指穿衣服这样的动作。", "吃": "搭配：“吃”的对象是食物，不能接“自己穿衣服”。", "打扫": "配价：“打扫”的对象是场所或物品，后面不能接“穿衣服”这样的动作。"}, "sentence_index": 0, "correct_answer": "试着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他试着生病了。", "explanation": "“试着”表示有意去尝试做某件事，患病是身体的状况，人没办法主动去尝试，这里不能用“试着”。"}, {"text": "昨晚试着下了一场大雨。", "explanation": "“试着”表示有意去尝试某个动作，降雨是自然现象，没有人能主动去试，这里不能用“试着”。"}, {"text": "我试着出生在北京。", "explanation": "“试着”表示有意去尝试，出生是人无法主动选择或尝试的事，这里不能用“试着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96454, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试着", "is_correct": true, "explanation": "正确答案：shì zhe，表示尝试着做某事。"}, {"text": "驶着", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）只差声调，“驶着”意思是（车、船）正在行驶。"}, {"text": "施着", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）只差声调，“施着”意思是施展、施加。"}, {"text": "侍者", "is_correct": false, "explanation": "zhě（第三声）与 zhe（轻声）只差声调，“侍者”指在饭店等地方服务的人。"}], "explanations": {"试着": "正确答案：shì zhe，表示尝试着做某事。", "驶着": "shǐ（第三声）与 shì（第四声）只差声调，“驶着”意思是（车、船）正在行驶。", "施着": "shī（第一声）与 shì（第四声）只差声调，“施着”意思是施展、施加。", "侍者": "zhě（第三声）与 zhe（轻声）只差声调，“侍者”指在饭店等地方服务的人。"}, "sentence_index": null, "correct_answer": "试着"}, "level_3": {"options": [{"text": "试着", "is_correct": true, "explanation": "正确答案：“试着”表示尝试去做，符合“弟弟…骑了一下我的自行车”的语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，不能用在“骑了一下自行车”的句子里。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”一般用于文字、书报，后面不能接“骑”这样的动作。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”是咀嚼食物，不能用来描述骑车的动作。"}], "explanations": {"试着": "正确答案：“试着”表示尝试去做，符合“弟弟…骑了一下我的自行车”的语境。", "唱": "语义：“唱”是发出歌声，不能用在“骑了一下自行车”的句子里。", "读": "搭配：“读”一般用于文字、书报，后面不能接“骑”这样的动作。", "嚼": "语义：“嚼”是咀嚼食物，不能用来描述骑车的动作。"}, "sentence_index": 6, "correct_answer": "试着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他试着不小心摔了一跤。", "explanation": "“试着”表示有意去尝试，句中却说是无意发生，两者自相矛盾，这里不能用“试着”。"}, {"text": "这件事试着发生在昨天。", "explanation": "“试着”表示有意去尝试，事情的发生是自然的，不是人能主动去试的事，这里不能用“试着”。"}, {"text": "湖面试着结冰了。", "explanation": "“试着”表示有意去尝试，结冰是自然变化，湖面没有办法有意去试，这里不能用“试着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他第一次试着了做饭，味道还不错。", "corrected_sentence": "他第一次试着做饭，味道还不错。", "error_description": "错误：“试着”是一个整体，后面不能直接接“了”。应改为：他第一次试着做饭，味道还不错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他试着了把房间收拾干净。", "corrected_sentence": "他试着把房间收拾干净。", "error_description": "错误：“试着”后面不能直接接“了”，“试着”要直接接后面的动作。应改为：他试着把房间收拾干净。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
