INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96455, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "像下面这些的东西，说几个例子。", "primary_collocate": null, "pronunciation": "zhū rú", "ipa": "tʂu˥ ʐu˧˥", "syllable_count": 2, "sentences": [{"text": "我喜欢水果，诸如苹果、香蕉和西瓜。", "target_word": "诸如", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他会说很多语言，诸如英语、法语和日语。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有很多蔬菜，诸如白菜、土豆和西红柿。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有各种动物，诸如猴子、老虎和熊猫。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多食物，诸如鱼、鸡蛋和牛奶，都对身体很好。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有很多运动，诸如跑步、游泳和打球。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了很多文具，诸如笔、本子和尺子。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去过很多国家，诸如日本、美国和法国。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的花很多，诸如桃花、梨花和樱花。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爱好很多，诸如看书、画画和唱歌。", "target_word": "诸如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诸如此类", "label": "复合"}], "register": "书面", "sense_fingerprint": "放在列举的例子前，说明下面几项只是同类事物中的几个例子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4a1f6f-7ab9-4f4b-aa6d-3fc7424745ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诸如", "is_correct": true, "explanation": "“诸如”引出同类事物中的几个例子，这里列举水果中的苹果、香蕉和西瓜。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物或机器，不能修理水果。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场地，不能打扫水果。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”与前句的“喜欢”矛盾，前后意思不通。"}], "explanations": {"诸如": "“诸如”引出同类事物中的几个例子，这里列举水果中的苹果、香蕉和西瓜。", "修理": "搭配：“修理”的对象是器物或机器，不能修理水果。", "打扫": "搭配：“打扫”的对象是房间、场地，不能打扫水果。", "批评": "语义：“批评”与前句的“喜欢”矛盾，前后意思不通。"}, "sentence_index": 0, "correct_answer": "诸如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子诸如他的父亲，很聪明。", "explanation": "这里应该用〈像〉。诸如只用于列举同类事物中的几例，不表示相似；说某人像另一人要用“像”或“跟…一样”。"}, {"text": "学校只有三个社团，诸如音乐社、美术社和篮球社。", "explanation": "这里应该用〈分别是〉。诸如用于列举同类事物中的几例，暗示还有其他的；前文说“只有三个”，是全部，应说“分别是”。"}, {"text": "公园里有猴子、老虎和熊猫诸如。", "explanation": "这里应该用〈等〉。诸如要放在列举的例子前面，不能放在句末；放在列举之后应用“等”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诸如", "is_correct": true, "explanation": "“诸如”引出同类事物的例子，这里列举文具中的笔、本子和尺子。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能煮笔、本子和尺子。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人或动物，不能喂文具。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”与前句的“买了”矛盾，买和偷不能同时成立。"}], "explanations": {"诸如": "“诸如”引出同类事物的例子，这里列举文具中的笔、本子和尺子。", "煮": "搭配：“煮”的对象是食物，不能煮笔、本子和尺子。", "喂": "搭配：“喂”的对象是人或动物，不能喂文具。", "偷": "语义：“偷”与前句的“买了”矛盾，买和偷不能同时成立。"}, "sentence_index": 6, "correct_answer": "诸如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的爱好很多，唱歌诸如画画，他都喜欢。", "explanation": "这里应该用〈和〉。诸如用于说明某事物所包含的几例，唱歌和画画是并列的两种爱好，应用和连接，不能用诸如。"}, {"text": "他的爱好很多，诸如唱歌一样，他都喜欢。", "explanation": "这里应该用〈像〉。诸如只用于列举同类事物中的几例，不表示相似；说某事像另一事一样要用“像”或“跟…一样”。"}, {"text": "他的爱好很少，诸如看书、画画和唱歌。", "explanation": "这里应该用〈只有〉。诸如暗示列出的只是许多同类事物中的几例，与“很少”的限定矛盾；说明数量少要用“只有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
