INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96459, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有轮子，能带人走的东西。", "primary_collocate": null, "pronunciation": "chē zi", "ipa": "ʈʂʰɤ˥ tsɿ", "syllable_count": 2, "sentences": [{"text": "他的车子停在门口。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车子开得很快。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一辆新车子。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子坏了，我只好坐地铁。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每个周末都洗车子。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子里坐着三个人。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把车子开到前面去。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆红色的车子是我朋友的。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的车子没有油了。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车子修好了，明天可以用。", "target_word": "车子", "complexity_tier": "T3", "furigana": "tā de chē zi xiū hǎo le, míng tiān kě yǐ yòng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "車子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "某个人拥有或使用的、有轮子能载人的一辆车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96459, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "车子", "is_correct": true, "explanation": "车子：chē zi，指有轮子、能载人的东西，与听到的词相符。"}, {"text": "叉子", "is_correct": false, "explanation": "叉子：chā（第一声）与 chē（第一声）只有韵母不同，a 与 e 不同，意思是吃饭用的叉子。"}, {"text": "尺子", "is_correct": false, "explanation": "尺子：chǐ（第三声）与 chē（第一声）韵母不同且声调不同，意思是量长度的尺子。"}, {"text": "池子", "is_correct": false, "explanation": "池子：chí（第二声）与 chē（第一声）韵母不同且声调不同，意思是水池。"}], "explanations": {"车子": "车子：chē zi，指有轮子、能载人的东西，与听到的词相符。", "叉子": "叉子：chā（第一声）与 chē（第一声）只有韵母不同，a 与 e 不同，意思是吃饭用的叉子。", "尺子": "尺子：chǐ（第三声）与 chē（第一声）韵母不同且声调不同，意思是量长度的尺子。", "池子": "池子：chí（第二声）与 chē（第一声）韵母不同且声调不同，意思是水池。"}, "sentence_index": null, "correct_answer": "车子"}, "level_3": {"options": [{"text": "车子", "is_correct": true, "explanation": "车子：有轮子、能载人的车，停在门口的正是它。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能自己停在门口，“停”用于车辆一类能移动的东西。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是固定的建筑，不会“停在门口”。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“停”一般用于车、船等交通工具，不说书包停在门口。"}], "explanations": {"车子": "车子：有轮子、能载人的车，停在门口的正是它。", "桌子": "语义：桌子不能自己停在门口，“停”用于车辆一类能移动的东西。", "房子": "语义：房子是固定的建筑，不会“停在门口”。", "书包": "搭配：“停”一般用于车、船等交通工具，不说书包停在门口。"}, "sentence_index": 0, "correct_answer": "车子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一只车子。", "explanation": "这里应该用〈辆〉。〈只〉用于动物或成对的小东西，车子是车辆，量词要用〈辆〉。"}, {"text": "我昨天买了一本车子。", "explanation": "这里应该用〈辆〉。〈本〉用于书籍，车子要用〈辆〉。"}, {"text": "他去年买了一张车子。", "explanation": "这里应该用〈辆〉。〈张〉用于平面的东西，车子要用〈辆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96459, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "车子", "is_correct": true, "explanation": "车子：chē zi，指有轮子、能载人的东西，与听到的词相符。"}, {"text": "车次", "is_correct": false, "explanation": "车次：第二个音节声母 cì 与 zi 不同（c 与 z），声调也不同，意思是列车的编号。"}, {"text": "厨子", "is_correct": false, "explanation": "厨子：chú（第二声）与 chē（第一声）韵母与声调都不同，意思是做饭的人。"}, {"text": "折子", "is_correct": false, "explanation": "折子：zhé（第二声）与 chē 声母不同（zh 与 ch），声调也不同，意思是存折。"}], "explanations": {"车子": "车子：chē zi，指有轮子、能载人的东西，与听到的词相符。", "车次": "车次：第二个音节声母 cì 与 zi 不同（c 与 z），声调也不同，意思是列车的编号。", "厨子": "厨子：chú（第二声）与 chē（第一声）韵母与声调都不同，意思是做饭的人。", "折子": "折子：zhé（第二声）与 chē 声母不同（zh 与 ch），声调也不同，意思是存折。"}, "sentence_index": null, "correct_answer": "车子"}, "level_3": {"options": [{"text": "车子", "is_correct": true, "explanation": "车子：能被开、能移动的交通工具，正是要开到前面的东西。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“开”用于车、船等交通工具，不说开椅子。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能被驾驶，也不能“开到前面去”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不会自己被开到前面去。"}], "explanations": {"车子": "车子：能被开、能移动的交通工具，正是要开到前面的东西。", "椅子": "搭配：“开”用于车、船等交通工具，不说开椅子。", "垃圾": "语义：垃圾不能被驾驶，也不能“开到前面去”。", "冰箱": "语义：冰箱是家用电器，不会自己被开到前面去。"}, "sentence_index": 6, "correct_answer": "车子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我国的车子工业发展很快。", "explanation": "这里应该用〈汽车〉。“车子”不能修饰“工业”，固定说法是“汽车工业”。"}, {"text": "我们把自行车停进了车子。", "explanation": "这里应该用〈车库〉。“车子”指车辆本身，不指停放车辆的地方，停车的地方要说“车库”。"}, {"text": "车子司机每天很辛苦。", "explanation": "这里应该用〈司机〉。“车子司机”不是固定说法，直接说“司机”即可，不必指明车型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸昨天买了一只车子。", "corrected_sentence": "爸爸昨天买了一辆车子。", "error_description": "量词错误：“车子”是车辆，应用量词“辆”。“只”用于动物或成对的小东西，应说“一辆车子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆车子开很稳。", "corrected_sentence": "那辆车子开得很稳。", "error_description": "补语错误：“开”和补语“很稳”之间缺少结构助词“得”，应说“开得很稳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
