INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "车辆的通称。", "primary_collocate": null, "pronunciation": "chē zi", "ipa": "ʈʂʰɤ˥ tsɿ", "syllable_count": 2, "sentences": [{"text": "路上有很多车子，有大的，也有小的。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车、出租车都是车子。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路只让车子走，人不能走。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上的车子越来越多。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时要看看有没有车子。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的车子多，空气不太好。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥上堵满了车子。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有很多车子在等红灯。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子喜欢画各种各样的车子。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，车子开得比较慢。", "target_word": "车子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "車子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "各种车辆的总称，泛指路上的车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96460, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "车子", "is_correct": true, "explanation": "车子：chē zi，指路上的各种车辆，与听到的词相符。"}, {"text": "车次", "is_correct": false, "explanation": "车次：第二个音节声母 cì 与 zi 不同（c 与 z），声调也不同，意思是列车的编号。"}, {"text": "厨子", "is_correct": false, "explanation": "厨子：chú（第二声）与 chē（第一声）韵母与声调都不同，意思是做饭的人。"}, {"text": "折子", "is_correct": false, "explanation": "折子：zhé（第二声）与 chē 声母不同（zh 与 ch），声调也不同，意思是存折。"}], "explanations": {"车子": "车子：chē zi，指路上的各种车辆，与听到的词相符。", "车次": "车次：第二个音节声母 cì 与 zi 不同（c 与 z），声调也不同，意思是列车的编号。", "厨子": "厨子：chú（第二声）与 chē（第一声）韵母与声调都不同，意思是做饭的人。", "折子": "折子：zhé（第二声）与 chē 声母不同（zh 与 ch），声调也不同，意思是存折。"}, "sentence_index": null, "correct_answer": "车子"}, "level_3": {"options": [{"text": "车子", "is_correct": true, "explanation": "车子：泛指路上的各种车辆，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：路上不会有很多桌子，句子说的是路上的车辆。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会成堆出现在路上，也没有“有大的，也有小的”这种说法。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不可数，不说“路上有很多空气”，也不说“有大的，也有小的”。"}], "explanations": {"车子": "车子：泛指路上的各种车辆，符合句意。", "桌子": "语义：路上不会有很多桌子，句子说的是路上的车辆。", "椅子": "语义：椅子不会成堆出现在路上，也没有“有大的，也有小的”这种说法。", "空气": "搭配：空气不可数，不说“路上有很多空气”，也不说“有大的，也有小的”。"}, "sentence_index": 0, "correct_answer": "车子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路上跑过一只车子。", "explanation": "这里应该用〈辆〉。〈只〉用于动物或成对的小东西，车子是车辆，量词用〈辆〉。"}, {"text": "墙角停着一支车子。", "explanation": "这里应该用〈辆〉。〈支〉用于细长的东西，车子要用〈辆〉。"}, {"text": "我们小区新来了一张车子。", "explanation": "这里应该用〈辆〉。〈张〉用于平面的东西，车子要用〈辆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96460, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "车子", "is_correct": true, "explanation": "车子：chē zi，指路上的各种车辆，与听到的词相符。"}, {"text": "叉子", "is_correct": false, "explanation": "叉子：chā（第一声）与 chē（第一声）只有韵母不同，a 与 e 不同，意思是叉子。"}, {"text": "尺子", "is_correct": false, "explanation": "尺子：chǐ（第三声）与 chē（第一声）韵母与声调都不同，意思是量长度的尺子。"}, {"text": "池子", "is_correct": false, "explanation": "池子：chí（第二声）与 chē（第一声）韵母与声调都不同，意思是水池。"}], "explanations": {"车子": "车子：chē zi，指路上的各种车辆，与听到的词相符。", "叉子": "叉子：chā（第一声）与 chē（第一声）只有韵母不同，a 与 e 不同，意思是叉子。", "尺子": "尺子：chǐ（第三声）与 chē（第一声）韵母与声调都不同，意思是量长度的尺子。", "池子": "池子：chí（第二声）与 chē（第一声）韵母与声调都不同，意思是水池。"}, "sentence_index": null, "correct_answer": "车子"}, "level_3": {"options": [{"text": "车子", "is_correct": true, "explanation": "车子：堵在桥上的车辆，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会堵在桥上，句子说的是堵满的车辆。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“堵满”用于车辆、人群，花应说“开满”，不说堵满花。"}, {"text": "树", "is_correct": false, "explanation": "语义：树是长在地上的植物，不会堵在桥上。"}], "explanations": {"车子": "车子：堵在桥上的车辆，符合句意。", "桌子": "语义：桌子不会堵在桥上，句子说的是堵满的车辆。", "花": "搭配：“堵满”用于车辆、人群，花应说“开满”，不说堵满花。", "树": "语义：树是长在地上的植物，不会堵在桥上。"}, "sentence_index": 6, "correct_answer": "车子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车子司机需要有驾照。", "explanation": "这里应该用〈汽车〉。“车子司机”不是固定说法，开汽车的人要说“汽车司机”。"}, {"text": "他把摩托车停进了车子。", "explanation": "这里应该用〈车库〉。“车子”是车辆的通称，不指停车的地方，停放车辆要说“车库”。"}, {"text": "我在车子站等公共汽车。", "explanation": "这里应该用〈车站〉。“车子站”不是固定说法，等车的地方要说“车站”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路边停着一只车子。", "corrected_sentence": "路边停着一辆车子。", "error_description": "量词错误：车子泛指各种车辆，量词应用“辆”，不用“只”（“只”用于动物或成对的东西），应说“一辆车子”，不说“一只车子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路上的车子开很慢。", "corrected_sentence": "路上的车子开得很慢。", "error_description": "补语错误：“开”和补语“很慢”之间缺少结构助词“得”，应说“开得很慢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
