INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96461, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己的东西给了别人，以后归别人。", "primary_collocate": null, "pronunciation": "zhuǎn ràng", "ipa": "ʈʂwan˨˩ ʐɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他把旧车转让给了朋友。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我要搬家，所以想转让这台冰箱。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店要转让，价格不高。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把自己的房子转让给了弟弟。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张音乐会的票我不能去了，想转让给别人。", "target_word": "转让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转让了那辆自行车，没有再买新的。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家前，她把那台旧电视转让给了邻居。", "target_word": "转让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板老了，把饭馆转让给了年轻人。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套二手沙发便宜转让，欢迎来看。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想转让手机，因为已经买了新的。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "转让了", "label": "体标"}, {"form": "转让过", "label": "体标"}, {"form": "转让费", "label": "复合"}, {"form": "转让人", "label": "复合"}], "register": "中性", "sense_fingerprint": "转让（动词）：把车、房子、店铺等自己的东西让给别人，之后归别人所有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96461, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转让", "is_correct": true, "explanation": "“转让”指把自己的东西让给别人、归对方所有，与“把旧车给了朋友”相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”指把坏的东西修好，不能说把车修理给朋友。"}, {"text": "复制", "is_correct": false, "explanation": "语义：“复制”指做出一样的副本，原车仍在他手里，与“给了朋友”不符。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”指制造新东西，与“把已有的旧车交给朋友”不合。"}], "explanations": {"转让": "“转让”指把自己的东西让给别人、归对方所有，与“把旧车给了朋友”相符。", "修理": "搭配：“修理”指把坏的东西修好，不能说把车修理给朋友。", "复制": "语义：“复制”指做出一样的副本，原车仍在他手里，与“给了朋友”不符。", "生产": "语义：“生产”指制造新东西，与“把已有的旧车交给朋友”不合。"}, "sentence_index": 0, "correct_answer": "转让"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这本书转让给朋友看了两天。", "explanation": "这里应该用〈借〉。转让后东西归对方所有，只让别人用一段时间要用〈借〉。"}, {"text": "我借的书要按时转让给图书馆。", "explanation": "这里应该用〈归还〉。书本属于图书馆，要还回去，不是转让给它。"}, {"text": "她把弟弟转让给了朋友。", "explanation": "这个词不这么用。在此义项中，转让的对象是自己的东西，弟弟是人，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转让", "is_correct": true, "explanation": "“转让”指把东西让给别人、归对方所有，与“把旧电视给了邻居”相符。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”指拿回来，与“给了邻居”的方向相反。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋等空间，不能说把电视装修给邻居。"}, {"text": "颁布", "is_correct": false, "explanation": "语义：“颁布”指正式公布法令或规定，与一台旧电视无关。"}], "explanations": {"转让": "“转让”指把东西让给别人、归对方所有，与“把旧电视给了邻居”相符。", "收回": "语义：“收回”指拿回来，与“给了邻居”的方向相反。", "装修": "搭配：“装修”用于房屋等空间，不能说把电视装修给邻居。", "颁布": "语义：“颁布”指正式公布法令或规定，与一台旧电视无关。"}, "sentence_index": 6, "correct_answer": "转让"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这笔钱转让给了孤儿院，希望能帮助更多孩子。", "explanation": "这里应该用〈捐〉。转让是把自己的财产或权利交给对方、对方从此拥有；把钱无偿送给公益机构要用〈捐〉。"}, {"text": "他把这套房子转让给了银行，三年后还款才能赎回。", "explanation": "这里应该用〈抵押〉。转让是把权利彻底交给对方，抵押只是用作担保，还款后还能赎回。"}, {"text": "他想把自己的快乐转让给朋友。", "explanation": "这里应该用〈分享〉。转让是把实物或权利交给对方、归对方所有；把快乐与朋友共享要用〈分享〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧电脑转让了给表哥。", "corrected_sentence": "他把旧电脑转让给了表哥。", "error_description": "错误在于“转让”后面“了”的位置。应说“转让给了表哥”，“了”要放在“给”后面，不能说“转让了给表哥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想转让了那部旧手机，因为买了新的。", "corrected_sentence": "她想转让那部旧手机，因为买了新的。", "error_description": "错误在于“转让”后面多出了“了”。“想”后面的动词不能直接带“了”，应说“想转让那部旧手机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
