INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96462, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己的东西、权利等让给他人。", "primary_collocate": null, "pronunciation": "zhuǎn ràng", "ipa": "ʈʂwan˨˩ ʐɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他把权利转让给了儿子。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司老板转让了一部分股份。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作者把这本书的版权转让给了出版社。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地的使用权不能随便转让。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她签了合同，把专利转让给公司。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有对方同意，你不能转让这份合同。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想把自己的股票转让给朋友。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人把公司的管理权转让给了女儿。", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项技术的所有权已经转让给了那家公司。", "target_word": "转让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房合同可以转让给别人吗？", "target_word": "转让", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "转让了", "label": "体标"}, {"form": "转让过", "label": "体标"}, {"form": "转让费", "label": "复合"}, {"form": "转让人", "label": "复合"}], "register": "中性", "sense_fingerprint": "转让（动词）：把权利、股份、版权、合同等让给他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转让", "is_correct": true, "explanation": "“转让”指把权利让给他人，与“把权利给了儿子”相符。"}, {"text": "修复", "is_correct": false, "explanation": "搭配：“修复”用于损坏的物品或关系，不能用来说修复权利。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：“挖掘”指从地下或深处取出，与把权利交给儿子不符。"}, {"text": "切断", "is_correct": false, "explanation": "语义：“切断”指割断或中断，与把权利交给别人的意思相反。"}], "explanations": {"转让": "“转让”指把权利让给他人，与“把权利给了儿子”相符。", "修复": "搭配：“修复”用于损坏的物品或关系，不能用来说修复权利。", "挖掘": "语义：“挖掘”指从地下或深处取出，与把权利交给儿子不符。", "切断": "语义：“切断”指割断或中断，与把权利交给别人的意思相反。"}, "sentence_index": 0, "correct_answer": "转让"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间房子转让给学生住一年。", "explanation": "这里应该用〈出租〉。转让后权利归对方，不能只让人住一年。只出借一段时间要用〈出租〉。"}, {"text": "他把这笔存款转让给了山区小学，帮助孩子们读书。", "explanation": "这里应该用〈捐〉。转让是把财产或权利交给对方、对方从此拥有；把存款无偿捐给学校要用〈捐〉。"}, {"text": "她想把自己的笑容转让给朋友。", "explanation": "这里应该用〈分享〉。转让用于股份、权利这类可以交出去的东西；笑容是表情，与朋友分享要用〈分享〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转让", "is_correct": true, "explanation": "“转让”指把股票等财产让给别人，与“想把股票给朋友”相符。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”指弄碎，股票不能被弄碎后送给朋友，与句意不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于股票。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦拭表面，股票不能被擦后交给朋友。"}], "explanations": {"转让": "“转让”指把股票等财产让给别人，与“想把股票给朋友”相符。", "粉碎": "语义：“粉碎”指弄碎，股票不能被弄碎后送给朋友，与句意不符。", "煮": "搭配：“煮”的对象是食物，不能用于股票。", "擦": "搭配：“擦”用于擦拭表面，股票不能被擦后交给朋友。"}, "sentence_index": 6, "correct_answer": "转让"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我借来的这套设备，要按时转让给学校。", "explanation": "这里应该用〈归还〉。借来的东西不是自己的，按时还回去要用〈归还〉，不能用“转让”。"}, {"text": "他把自己的生日转让给了朋友。", "explanation": "这个词不这么用。生日不是可以交给别人的财产或权利，不能用“转让”。"}, {"text": "这块地转让给了银行做担保，三年后还款才能赎回。", "explanation": "这里应该用〈抵押〉。转让是把权利彻底交给对方，抵押只是用作担保，还款后还能赎回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把专利使用权转让了公司。", "corrected_sentence": "他把专利使用权转让给了公司。", "error_description": "错误在于漏掉了“给”。“转让”后面带接收方时要说“转让给”，应说“转让给了公司”，不能说“转让了公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想把旧股票转让到表姐。", "corrected_sentence": "她想把旧股票转让给表姐。", "error_description": "错误在于介词用错。“转让”引出接收人时要用“给”。“转让到”通常接“某人名下”，直接说“转让到表姐”不自然，应说“转让给表姐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96463, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清醒", "is_correct": true, "explanation": "清醒：神志清楚，与“醉”（饮酒后神志不清）意义相反。"}, {"text": "疲惫", "is_correct": false, "explanation": "疲惫：指累、没有精神，与“醉”不构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "干净：指不脏，与“醉”不构成反义。"}, {"text": "健康", "is_correct": false, "explanation": "健康：指身体好，与“醉”不构成反义。"}], "correct_answer": "清醒", "explanations": {"清醒": "清醒：神志清楚，与“醉”（饮酒后神志不清）意义相反。", "疲惫": "疲惫：指累、没有精神，与“醉”不构成反义。", "干净": "干净：指不脏，与“醉”不构成反义。", "健康": "健康：指身体好，与“醉”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96463, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清醒", "is_correct": true, "explanation": "清醒：神志清楚，与“醉”（饮酒后神志不清）意义相反。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞：指空间大，与“醉”不构成反义。"}, {"text": "响亮", "is_correct": false, "explanation": "响亮：指声音大，与“醉”不构成反义。"}, {"text": "年轻", "is_correct": false, "explanation": "年轻：指年龄小，与“醉”不构成反义。"}], "correct_answer": "清醒", "explanations": {"清醒": "清醒：神志清楚，与“醉”（饮酒后神志不清）意义相反。", "宽敞": "宽敞：指空间大，与“醉”不构成反义。", "响亮": "响亮：指声音大，与“醉”不构成反义。", "年轻": "年轻：指年龄小，与“醉”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96463, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "喝了太多酒，走路不稳，脑子也不清楚。", "primary_collocate": null, "pronunciation": "zuì", "ipa": "tswei̯˥˩", "syllable_count": 1, "sentences": [{"text": "他喝醉了，走路都不稳。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸昨晚醉了，一回家就睡着了。", "target_word": "醉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他醉得连家都找不到了。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别开车，你已经醉了。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个醉了的人在路边唱歌。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一杯酒就醉了。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝醉的朋友说了很多胡话。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他醉得站不起来。", "target_word": "醉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我没醉，我还能走回家。", "target_word": "醉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "醉了以后，他什么都不记得了。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "醉了", "label": "体标"}, {"form": "醉过", "label": "体标"}, {"form": "喝醉", "label": "复合"}, {"form": "醉酒", "label": "复合"}], "register": "通用", "sense_fingerprint": "喝酒过多，走路不稳、头脑不清", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96463, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "醉", "is_correct": true, "explanation": "醉（zuì，第四声）：饮酒过量、神志不清，是本词的意思。"}, {"text": "嘴", "is_correct": false, "explanation": "嘴（zuǐ，第三声）与醉（zuì，第四声）声调不同，意思是嘴巴。"}, {"text": "脆", "is_correct": false, "explanation": "脆（cuì）与醉的声母不同（c 与 z），意思是易碎、清脆。"}, {"text": "岁", "is_correct": false, "explanation": "岁（suì）与醉的声母不同（s 与 z），意思是年龄的单位。"}], "explanations": {"醉": "醉（zuì，第四声）：饮酒过量、神志不清，是本词的意思。", "嘴": "嘴（zuǐ，第三声）与醉（zuì，第四声）声调不同，意思是嘴巴。", "脆": "脆（cuì）与醉的声母不同（c 与 z），意思是易碎、清脆。", "岁": "岁（suì）与醉的声母不同（s 与 z），意思是年龄的单位。"}, "sentence_index": null, "correct_answer": "醉"}, "level_3": {"options": [{"text": "醉", "is_correct": true, "explanation": "醉：“喝醉了”的正确形式，与后文“走路都不稳”相符。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”说饮料的温度，“喝凉了”与“走路都不稳”的醉态无关，句意不通。"}, {"text": "撑", "is_correct": false, "explanation": "搭配：“撑”说吃喝后肚子胀，不与“走路都不稳”的醉态相合。"}, {"text": "累", "is_correct": false, "explanation": "语义：“累”指疲劳，与“走路都不稳”所说的醉酒情形不符。"}], "explanations": {"醉": "醉：“喝醉了”的正确形式，与后文“走路都不稳”相符。", "凉": "语义：“凉”说饮料的温度，“喝凉了”与“走路都不稳”的醉态无关，句意不通。", "撑": "搭配：“撑”说吃喝后肚子胀，不与“走路都不稳”的醉态相合。", "累": "语义：“累”指疲劳，与“走路都不稳”所说的醉酒情形不符。"}, "sentence_index": 0, "correct_answer": "醉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完步很醉，一直坐着不动。", "explanation": "这里应该用〈累〉。醉指饮酒过量，身体疲劳要用“累”。"}, {"text": "他在陌生的城市醉了路，怎么也找不到家。", "explanation": "这里应该用〈迷〉。醉指饮酒过量，走错路要用“迷”，不能说“醉了路”。"}, {"text": "这辆车醉了，司机要停下来。", "explanation": "这里是把“醉”当成了“机器失灵”的意思。醉只用于人饮酒过量，车出故障不能说“醉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96463, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "醉", "is_correct": true, "explanation": "醉（zuì，第四声）：饮酒过量、神志不清，是本词的意思。"}, {"text": "翠", "is_correct": false, "explanation": "翠（cuì）与醉的声母不同（c 与 z），意思是翠绿色。"}, {"text": "碎", "is_correct": false, "explanation": "碎（suì）与醉的声母不同（s 与 z），意思是破碎。"}, {"text": "坠", "is_correct": false, "explanation": "坠（zhuì）与醉的声母不同（zh 与 z），意思是掉落。"}], "explanations": {"醉": "醉（zuì，第四声）：饮酒过量、神志不清，是本词的意思。", "翠": "翠（cuì）与醉的声母不同（c 与 z），意思是翠绿色。", "碎": "碎（suì）与醉的声母不同（s 与 z），意思是破碎。", "坠": "坠（zhuì）与醉的声母不同（zh 与 z），意思是掉落。"}, "sentence_index": null, "correct_answer": "醉"}, "level_3": {"options": [{"text": "醉", "is_correct": true, "explanation": "醉：“喝醉的”的正确形式，句意是醉酒的朋友说胡话。"}, {"text": "呛", "is_correct": false, "explanation": "搭配：“喝呛”指喝东西时被呛到，不指醉酒，句意不合。"}, {"text": "渴", "is_correct": false, "explanation": "语义：“渴”指想喝水，不能与“喝”组成“喝渴”，“喝渴的朋友”句意不通。"}, {"text": "惯", "is_correct": false, "explanation": "语义：“喝惯”指习惯饮酒，与“说胡话”没有关系，句意不合。"}], "explanations": {"醉": "醉：“喝醉的”的正确形式，句意是醉酒的朋友说胡话。", "呛": "搭配：“喝呛”指喝东西时被呛到，不指醉酒，句意不合。", "渴": "语义：“渴”指想喝水，不能与“喝”组成“喝渴”，“喝渴的朋友”句意不通。", "惯": "语义：“喝惯”指习惯饮酒，与“说胡话”没有关系，句意不合。"}, "sentence_index": 6, "correct_answer": "醉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人年纪大了，说话常常醉。", "explanation": "这里应该用〈糊涂〉。醉指饮酒过量，年老记忆不清要用“糊涂”。"}, {"text": "他被阳光晃得头有点醉。", "explanation": "这里应该用〈晕〉。醉是饮酒引起的，被光线刺激而头晕要用“晕”。"}, {"text": "他发烧烧得醉过去了。", "explanation": "这里应该用〈昏〉。醉指饮酒后神志不清，发烧失去知觉要用“昏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天醉喝了，今天还头疼。", "corrected_sentence": "他昨天喝醉了，今天还头疼。", "error_description": "错误在“喝醉”的语序颠倒。“醉”是结果补语，应放在动词“喝”之后，说“喝醉”，不能说“醉喝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喝醉得以后，说话都不清楚。", "corrected_sentence": "他喝醉以后，说话都不清楚。", "error_description": "错误在“醉”后面多加了“得”。“醉”作结果补语时不带“得”；“醉得”只用于后接程度补语的句子，此处应说“喝醉以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96464, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清醒", "is_correct": true, "explanation": "清醒：神志清楚，与“醉”（饮酒后神志不清）意义相反。"}, {"text": "疲惫", "is_correct": false, "explanation": "疲惫：指累、没有精神，与“醉”不构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "干净：指不脏，与“醉”不构成反义。"}, {"text": "健康", "is_correct": false, "explanation": "健康：指身体好，与“醉”不构成反义。"}], "correct_answer": "清醒", "explanations": {"清醒": "清醒：神志清楚，与“醉”（饮酒后神志不清）意义相反。", "疲惫": "疲惫：指累、没有精神，与“醉”不构成反义。", "干净": "干净：指不脏，与“醉”不构成反义。", "健康": "健康：指身体好，与“醉”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96464, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清醒", "is_correct": true, "explanation": "清醒：神志清楚，与“醉”（饮酒后神志不清）意义相反。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞：指空间大，与“醉”不构成反义。"}, {"text": "响亮", "is_correct": false, "explanation": "响亮：指声音大，与“醉”不构成反义。"}, {"text": "年轻", "is_correct": false, "explanation": "年轻：指年龄小，与“醉”不构成反义。"}], "correct_answer": "清醒", "explanations": {"清醒": "清醒：神志清楚，与“醉”（饮酒后神志不清）意义相反。", "宽敞": "宽敞：指空间大，与“醉”不构成反义。", "响亮": "响亮：指声音大，与“醉”不构成反义。", "年轻": "年轻：指年龄小，与“醉”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96464, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "饮酒过量而神志不清。", "primary_collocate": null, "pronunciation": "zuì", "ipa": "tswei̯˥˩", "syllable_count": 1, "sentences": [{"text": "昨天的聚会上，大哥醉了。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他醉了，把我当成了他弟弟。", "target_word": "醉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都醉了，只有我还清醒。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每次喝酒都不会醉。", "target_word": "醉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看他醉的样子，我们送他回家吧。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝了两瓶白酒，他有点醉了。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不喝酒，怕醉了出丑。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他醉了以后总是哭。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从没见他醉过。", "target_word": "醉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "醉了的人说的话不能信。", "target_word": "醉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "醉了", "label": "体标"}, {"form": "醉过", "label": "体标"}, {"form": "喝醉", "label": "复合"}, {"form": "醉酒", "label": "复合"}], "register": "通用", "sense_fingerprint": "饮酒过量而神志不清", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96464, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "醉", "is_correct": true, "explanation": "醉（zuì，第四声）：饮酒过量、神志不清，是本词的意思。"}, {"text": "嘴", "is_correct": false, "explanation": "嘴（zuǐ，第三声）与醉（zuì，第四声）声调不同，意思是嘴巴。"}, {"text": "脆", "is_correct": false, "explanation": "脆（cuì）与醉的声母不同（c 与 z），意思是易碎、清脆。"}, {"text": "岁", "is_correct": false, "explanation": "岁（suì）与醉的声母不同（s 与 z），意思是年龄的单位。"}], "explanations": {"醉": "醉（zuì，第四声）：饮酒过量、神志不清，是本词的意思。", "嘴": "嘴（zuǐ，第三声）与醉（zuì，第四声）声调不同，意思是嘴巴。", "脆": "脆（cuì）与醉的声母不同（c 与 z），意思是易碎、清脆。", "岁": "岁（suì）与醉的声母不同（s 与 z），意思是年龄的单位。"}, "sentence_index": null, "correct_answer": "醉"}, "level_3": {"options": [{"text": "醉", "is_correct": true, "explanation": "醉：“醉了”的正确形式，指饮酒过量，与“聚会上”的语境相符。"}, {"text": "酒杯", "is_correct": false, "explanation": "语法：“酒杯”是名词，不能放在“了”前作谓语，“大哥酒杯了”不成句。"}, {"text": "桌子", "is_correct": false, "explanation": "语法：“桌子”是名词，“大哥桌子了”不成句。"}, {"text": "饭菜", "is_correct": false, "explanation": "语法：“饭菜”是名词，不能作谓语，“大哥饭菜了”不成句。"}], "explanations": {"醉": "醉：“醉了”的正确形式，指饮酒过量，与“聚会上”的语境相符。", "酒杯": "语法：“酒杯”是名词，不能放在“了”前作谓语，“大哥酒杯了”不成句。", "桌子": "语法：“桌子”是名词，“大哥桌子了”不成句。", "饭菜": "语法：“饭菜”是名词，不能作谓语，“大哥饭菜了”不成句。"}, "sentence_index": 0, "correct_answer": "醉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他熬夜熬了三天，醉得眼睛都睁不开。", "explanation": "这里应该用〈困〉。醉指饮酒过量，熬夜后困倦要用“困”。"}, {"text": "这瓶酒醉了，不能再喝。", "explanation": "这里是把“醉”当成了“变质”的意思。酒会变质，但不会“醉”；醉只用于人饮酒过量。"}, {"text": "他站起来太快，头有点醉。", "explanation": "这里应该用〈晕〉。醉指饮酒过量，起身后头晕要用“晕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96464, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "醉", "is_correct": true, "explanation": "醉（zuì，第四声）：饮酒过量、神志不清，是本词的意思。"}, {"text": "翠", "is_correct": false, "explanation": "翠（cuì）与醉的声母不同（c 与 z），意思是翠绿色。"}, {"text": "碎", "is_correct": false, "explanation": "碎（suì）与醉的声母不同（s 与 z），意思是破碎。"}, {"text": "坠", "is_correct": false, "explanation": "坠（zhuì）与醉的声母不同（zh 与 z），意思是掉落。"}], "explanations": {"醉": "醉（zuì，第四声）：饮酒过量、神志不清，是本词的意思。", "翠": "翠（cuì）与醉的声母不同（c 与 z），意思是翠绿色。", "碎": "碎（suì）与醉的声母不同（s 与 z），意思是破碎。", "坠": "坠（zhuì）与醉的声母不同（zh 与 z），意思是掉落。"}, "sentence_index": null, "correct_answer": "醉"}, "level_3": {"options": [{"text": "醉", "is_correct": true, "explanation": "醉：“醉了”的正确形式，句意是怕自己喝醉后出丑。"}, {"text": "呛", "is_correct": false, "explanation": "搭配：“呛”指液体进入气管，“怕呛了出丑”不成立，与“不喝酒”的语境不合。"}, {"text": "惯", "is_correct": false, "explanation": "语义：“惯”指习以为常，与“怕出丑”的语境不合，句意不通。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指没有吃饱，与“不喝酒”“怕出丑”的语境无关，句意不通。"}], "explanations": {"醉": "醉：“醉了”的正确形式，句意是怕自己喝醉后出丑。", "呛": "搭配：“呛”指液体进入气管，“怕呛了出丑”不成立，与“不喝酒”的语境不合。", "惯": "语义：“惯”指习以为常，与“怕出丑”的语境不合，句意不通。", "饿": "语义：“饿”指没有吃饱，与“不喝酒”“怕出丑”的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "醉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最近做事很醉，常常出错。", "explanation": "这里应该用〈糊涂〉。醉指饮酒过量，做事不清楚要用“糊涂”。"}, {"text": "他跑了一整天，醉得走不动了。", "explanation": "这里应该用〈累〉。醉指饮酒过量，身体劳累要用“累”。"}, {"text": "他刚从梦中醒来，还很醉。", "explanation": "这里应该用〈迷糊〉。醉指饮酒过量，刚醒时神志模糊要用“迷糊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他第一次醉喝，吐得很厉害。", "corrected_sentence": "他第一次喝醉，吐得很厉害。", "error_description": "错误在“喝醉”的语序颠倒。“醉”是结果补语，应放在动词“喝”之后，说“喝醉”，不能说“醉喝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没醉了过。", "corrected_sentence": "我从没醉过。", "error_description": "错误在“醉”后面同时加了“了”和“过”。表示经历时只用“过”，应说“醉过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
