INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96465, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96465, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于坏事的消息，传出来后大家都知道，很丢脸。", "primary_collocate": null, "pronunciation": "chǒu wén", "ipa": "ʈʂʰoʊ˨˩ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这个丑闻一传出来，大家都知道了。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的丑闻在网上传得很快。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人不想让邻居知道家里的丑闻。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上又登出了一条明星的丑闻。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个丑闻，同事们都很吃惊。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别到处说别人的丑闻，这样不好。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丑闻传开以后，他不好意思出门。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这桩丑闻让全家人都觉得丢脸。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上整天都在说那个丑闻。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不想成为丑闻的主角。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "桩", "label": "量词"}], "register": "中性", "sense_fingerprint": "传开后让人丢脸的坏消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丑闻", "is_correct": true, "explanation": "丑闻：指传开后让人丢脸的坏事，符合“传出来、大家都知道”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“传出来”只能说消息、话语，不能说“天气”。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”是食物，不是可以“传出来、大家都知道”的消息。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，句中说的是传开的消息，不能是钢琴。"}], "explanations": {"丑闻": "丑闻：指传开后让人丢脸的坏事，符合“传出来、大家都知道”的语境。", "天气": "搭配：“传出来”只能说消息、话语，不能说“天气”。", "蔬菜": "语义：“蔬菜”是食物，不是可以“传出来、大家都知道”的消息。", "钢琴": "语义：“钢琴”是乐器，句中说的是传开的消息，不能是钢琴。"}, "sentence_index": 0, "correct_answer": "丑闻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他送给妈妈一件丑闻。", "explanation": "这里应该用〈礼物〉。“丑闻”是不光彩的消息或事件，不能用来“送”，送的应是“礼物”。"}, {"text": "他会说三种丑闻。", "explanation": "这里应该用〈外语〉。“丑闻”指不光彩的消息或事件，不能说“会说”，会说的应是“外语”。"}, {"text": "他获得了丑闻。", "explanation": "这里应该用〈荣誉〉。“丑闻”是不光彩的事，不能说“获得”，获得的应是“荣誉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丑闻", "is_correct": true, "explanation": "丑闻：指传开后让人丢脸的坏事，符合“传开以后，他不好意思出门”的语境。"}, {"text": "喜讯", "is_correct": false, "explanation": "语义：“喜讯”是令人高兴的消息，与“他不好意思出门”的语境相反。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“传开”只能说消息、话语，不能说“钥匙”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是给孩子玩的东西，不是可以传开的事情。"}], "explanations": {"丑闻": "丑闻：指传开后让人丢脸的坏事，符合“传开以后，他不好意思出门”的语境。", "喜讯": "语义：“喜讯”是令人高兴的消息，与“他不好意思出门”的语境相反。", "钥匙": "搭配：“传开”只能说消息、话语，不能说“钥匙”。", "玩具": "语义：“玩具”是给孩子玩的东西，不是可以传开的事情。"}, "sentence_index": 6, "correct_answer": "丑闻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "观众们给演员献上了热烈的丑闻。", "explanation": "这里应该用〈掌声〉。“丑闻”是不光彩的事，不能“献上”和“热烈”，献上的应是“掌声”。"}, {"text": "这是一个感人的丑闻，大家都哭了。", "explanation": "这里应该用〈故事〉。“丑闻”指不光彩的事，不能用来形容感人的内容。"}, {"text": "他这次考试取得了好丑闻。", "explanation": "这里应该用〈成绩〉。“丑闻”是不光彩的事，不能用“好”来形容，取得的应是“好成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他丑闻在朋友圈里传开了。", "corrected_sentence": "他的丑闻在朋友圈里传开了。", "error_description": "名词“丑闻”前的领属性修饰语需要加“的”。漏掉“的”，句子就不通，应说“他的丑闻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块丑闻让整个学校都议论纷纷。", "corrected_sentence": "这桩丑闻让整个学校都议论纷纷。", "error_description": "量词用错。“丑闻”用“桩”，不用“块”（“块”多用于成片的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
