INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96466, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不光彩、使名声受损的事件或消息。", "primary_collocate": null, "pronunciation": "chǒu wén", "ipa": "ʈʂʰoʊ˨˩ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这家公司的丑闻让它失去了很多客户。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一桩丑闻毁了这位市长的名声。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球协会出了一个大丑闻。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者查出了学校招生的丑闻。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起丑闻发生后，经理马上辞职了。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想尽办法掩盖这桩丑闻。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手因为丑闻离开了娱乐圈。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在调查这个丑闻。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了丑闻以后，这家银行的名声一直不好。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次丑闻对球队的影响很大。", "target_word": "丑闻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "桩", "label": "量词"}], "register": "中性", "sense_fingerprint": "损害个人或机构名声的不光彩事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丑闻", "is_correct": true, "explanation": "丑闻：指不光彩、损害名声的事件，符合“让它失去了很多客户”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是能让公司失去客户的事情，句中的原因应是不光彩的事件。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不能是让公司失去客户的原因。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是遮雨的物品，不能使公司失去客户。"}], "explanations": {"丑闻": "丑闻：指不光彩、损害名声的事件，符合“让它失去了很多客户”的语境。", "天气": "语义：“天气”不是能让公司失去客户的事情，句中的原因应是不光彩的事件。", "钢琴": "语义：“钢琴”是乐器，不能是让公司失去客户的原因。", "雨伞": "语义：“雨伞”是遮雨的物品，不能使公司失去客户。"}, "sentence_index": 0, "correct_answer": "丑闻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "记者接受了学校的丑闻。", "explanation": "这里应该用〈采访〉。“丑闻”是不光彩的消息或事件，不能“接受”，接受的应是“采访”。"}, {"text": "学校公开表彰了他的丑闻。", "explanation": "这里应该用〈成绩〉。“丑闻”是不光彩的事，不能被表彰，应说“表彰他的成绩”。"}, {"text": "这次比赛颁发了丑闻。", "explanation": "这里应该用〈奖项〉。“丑闻”是不光彩的事，不能被颁发，颁发的应是“奖项”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丑闻", "is_correct": true, "explanation": "丑闻：指不光彩、损害名声的事件，符合“因为……离开了娱乐圈”的语境。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是日子，不是能让人离开娱乐圈的原因。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“因为……离开”的原因应是事件，不能说“脚步”。"}, {"text": "橡皮", "is_correct": false, "explanation": "语义：“橡皮”是文具，不能作为让人离开娱乐圈的原因。"}], "explanations": {"丑闻": "丑闻：指不光彩、损害名声的事件，符合“因为……离开了娱乐圈”的语境。", "生日": "语义：“生日”是日子，不是能让人离开娱乐圈的原因。", "脚步": "搭配：“因为……离开”的原因应是事件，不能说“脚步”。", "橡皮": "语义：“橡皮”是文具，不能作为让人离开娱乐圈的原因。"}, "sentence_index": 6, "correct_answer": "丑闻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位教练为球队制定了丑闻。", "explanation": "这里应该用〈计划〉。“丑闻”是不光彩的事件，不能被“制定”，制定的应是“计划”。"}, {"text": "这次活动大大提高了学校的丑闻。", "explanation": "这里应该用〈声誉〉。丑闻会损害名声，不能“提高”，提高的是“声誉”。"}, {"text": "这位球员赢得了丑闻。", "explanation": "这里应该用〈冠军〉。“丑闻”是不光彩的事，不能“赢得”，赢得的应是“冠军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只丑闻让那家公司失去了很多客户。", "corrected_sentence": "这桩丑闻让那家公司失去了很多客户。", "error_description": "量词用错。“丑闻”用“桩”，不用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位歌手丑闻在网上传开了。", "corrected_sentence": "这位歌手的丑闻在网上传开了。", "error_description": "名词“丑闻”前的领属性修饰语需要加“的”。漏掉“的”，句子就不通，应说“这位歌手的丑闻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96468, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96468, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96468, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "首次创立；开辟。", "primary_collocate": null, "pronunciation": "kāi chuàng", "ipa": "kʰai˥ tʂʰuaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他三十岁时开创了自己的公司。", "target_word": "开创", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在国外开创了一番新事业。", "target_word": "开创", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家改革开放，开创了新的时代。", "target_word": "开创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人想开创属于自己的生活。", "target_word": "开创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她离开大公司，开创了自己的品牌。", "target_word": "开创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲从零开始，开创了这家小饭店。", "target_word": "开创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的努力开创了新局面。", "target_word": "开创", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起努力，开创美好的未来。", "target_word": "开创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开创过两个公司，但都很小。", "target_word": "开创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市靠新政策开创了发展的新阶段。", "target_word": "开创", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开创了", "label": "完成体"}, {"form": "开创过", "label": "经历体"}, {"form": "开创者", "label": "复合词"}], "register": "书面", "sense_fingerprint": "首次创立公司、事业、时代等并开辟新局面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5192d602-4ef9-4f05-9da9-5f33ac684468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃了自己的公司”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，与“自己的公司”不相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是有形的物品，公司不能擦。"}, {"text": "开创", "is_correct": true, "explanation": "开创指首次创立或开辟，与“三十岁时……自己的公司”相符。"}], "explanations": {"吃": "搭配：“吃”的宾语应是食物，不能说“吃了自己的公司”。", "唱": "语义：“唱”的对象是歌曲，与“自己的公司”不相符。", "擦": "搭配：“擦”的对象是有形的物品，公司不能擦。", "开创": "开创指首次创立或开辟，与“三十岁时……自己的公司”相符。"}, "sentence_index": 0, "correct_answer": "开创"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他开创了窗户。", "explanation": "这里应该用〈打开〉。开创指首次创立或开辟新局面，不能用来说打开窗户这样的具体动作。"}, {"text": "他进门就开创了空调。", "explanation": "这里应该用〈开〉（开空调）。空调是已有的电器，开机只是启动，不是首次创立新事物，不能说“开创”。"}, {"text": "她开创了抽屉。", "explanation": "这里应该用〈拉开〉。抽屉是已有的家具部件，拉开只是打开，不是首次创立，不能说“开创”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮料，不能说“喝了新局面”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是具体的物品，“局面”是抽象的，不能洗。"}, {"text": "锁", "is_correct": false, "explanation": "搭配：“锁”的对象是门、箱子等，不能说“锁了新局面”。"}, {"text": "开创", "is_correct": true, "explanation": "开创指开辟新局面，与“他们的努力”和“新局面”相符。"}], "explanations": {"喝": "搭配：“喝”的宾语应是饮料，不能说“喝了新局面”。", "洗": "语义：“洗”的对象是具体的物品，“局面”是抽象的，不能洗。", "锁": "搭配：“锁”的对象是门、箱子等，不能说“锁了新局面”。", "开创": "开创指开辟新局面，与“他们的努力”和“新局面”相符。"}, "sentence_index": 6, "correct_answer": "开创"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校每周开创图书馆。", "explanation": "这里应该用〈开放〉。图书馆已经存在，只是定时对外开放，应说〈开放〉；开创指首次创立。"}, {"text": "司机开创了汽车。", "explanation": "这里应该用〈开动〉。汽车已经存在，只是发动运转，应说〈开动〉，不能说“开创汽车”。"}, {"text": "市政府开创了新大楼。", "explanation": "这里应该用〈启用〉。大楼已经建好，只是投入使用，应说〈启用〉；开创指首次创立前人没有的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们开创了过自己的道路。", "corrected_sentence": "他们开创了自己的道路。", "error_description": "错误形式“开创了过”，正确形式“开创了”。“了”表示完成，“过”表示经历，两者不能同用；应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在开创了新局面。", "corrected_sentence": "他们正在开创新局面。", "error_description": "“正在”表示动作进行，不能与“了”同用；应去掉“了”，说“他们正在开创新局面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96469, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
