INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96473, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "告诉", "is_correct": true, "explanation": "反义：告诉指把事情说给别人知道，与“隐瞒”相对。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：打扫指清除垃圾、灰尘，与隐瞒无关。"}, {"text": "雕刻", "is_correct": false, "explanation": "无关：雕刻指在材料上刻画图形，与隐瞒无关。"}, {"text": "刷洗", "is_correct": false, "explanation": "无关：刷洗指用刷子清洗物体，与隐瞒无关。"}], "correct_answer": "告诉", "explanations": {"告诉": "反义：告诉指把事情说给别人知道，与“隐瞒”相对。", "打扫": "无关：打扫指清除垃圾、灰尘，与隐瞒无关。", "雕刻": "无关：雕刻指在材料上刻画图形，与隐瞒无关。", "刷洗": "无关：刷洗指用刷子清洗物体，与隐瞒无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96473, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "知道一件事，却不告诉别人。", "primary_collocate": null, "pronunciation": "yǐn mán", "ipa": "in˨˩˦ man˧˥", "syllable_count": 2, "sentences": [{"text": "他早就知道，却一直隐瞒着我们。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她知道朋友的秘密，却对谁都隐瞒。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么对我隐瞒这件事？", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他知道钱在哪儿，却隐瞒不说。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想隐瞒你，其实我早就知道了。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道你的计划，却向大家隐瞒了。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间不应该互相隐瞒。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥看见了一切，却向父母隐瞒了。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她隐瞒了自己知道的消息。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这个秘密隐瞒了很多年。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐瞒了", "label": "完成体"}, {"form": "隐瞒着", "label": "持续体"}, {"form": "隐瞒过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "明明知情却不对某人说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5192d602-4ef9-4f05-9da9-5f33ac684468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96473, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隐瞒", "is_correct": true, "explanation": "正确：“却一直隐瞒着我们”表示明明知情却不说，与句意一致。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：烹饪用于食物，不能用于人。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：饲养用于动物，不能用于人。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏指用乐器奏乐，与人无关。"}], "explanations": {"隐瞒": "正确：“却一直隐瞒着我们”表示明明知情却不说，与句意一致。", "烹饪": "搭配：烹饪用于食物，不能用于人。", "饲养": "搭配：饲养用于动物，不能用于人。", "演奏": "语义：演奏指用乐器奏乐，与人无关。"}, "sentence_index": 0, "correct_answer": "隐瞒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他隐瞒了那把旧椅子。", "explanation": "这里应该用〈修理〉。隐瞒针对需要保密的事情，不能用于修理物品，椅子坏了要用修理。"}, {"text": "妈妈轻轻隐瞒受伤的孩子。", "explanation": "这里应该用〈安慰〉。隐瞒是对事实不说出来，不能用于对人的关心。"}, {"text": "我们每天隐瞒教室。", "explanation": "这里应该用〈打扫〉。隐瞒是不让人知道事情，不能用于清理场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐瞒", "is_correct": true, "explanation": "正确：“互相隐瞒”指彼此不说真相，与“朋友之间不应该”的语境相符。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种指撒种子，朋友之间不能互相播种。"}, {"text": "烘焙", "is_correct": false, "explanation": "搭配：烘焙用于面包、糕点等食物，不能用于人际关系。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：驯养用于动物，不能用于朋友。"}], "explanations": {"隐瞒": "正确：“互相隐瞒”指彼此不说真相，与“朋友之间不应该”的语境相符。", "播种": "语义：播种指撒种子，朋友之间不能互相播种。", "烘焙": "搭配：烘焙用于面包、糕点等食物，不能用于人际关系。", "驯养": "搭配：驯养用于动物，不能用于朋友。"}, "sentence_index": 6, "correct_answer": "隐瞒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他隐瞒了一场大雨。", "explanation": "这里应该用〈经历〉。隐瞒针对需要保密的事情，天气是客观现象，不能隐瞒，只能经历。"}, {"text": "园丁每天隐瞒花草。", "explanation": "这里应该用〈修剪〉。隐瞒用于事情或真相，不能用于照料植物。"}, {"text": "我们隐瞒了故宫。", "explanation": "这里应该用〈游览〉。隐瞒用于事情或真相，不能用于参观地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们从来没有隐瞒了你。", "corrected_sentence": "我们从来没有隐瞒过你。", "error_description": "错误形式是“没有……了”，正确形式是“没有……过”。否定过去的经历要用“没有……过”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她隐瞒很好，一句话也不说。", "corrected_sentence": "她隐瞒得很好，一句话也不说。", "error_description": "错误形式是“隐瞒很好”，正确形式是“隐瞒得很好”。“隐瞒”后要用“得”引出程度补语，少了“得”句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
