INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有意掩盖真相，不让别人知道。", "primary_collocate": null, "pronunciation": "yǐn mán", "ipa": "in˨˩˦ man˧˥", "syllable_count": 2, "sentences": [{"text": "他向警察隐瞒了真相。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司隐瞒了产品的问题。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想隐瞒自己的年龄。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生不应该对病人隐瞒病情。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他隐瞒着事故的原因，不肯说出来。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你不要再隐瞒了。", "target_word": "隐瞒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他隐瞒过自己的过去。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板故意隐瞒收入，少交了税。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把失败的消息隐瞒了很久。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他隐瞒真相，只是怕大家生气。", "target_word": "隐瞒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐瞒了", "label": "完成体"}, {"form": "隐瞒着", "label": "持续体"}, {"form": "隐瞒过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "故意掩盖真相或事实，不让别人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5192d602-4ef9-4f05-9da9-5f33ac684468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隐瞒", "is_correct": true, "explanation": "正确：隐瞒指有意掩盖真相，与“真相”搭配，符合句意。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：修补用于器物、关系，真相不能被修补。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种指撒下种子，与“真相”无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赏识美好的事物，与“真相”不合。"}], "explanations": {"隐瞒": "正确：隐瞒指有意掩盖真相，与“真相”搭配，符合句意。", "修补": "搭配：修补用于器物、关系，真相不能被修补。", "播种": "语义：播种指撒下种子，与“真相”无关。", "欣赏": "语义：欣赏指赏识美好的事物，与“真相”不合。"}, "sentence_index": 0, "correct_answer": "隐瞒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钱隐瞒在床底下。", "explanation": "这里应该用〈隐藏〉。隐瞒用于不让人知道的事情，藏实物要用隐藏。"}, {"text": "窗帘隐瞒了阳光。", "explanation": "这里应该用〈遮挡〉。隐瞒的对象是事情或真相，窗帘挡住阳光要用遮挡。"}, {"text": "大雪隐瞒了整条小路。", "explanation": "这里应该用〈覆盖〉。隐瞒是有意不让人知道真相，大雪不能隐瞒，它盖住道路应说覆盖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐瞒", "is_correct": true, "explanation": "正确：隐瞒指有意不让人知道，与“过去”搭配，符合句意。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：测量用于长度、面积等可量化的事物，不能测量过去。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏指用乐器奏乐，与过去无关。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：驯养用于动物，不能用于过去。"}], "explanations": {"隐瞒": "正确：隐瞒指有意不让人知道，与“过去”搭配，符合句意。", "测量": "搭配：测量用于长度、面积等可量化的事物，不能测量过去。", "演奏": "语义：演奏指用乐器奏乐，与过去无关。", "驯养": "搭配：驯养用于动物，不能用于过去。"}, "sentence_index": 6, "correct_answer": "隐瞒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都隐瞒生病的孩子，一刻也不离开他。", "explanation": "这里应该用〈照顾〉。隐瞒是故意不让人知道事情，不能用于照料生病的人。"}, {"text": "公司热情地隐瞒了远道而来的客人。", "explanation": "这里应该用〈接待〉。隐瞒用于事情或真相，不能用于对待客人。"}, {"text": "老朋友隐瞒我度过了最难的时候。", "explanation": "这里应该用〈陪伴〉。隐瞒是有意不让人知道事情，不能用来表示陪伴；句中“度过最难的时候”也不是可以隐瞒的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没有隐瞒了这件事。", "corrected_sentence": "他从来没有隐瞒过这件事。", "error_description": "错误形式是“没有……了”，正确形式是“没有……过”。否定过去的经历要用“没有……过”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她隐瞒很好，没人发现。", "corrected_sentence": "她隐瞒得很好，没人发现。", "error_description": "错误形式是“隐瞒很好”，正确形式是“隐瞒得很好”。“隐瞒”后要用“得”引出程度补语，少了“得”句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ddca0af-20be-4285-9419-28f24491ad3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96475, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
