INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96475, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很少有，不容易碰上。", "primary_collocate": null, "pronunciation": "nán dé", "ipa": "nan˧˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "今天难得有空，我们去爬山吧。", "target_word": "难得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷难得笑一次。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这么好的天气很难得。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他难得回家一次。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京冬天难得下雨。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你难得来，多坐一会儿。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个城市一年到头都在下雨，难得见到太阳。", "target_word": "难得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一家人难得在一起吃饭。", "target_word": "难得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他平时很忙，难得休息。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这个城市，看到星星是很难得的。", "target_word": "难得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "难得一见", "label": "复合"}], "register": "通用", "sense_fingerprint": "很少有，不容易碰上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96475, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "难得", "is_correct": true, "explanation": "正确答案。“难得”读作 nán dé，意思是很少有、不容易碰上。"}, {"text": "难度", "is_correct": false, "explanation": "dù（第四声）与 dé（第二声）韵母与声调都不同，意思是难的程度。"}, {"text": "难道", "is_correct": false, "explanation": "dào 与 dé 韵母不同（ao 与 e），声调也不同，意思是难道、岂。"}, {"text": "男的", "is_correct": false, "explanation": "de（轻声）与 dé（第二声）声调不同，意思是男人。"}, {"text": "难倒", "is_correct": false, "explanation": "dǎo 与 dé 韵母不同（ao 与 e），声调也不同，意思是使人无法应付。"}], "explanations": {"难得": "正确答案。“难得”读作 nán dé，意思是很少有、不容易碰上。", "难度": "dù（第四声）与 dé（第二声）韵母与声调都不同，意思是难的程度。", "难道": "dào 与 dé 韵母不同（ao 与 e），声调也不同，意思是难道、岂。", "男的": "de（轻声）与 dé（第二声）声调不同，意思是男人。", "难倒": "dǎo 与 dé 韵母不同（ao 与 e），声调也不同，意思是使人无法应付。"}, "sentence_index": null, "correct_answer": "难得"}, "level_3": {"options": [{"text": "难得", "is_correct": true, "explanation": "“难得”表示很少有、不容易碰上，与“今天有空”的少见之意相合。"}, {"text": "忙", "is_correct": false, "explanation": "语义：“忙”与后面的“有空”意思相反，句子自相矛盾。"}, {"text": "普通", "is_correct": false, "explanation": "搭配：“普通”说平常，不能修饰“有空”，“今天普通有空”不成句。"}, {"text": "迟", "is_correct": false, "explanation": "语义：“迟”指时间晚或动作慢，与句中“有空”的少见之意不合。"}], "explanations": {"难得": "“难得”表示很少有、不容易碰上，与“今天有空”的少见之意相合。", "忙": "语义：“忙”与后面的“有空”意思相反，句子自相矛盾。", "普通": "搭配：“普通”说平常，不能修饰“有空”，“今天普通有空”不成句。", "迟": "语义：“迟”指时间晚或动作慢，与句中“有空”的少见之意不合。"}, "sentence_index": 0, "correct_answer": "难得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题很难得，我想了半天也没做出来。", "explanation": "这里应该用〈难〉。“难得”指少有、不容易碰上，不表示题目做起来很难。"}, {"text": "我们遇到的问题很难得，需要大家一起解决。", "explanation": "这里应该用〈困难〉。“难得”指少见，形容问题棘手要用“困难”。"}, {"text": "这家餐厅很难得，每天都坐满了客人。", "explanation": "这里应该用〈热门〉。“难得”指少有，天天客满的餐厅不能说难得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96475, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难得", "is_correct": true, "explanation": "“难得”表示很少有、不容易碰上，与“一年到头都在下雨”的语境相合，说明太阳出现得少。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”指经常，与“一年到头都在下雨”的语境相反，句意矛盾。"}, {"text": "天天", "is_correct": false, "explanation": "语义：“天天”指每天都有，与“一年到头都在下雨”的语境矛盾，句意不通。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”指一直如此，与“一年到头都在下雨”的语境相反，句意矛盾。"}], "explanations": {"难得": "“难得”表示很少有、不容易碰上，与“一年到头都在下雨”的语境相合，说明太阳出现得少。", "常常": "语义：“常常”指经常，与“一年到头都在下雨”的语境相反，句意矛盾。", "天天": "语义：“天天”指每天都有，与“一年到头都在下雨”的语境矛盾，句意不通。", "总是": "语义：“总是”指一直如此，与“一年到头都在下雨”的语境相反，句意矛盾。"}, "sentence_index": 6, "correct_answer": "难得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次远足很难得，我们每周都去一次。", "explanation": "这里应该用〈经常〉。“难得”指少有，每周都去的远足不能说难得。"}, {"text": "这门课很难得，人人都学过，大家都很熟悉。", "explanation": "这里应该用〈普遍〉。“难得”指少有，人人都学过的课不能说难得。"}, {"text": "这次搬家很难得，光打包就用了一整天。", "explanation": "这里应该用〈麻烦〉。“难得”指少见，形容事情繁琐要用“麻烦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很难得机会。", "corrected_sentence": "这是一个很难得的机会。", "error_description": "“难得”作定语修饰名词“机会”时后面要加“的”，应为“很难得的机会”，这里漏掉了“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈工作很忙，周末也难道休息。", "corrected_sentence": "妈妈工作很忙，周末也难得休息。", "error_description": "用词错误：“难道”用来加强反问语气，不表示“很少有”。这里要说很少休息，应用“难得休息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96476, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96476, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96476, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不易得到；少有的；可贵。", "primary_collocate": null, "pronunciation": "nán dé", "ipa": "nan˧˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他是一位难得的好老师。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这么多年的友情非常难得。", "target_word": "难得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "能买到这本旧书真难得。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样诚实的孩子很难得。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一个难得的机会。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一次难得的经验。", "target_word": "难得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在大城市找到安静的地方很难得。", "target_word": "难得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的勇气很难得，大家都佩服他。", "target_word": "难得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么好的朋友，真是难得。", "target_word": "难得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一份难得的礼物，我会好好保存。", "target_word": "难得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "难得一见", "label": "复合"}], "register": "通用", "sense_fingerprint": "不易得到、少有而可贵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难得", "is_correct": true, "explanation": "“难得”表示少有而可贵，正好修饰“好老师”的珍贵。"}, {"text": "糟糕", "is_correct": false, "explanation": "语义：“糟糕”指很差，与“好老师”相矛盾。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”是负面评价，与“好老师”的赞许不合。"}, {"text": "愚蠢", "is_correct": false, "explanation": "搭配：“愚蠢”形容人头脑笨，不能与“好老师”组合作评价。"}], "explanations": {"难得": "“难得”表示少有而可贵，正好修饰“好老师”的珍贵。", "糟糕": "语义：“糟糕”指很差，与“好老师”相矛盾。", "懒惰": "语义：“懒惰”是负面评价，与“好老师”的赞许不合。", "愚蠢": "搭配：“愚蠢”形容人头脑笨，不能与“好老师”组合作评价。"}, "sentence_index": 0, "correct_answer": "难得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道奥数题很难得，我花了一下午才做出来。", "explanation": "这里应该用〈难〉。“难得”强调少有可贵，不表示题目难做。"}, {"text": "这项任务很难得，我们需要分工合作才能完成。", "explanation": "这里应该用〈困难〉。“难得”强调少有可贵，形容任务棘手要用“困难”。"}, {"text": "这件家务很难得，我做了整整一上午。", "explanation": "这里应该用〈辛苦〉。“难得”不表示劳累，形容家务费力要用“辛苦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难得", "is_correct": true, "explanation": "“难得”表示少有，与“找到安静的地方”的稀少之感相合。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”与“安静”相反，句子自相矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”与“安静”的意思相反，句意不通。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”形容人多地窄，不能与“安静的地方”搭配作评价。"}], "explanations": {"难得": "“难得”表示少有，与“找到安静的地方”的稀少之感相合。", "嘈杂": "语义：“嘈杂”与“安静”相反，句子自相矛盾。", "热闹": "语义：“热闹”与“安静”的意思相反，句意不通。", "拥挤": "搭配：“拥挤”形容人多地窄，不能与“安静的地方”搭配作评价。"}, "sentence_index": 6, "correct_answer": "难得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的水很难得，我们随便用多少都行。", "explanation": "这里应该用〈充足〉。“难得”强调少见可贵，水多到随便用要说“充足”。"}, {"text": "这种草很难得，到处都是。", "explanation": "这里应该用〈常见〉。“难得”说少有，“到处都是”的草不能说难得。"}, {"text": "这种杯子超市里到处都有，很难得。", "explanation": "这里应该用〈常见〉。“难得”指少有可贵，到处都有的东西不能说难得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师是难得地好人。", "corrected_sentence": "这位老师是难得的好人。", "error_description": "“难得”作定语修饰“好人”时要用“的”，不能用表示状语的“地”，应为“难得的好人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次机会非常难得的，你要好好珍惜。", "corrected_sentence": "这次机会非常难得，你要好好珍惜。", "error_description": "“难得”直接作谓语时，后面不能单独加“的”。要么去掉“的”，要么说“是非常难得的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
