INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96477, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "考试时让你回答的问题，或者文章的名字。", "primary_collocate": null, "pronunciation": "tí mù", "ipa": "tʰi˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "考试时，我先看简单的题目。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个题目我以前做过。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把考试题目看了两遍。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师出的题目不太难。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的题目很吸引人。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能不能给这篇作文起个题目？", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业只有三个题目。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着题目，想了很久。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些题目都是上周学过的内容。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "题目写在试卷的第一页。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "演讲题目", "label": "复合"}], "register": "中性", "sense_fingerprint": "考试时要回答的问题；文章的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "题目", "is_correct": true, "explanation": "“题目”指考试时要回答的问题，“看简单的题目”自然。"}, {"text": "考场", "is_correct": false, "explanation": "语义：考场是地点，不是要回答的内容，与“看”不合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“简单”不修饰天气，句意不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是座椅的位置，不是要回答的内容。"}], "explanations": {"题目": "“题目”指考试时要回答的问题，“看简单的题目”自然。", "考场": "语义：考场是地点，不是要回答的内容，与“看”不合。", "天气": "搭配：“简单”不修饰天气，句意不通。", "座位": "语义：座位是座椅的位置，不是要回答的内容。"}, "sentence_index": 0, "correct_answer": "题目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的题目是三。", "explanation": "这里应该用〈答案〉。题目是试卷上要解答的问题，不能当作解题的结果。"}, {"text": "这把椅子的题目很结实。", "explanation": "这里应该用〈做工〉。题目指试题或文章标题，不指家具的质量。"}, {"text": "这家饭店的题目是北京烤鸭。", "explanation": "这里应该用〈招牌菜〉。题目指试卷上的问题或文章标题，不指饭店最有名的菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "题目", "is_correct": true, "explanation": "“题目”指要回答的问题，“三个题目”是作业的内容，搭配自然。"}, {"text": "同学", "is_correct": false, "explanation": "语义：同学是人，不是作业的内容，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”用“本”计量，不说“三个书”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不能算作业的数量，句意不通。"}], "explanations": {"题目": "“题目”指要回答的问题，“三个题目”是作业的内容，搭配自然。", "同学": "语义：同学是人，不是作业的内容，句意不通。", "书": "搭配：“书”用“本”计量，不说“三个书”。", "老师": "语义：老师是人，不能算作业的数量，句意不通。"}, "sentence_index": 6, "correct_answer": "题目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门牌上写着题目。", "explanation": "这里应该用〈门牌号〉。题目指试题或文章标题，不能写在门牌上。"}, {"text": "我家猫的题目很可爱。", "explanation": "这里应该用〈名字〉。题目指试题或文章名，不用来称呼猫。"}, {"text": "这件衣服的题目很贵。", "explanation": "这里应该用〈价格〉。题目指试题或文章名，不指商品的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她认真地看了三道题目们。", "corrected_sentence": "她认真地看了三道题目。", "error_description": "用法错误：“题目”是无生命的事物，不能加“们”表示复数，应说“三道题目”，不说“题目们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
