INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "试卷上要求解答的问题；文章、讲演的标题。", "primary_collocate": null, "pronunciation": "tí mù", "ipa": "tʰi˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "这次考试的题目很难。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了今天的题目。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题目我不会做。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的作文题目是什么？", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先读了一遍题目，然后开始答题。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的题目很有意思。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学试卷一共有二十个题目。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把题目再读一遍。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "题目太长，我没看懂。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给文章换了一个新题目。", "target_word": "题目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "作文题目", "label": "复合"}], "register": "中性", "sense_fingerprint": "试卷上要解答的问题；文章或讲演的标题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "题目", "is_correct": true, "explanation": "“题目”指试卷上要解答的问题，“题目很难”搭配自然。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间指时长，不能说难易，与“很难”不搭。"}, {"text": "地点", "is_correct": false, "explanation": "语义：地点指位置，不能说难易，句意不通。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“成绩”说高低、好坏，不能被“很难”修饰。"}], "explanations": {"题目": "“题目”指试卷上要解答的问题，“题目很难”搭配自然。", "时间": "语义：时间指时长，不能说难易，与“很难”不搭。", "地点": "语义：地点指位置，不能说难易，句意不通。", "成绩": "搭配：“成绩”说高低、好坏，不能被“很难”修饰。"}, "sentence_index": 0, "correct_answer": "题目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的题目很重。", "explanation": "这里应该用〈重量〉。题目指试题或文章标题，不指物体的轻重。"}, {"text": "他的题目很好听。", "explanation": "这里应该用〈名字〉。题目指试题或文章标题，不用来称呼人。"}, {"text": "这部小说的题目是科幻。", "explanation": "这里应该用〈题材〉。题目指试题或文章、作品的标题，不指作品的类别；“科幻”这类类别要说“题材”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "题目", "is_correct": true, "explanation": "“题目”指试卷上要解答的问题，可以用“个”计数，“二十个题目”自然。"}, {"text": "段落", "is_correct": false, "explanation": "语义：段落属于文章，数学试卷上不会有段落。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不是试卷上的内容，句意不通。"}, {"text": "难度", "is_correct": false, "explanation": "搭配：“难度”是抽象程度，不能用“个”计数。"}], "explanations": {"题目": "“题目”指试卷上要解答的问题，可以用“个”计数，“二十个题目”自然。", "段落": "语义：段落属于文章，数学试卷上不会有段落。", "学生": "语义：学生是人，不是试卷上的内容，句意不通。", "难度": "搭配：“难度”是抽象程度，不能用“个”计数。"}, "sentence_index": 6, "correct_answer": "题目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店门口挂着题目。", "explanation": "这里应该用〈招牌〉。题目指试卷上的问题或文章标题，不能挂在店门口。"}, {"text": "这瓶饮料的题目写在瓶底。", "explanation": "这里应该用〈标签〉。题目不指商品上印的标签。"}, {"text": "信封上写的是寄件人的题目。", "explanation": "这里应该用〈地址〉。题目不指寄件人的住址。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我做了三道题目们。", "corrected_sentence": "我做了三道题目。", "error_description": "用法错误：“题目”是无生命的事物，不能加“们”表示复数，应说“三道题目”，不说“题目们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
