INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96481, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96481, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "从以前到现在一直这样，没有变过。", "primary_collocate": null, "pronunciation": "yí guàn", "ipa": "i˧˥ kwan˥˩", "syllable_count": 2, "sentences": [{"text": "他一贯很守时，从来没有迟到过。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是老师一贯的做法。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一贯喜欢早上跑步。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司一贯重视服务质量。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷一贯节约，从不浪费水。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的一贯风格，大家都很熟悉。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一贯对我很严格。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店一贯诚信经营，客人很放心。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友一贯很热情。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王一贯说话算数，我相信他。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人或集体的作风、习惯从过去到现在一直不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一贯", "is_correct": true, "explanation": "正确。“一贯”表示始终如此，与“从来没有迟到过”相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示并非每次都如此，与“从来没有迟到过”矛盾。"}, {"text": "有时", "is_correct": false, "explanation": "语义：“有时”表示时而如此，与“从来没有迟到过”矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”指忽然发生的变化，不能用来描述长期稳定的守时习惯。"}], "explanations": {"一贯": "正确。“一贯”表示始终如此，与“从来没有迟到过”相符。", "偶尔": "语义：“偶尔”表示并非每次都如此，与“从来没有迟到过”矛盾。", "有时": "语义：“有时”表示时而如此，与“从来没有迟到过”矛盾。", "突然": "搭配：“突然”指忽然发生的变化，不能用来描述长期稳定的守时习惯。"}, "sentence_index": 0, "correct_answer": "一贯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一贯讨厌运动，后来才爱上跑步。", "explanation": "这里应该用〈一度〉。“一贯”表示始终如此，不能用于前后已经改变的情况。"}, {"text": "我昨天一贯迟到了，老板很生气。", "explanation": "这里应该用〈又〉。“一贯”说明长期如此，不能用于某一天发生的单次事件。"}, {"text": "他一贯变得开朗了。", "explanation": "这里应该用〈逐渐〉。“一贯”表示始终不变，不能与“变得”这类表示变化的词搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一贯", "is_correct": true, "explanation": "正确。“一贯”表示始终如此，与“对我很严格”的长期态度相符。"}, {"text": "一切", "is_correct": false, "explanation": "语法：“一切”是代词，不能放在“对我很严格”前作状语。"}, {"text": "传统", "is_correct": false, "explanation": "语法：“传统”是名词，不能直接修饰“对我很严格”。"}, {"text": "贯彻", "is_correct": false, "explanation": "语法：“贯彻”是动词，要带“政策、精神”等宾语，不能作状语。"}], "explanations": {"一贯": "正确。“一贯”表示始终如此，与“对我很严格”的长期态度相符。", "一切": "语法：“一切”是代词，不能放在“对我很严格”前作状语。", "传统": "语法：“传统”是名词，不能直接修饰“对我很严格”。", "贯彻": "语法：“贯彻”是动词，要带“政策、精神”等宾语，不能作状语。"}, "sentence_index": 6, "correct_answer": "一贯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他一贯考了满分，大家都很惊讶。", "explanation": "这里应该用〈居然〉。“一贯”指长期如此，不能用于“这次考试”这样的单次事件。"}, {"text": "他一贯就明白了老师的意思。", "explanation": "这里应该用〈一下子〉。“一贯”指长期状态，不能描述瞬间完成的“明白”。"}, {"text": "天气一贯变冷了，大家都穿上了外套。", "explanation": "这里应该用〈突然〉。“一贯”表示始终不变，不能与“变冷”这种突然的变化搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一贯了很认真，做事从不马虎。", "corrected_sentence": "她一贯很认真，做事从不马虎。", "error_description": "“一贯”是表示状态的词，后面不能加“了”。正确说法是“她一贯很认真”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他一贯地做法。", "corrected_sentence": "这是他一贯的做法。", "error_description": "“一贯”修饰名词时要用“的”，不能用“地”。“地”用于修饰动词或形容词，“一贯地做法”不通，应写作“一贯的做法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
