INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96482, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96482, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一向如此，始终不变。", "primary_collocate": null, "pronunciation": "yí guàn", "ipa": "i˧˥ kwan˥˩", "syllable_count": 2, "sentences": [{"text": "我一贯的态度没有变。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一贯这样，你别生气。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校一贯主张少考试、多活动。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一贯反对浪费食物。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一贯友好，从不吵架。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家一贯的政策是保持和平。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一贯如此，从来不着急。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生一贯建议大家多喝水。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板一贯对工人很好。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一贯相信，努力会有结果。", "target_word": "一贯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "态度、主张、政策等始终如一，没有改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一贯", "is_correct": true, "explanation": "正确。“一贯的态度”指始终不变的态度，与“没有变”相符。"}, {"text": "善变", "is_correct": false, "explanation": "语义：“善变”表示常常改变，与“没有变”矛盾。"}, {"text": "浮动", "is_correct": false, "explanation": "语义：“浮动”指起伏不定，与“没有变”矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”指忽然发生的事，不能修饰表示稳定立场的“态度”。"}], "explanations": {"一贯": "正确。“一贯的态度”指始终不变的态度，与“没有变”相符。", "善变": "语义：“善变”表示常常改变，与“没有变”矛盾。", "浮动": "语义：“浮动”指起伏不定，与“没有变”矛盾。", "突然": "搭配：“突然”指忽然发生的事，不能修饰表示稳定立场的“态度”。"}, "sentence_index": 0, "correct_answer": "一贯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她这个星期才一贯反对浪费食物。", "explanation": "这里应该用〈开始〉。“一贯”表示一向如此，不能与“这个星期才”表示的起始时间矛盾；〈开始〉表示某事从某时起才发生。"}, {"text": "她一贯变得自信了。", "explanation": "这里应该用〈逐渐〉。“一贯”表示始终不变，不能与“变得”这类表示变化的词搭配。"}, {"text": "学校一贯取消了这条规定。", "explanation": "这里应该用〈突然〉。“一贯”指长期如此，不能修饰“取消了规定”这种一次性发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一贯", "is_correct": true, "explanation": "正确。“一贯如此”表示长期不变，与“从来不着急”相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示并非总是如此，与“一贯如此”矛盾。"}, {"text": "时而", "is_correct": false, "explanation": "语义：“时而”表示有时如此，与“一贯如此”矛盾。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”指突然的变化，不能用来描述长期的态度或性格“如此”。"}], "explanations": {"一贯": "正确。“一贯如此”表示长期不变，与“从来不着急”相符。", "偶尔": "语义：“偶尔”表示并非总是如此，与“一贯如此”矛盾。", "时而": "语义：“时而”表示有时如此，与“一贯如此”矛盾。", "忽然": "搭配：“忽然”指突然的变化，不能用来描述长期的态度或性格“如此”。"}, "sentence_index": 6, "correct_answer": "一贯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次谈判我一贯很坚持，结果没有成功。", "explanation": "这里应该用〈一直〉。“一贯”强调长期不变，不能用于“这次谈判”这样的单次事件。"}, {"text": "他一贯就放弃了原来的主张。", "explanation": "这里应该用〈一下子〉。“一贯”指长期状态，不能描述瞬间完成的“放弃”。"}, {"text": "他一贯去了一趟北京。", "explanation": "这里应该用〈曾经〉。“一贯”表示长期如此，不能用于“去了一趟”这样的一次性经历；“曾经”表示过去发生过某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一贯了很有耐心，从不催促别人。", "corrected_sentence": "他一贯很有耐心，从不催促别人。", "error_description": "“一贯”后面不能加“了”。正确说法是“他一贯很有耐心”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师很一贯主张孩子多读书。", "corrected_sentence": "老师一贯主张孩子多读书。", "error_description": "“一贯”在此作状语，表示始终如此，不能受“很”修饰；去掉“很”即可，即“老师一贯主张孩子多读书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96484, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
