INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96484, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "表示短暂的一段时间或一次的事情。", "primary_collocate": null, "pronunciation": "yī zhèn", "ipa": "i˥ tʂən˥˩", "syllable_count": 2, "sentences": [{"text": "他在门口站了一阵，才走进来。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先聊了一阵，然后开始工作。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前一阵我很忙，现在好多了。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看了一阵书，就去睡觉了。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭了一阵，慢慢安静下来。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一阵天气不好，常常下雨。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了一阵，还是没想出办法。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家笑了一阵，又继续上课。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在路边等了一阵，车才来。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵了一阵，最后都不说话了。", "target_word": "一阵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵子", "label": "复合"}, {"form": "一阵阵", "label": "重叠"}], "register": "口语", "sense_fingerprint": "放在动词后或“这／前”后，表示持续不长的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4a1f6f-7ab9-4f4b-aa6d-3fc7424745ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96484, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一阵", "is_correct": true, "explanation": "一阵：yī zhèn，表示持续不长的一段时间。"}, {"text": "一针", "is_correct": false, "explanation": "zhēn（第一声）与 zhèn（第四声）只差声调，意思是一根针。"}, {"text": "一枕", "is_correct": false, "explanation": "zhěn（第三声）与 zhèn（第四声）只差声调，意思是一个枕头。"}, {"text": "一站", "is_correct": false, "explanation": "zhàn 与 zhèn 声调相同，只差韵母（an 与 en），意思是一个车站或一段路程。"}], "explanations": {"一阵": "一阵：yī zhèn，表示持续不长的一段时间。", "一针": "zhēn（第一声）与 zhèn（第四声）只差声调，意思是一根针。", "一枕": "zhěn（第三声）与 zhèn（第四声）只差声调，意思是一个枕头。", "一站": "zhàn 与 zhèn 声调相同，只差韵母（an 与 en），意思是一个车站或一段路程。"}, "sentence_index": null, "correct_answer": "一阵"}, "level_3": {"options": [{"text": "一阵", "is_correct": true, "explanation": "“一阵”表示持续不长的一段时间，这里指在门口站了一会儿。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“片”用于大面积的东西，不能用来计量“站”的时间。"}, {"text": "一条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不能用来计量“站”。"}, {"text": "一座", "is_correct": false, "explanation": "语义：“座”指大型固定的东西，与“站了一会儿”的短时间不合。"}], "explanations": {"一阵": "“一阵”表示持续不长的一段时间，这里指在门口站了一会儿。", "一片": "搭配：“片”用于大面积的东西，不能用来计量“站”的时间。", "一条": "搭配：“条”用于细长的东西，不能用来计量“站”。", "一座": "语义：“座”指大型固定的东西，与“站了一会儿”的短时间不合。"}, "sentence_index": 0, "correct_answer": "一阵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在农村生活了一阵，直到七十岁。", "explanation": "这里应该用〈一辈子〉。一阵指较短的一段时间，一生的时间要用一辈子，与“直到七十岁”也不合。"}, {"text": "他们之间有一阵友谊，很深。", "explanation": "这里应该用〈一段〉。一阵指较短的时间，长期的友谊应用一段。"}, {"text": "他一阵长高了三十厘米。", "explanation": "这里应该用〈一年〉。一阵只表示短暂的一段时间，长高三十厘米是长时间逐渐发生的，应说一年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一阵", "is_correct": true, "explanation": "“一阵”表示持续不长的一段时间，这里指想了一会儿。"}, {"text": "一张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不能用来计量“想”的时间。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，不能修饰“想”这个动作。"}, {"text": "一丝", "is_correct": false, "explanation": "搭配：“一丝”指极少的一点（如一丝希望），不能放在“想了”后面表示时间。"}], "explanations": {"一阵": "“一阵”表示持续不长的一段时间，这里指想了一会儿。", "一张": "搭配：“张”用于平面的东西，不能用来计量“想”的时间。", "一根": "搭配：“根”用于细长的东西，不能修饰“想”这个动作。", "一丝": "搭配：“一丝”指极少的一点（如一丝希望），不能放在“想了”后面表示时间。"}, "sentence_index": 6, "correct_answer": "一阵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们吵了一阵，吵了一生。", "explanation": "这里应该用〈一辈子〉。一阵只指较短的一段时间，与“吵了一生”的漫长时间相冲突。"}, {"text": "他摔了一阵跤，马上爬了起来。", "explanation": "这里应该用〈一次〉。摔跤是一下子完成的动作，不是持续的一段时间，应用“一次”。"}, {"text": "他买了一阵房子，很贵。", "explanation": "这里应该用〈一套〉。一阵表示一段短时间，不能用来计量房子，房子要用“一套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他坐在窗边看着一阵报纸。", "corrected_sentence": "他坐在窗边看了一阵报纸。", "error_description": "体标错误：“着”表示动作正在进行，不能与表示已完成的一段时间的“一阵”搭配，应说“看了一阵报纸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们聊着一阵天，就各自回家了。", "corrected_sentence": "我们聊了一阵天，就各自回家了。", "error_description": "体标错误：“着”表示动作正在进行，不能与表示已完成的一段时间的“一阵”搭配，应说“聊了一阵天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
