INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96485, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "刚学东西，开始会用了。", "primary_collocate": null, "pronunciation": "shàng shǒu", "ipa": "ʂɑŋ˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我学了两个星期，才慢慢上手。", "target_word": "上手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手机我用了三天才上手。", "target_word": "上手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚学开车，还没上手。", "target_word": "上手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台机器我用了一个月才上手。", "target_word": "上手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学画画要多练，才能上手。", "target_word": "上手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小李来公司一个月，工作已经上手了。", "target_word": "上手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我学做饭学了很久，现在终于上手了。", "target_word": "上手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你多试几次，很快就上手。", "target_word": "上手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他学钢琴三个月，还不太上手。", "target_word": "上手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚开始我不会用电脑，一周后就上手了。", "target_word": "上手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "上手了", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "刚学一样东西或技能，开始会用、入门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4a1f6f-7ab9-4f4b-aa6d-3fc7424745ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96485, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上手", "is_correct": true, "explanation": "正确答案。shàng shǒu，指刚学会用某样东西或某种技能，开始会操作了。"}, {"text": "伤手", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是手受了伤。"}, {"text": "上水", "is_correct": false, "explanation": "第二个音节 shuǐ（第三声）与 shǒu 的韵母不同，意思是给管道供水。"}, {"text": "上收", "is_correct": false, "explanation": "第二个音节 shōu（第一声）与 shǒu 的声调不同，意思是收归上级。"}], "explanations": {"上手": "正确答案。shàng shǒu，指刚学会用某样东西或某种技能，开始会操作了。", "伤手": "shāng（第一声）与 shàng（第四声）声调不同，意思是手受了伤。", "上水": "第二个音节 shuǐ（第三声）与 shǒu 的韵母不同，意思是给管道供水。", "上收": "第二个音节 shōu（第一声）与 shǒu 的声调不同，意思是收归上级。"}, "sentence_index": null, "correct_answer": "上手"}, "level_3": {"options": [{"text": "发烧", "is_correct": false, "explanation": "语义：「发烧」指身体发热，与“学了两个星期”的语境无关，句子读不通。"}, {"text": "上手", "is_correct": true, "explanation": "正确答案。「上手」表示刚学会、开始会做，与“学了两个星期，才慢慢”的进展一致。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：「毕业」要求完成整个学业，学了两个星期说不上毕业。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」指婚姻，与学习的进展毫不相关，句子读不通。"}], "explanations": {"发烧": "语义：「发烧」指身体发热，与“学了两个星期”的语境无关，句子读不通。", "上手": "正确答案。「上手」表示刚学会、开始会做，与“学了两个星期，才慢慢”的进展一致。", "毕业": "搭配：「毕业」要求完成整个学业，学了两个星期说不上毕业。", "结婚": "语义：「结婚」指婚姻，与学习的进展毫不相关，句子读不通。"}, "sentence_index": 0, "correct_answer": "上手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这座城市已经很上手了。", "explanation": "这里应该用〈熟悉〉。上手指学会操作工具或技能，不用于人对城市、地方的熟悉。"}, {"text": "这次失恋我终于上手了。", "explanation": "这里应该用〈释怀〉。上手指学会操作或技能，不用于形容走出感情上的伤痛。"}, {"text": "他的脾气我已经上手了。", "explanation": "这里应该用〈摸透〉。上手指学会操作或技能，不用于形容对人脾气的摸清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生病", "is_correct": false, "explanation": "语义：「生病」指人或动物得病，与“学做饭学了很久”的语境不合，句子读不通。"}, {"text": "上手", "is_correct": true, "explanation": "正确答案。「上手」表示学会了做，与“学做饭学了很久，现在终于”的语境一致。"}, {"text": "出差", "is_correct": false, "explanation": "语义：「出差」指因公外出，与学做饭无关，句子读不通。"}, {"text": "竣工", "is_correct": false, "explanation": "搭配：「竣工」用于工程、建筑，不能说学做饭竣工。"}], "explanations": {"生病": "语义：「生病」指人或动物得病，与“学做饭学了很久”的语境不合，句子读不通。", "上手": "正确答案。「上手」表示学会了做，与“学做饭学了很久，现在终于”的语境一致。", "出差": "语义：「出差」指因公外出，与学做饭无关，句子读不通。", "竣工": "搭配：「竣工」用于工程、建筑，不能说学做饭竣工。"}, "sentence_index": 6, "correct_answer": "上手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个道理我想了很久，现在终于上手了。", "explanation": "这里应该用〈理解〉。上手指学会操作工具或技能，不用于想通一个道理。"}, {"text": "我和新同事才认识一个月，就已经上手了。", "explanation": "这里应该用〈熟悉〉。上手指学会操作工具或技能，不用于人与人之间变得熟悉。"}, {"text": "这个笑话我已经上手了。", "explanation": "这里应该用〈听懂〉。上手指学会操作或技能，不用于听懂一个笑话的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学了两个星期，才慢慢上手了过。", "corrected_sentence": "我学了两个星期，才慢慢上手了。", "error_description": "错误在于“上手”后同时带了“了”和“过”。“了”与“过”两个动态助词不能同现，应去掉“过”，说“慢慢上手了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学了一个月，还没上手了。", "corrected_sentence": "他学了一个月，还没上手。", "error_description": "错误在于“没”后面又加了“了”。否定“没”与句末“了”不能同现，应说“还没上手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
