INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "放在句尾，表示没想到，是在问。", "primary_collocate": null, "pronunciation": "bù chéng", "ipa": "pu˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "你还想骗我不成？", "target_word": "不成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "难道你想一个人去不成？", "target_word": "不成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他这么晚还不回家，难道出事了不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么简单的题，你还想问老师不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想饿一天不成？", "target_word": "不成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "难道你喜欢吃冷饭不成？", "target_word": "不成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天这么黑，你还要出去不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想让我替你写作业不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直不接电话，难道生气了不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "难道我说错了不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末语气词，常与“难道”“还”连用，表示反问、不敢相信", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4a1f6f-7ab9-4f4b-aa6d-3fc7424745ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "路程", "is_correct": false, "explanation": "lù（第四声）与 bù 的声母不同（l 与 b），意思是路程、距离。"}, {"text": "不成", "is_correct": true, "explanation": "正确答案。bù chéng，句末语气词，表示反问，意思是“难道……吗”。"}, {"text": "不曾", "is_correct": false, "explanation": "céng（第二声）与 chéng 的声母不同（c 与 ch），“不曾”意思是从来没有、还没有。"}, {"text": "不长", "is_correct": false, "explanation": "cháng（第二声）与 chéng 的韵母不同（ang 与 eng），“不长”意思是不长久、不够长。"}, {"text": "不沉", "is_correct": false, "explanation": "chén（第二声）与 chéng 的韵母不同（en 与 eng），“不沉”意思是不下沉。"}], "explanations": {"路程": "lù（第四声）与 bù 的声母不同（l 与 b），意思是路程、距离。", "不成": "正确答案。bù chéng，句末语气词，表示反问，意思是“难道……吗”。", "不曾": "céng（第二声）与 chéng 的声母不同（c 与 ch），“不曾”意思是从来没有、还没有。", "不长": "cháng（第二声）与 chéng 的韵母不同（ang 与 eng），“不长”意思是不长久、不够长。", "不沉": "chén（第二声）与 chéng 的韵母不同（en 与 eng），“不沉”意思是不下沉。"}, "sentence_index": null, "correct_answer": "不成"}, "level_3": {"options": [{"text": "而已", "is_correct": false, "explanation": "语义：「而已」表示“只是如此”，与句中的反问语气不合，句子读不通。"}, {"text": "不成", "is_correct": true, "explanation": "正确答案。「不成」表示反问，意思是“难道你还想骗我吗”。"}, {"text": "罢了", "is_correct": false, "explanation": "语义：「罢了」表示“不过如此”，与“你还想骗我”的反问语境不合。"}, {"text": "来着", "is_correct": false, "explanation": "体貌：「来着」表示回想过去的情况，与句中“还想”表示的当前反问不合。"}], "explanations": {"而已": "语义：「而已」表示“只是如此”，与句中的反问语气不合，句子读不通。", "不成": "正确答案。「不成」表示反问，意思是“难道你还想骗我吗”。", "罢了": "语义：「罢了」表示“不过如此”，与“你还想骗我”的反问语境不合。", "来着": "体貌：「来着」表示回想过去的情况，与句中“还想”表示的当前反问不合。"}, "sentence_index": 0, "correct_answer": "不成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这么大的雨，我们今天去不成了。", "explanation": "这里的“不成”作可能补语，表示“去不了、无法实现”，不是表示反问的句末语气词。"}, {"text": "这道题我一个人做不成。", "explanation": "这里的“不成”作可能补语，表示“做不到、办不成”，不是表示反问的句末语气词。"}, {"text": "这门课他这学期考不成了。", "explanation": "这里的“不成”作可能补语，表示“没法参加考试”，不是表示反问的句末语气词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着呢", "is_correct": false, "explanation": "体貌：「着呢」表示状态持续，与“你还要出去”的动作不合，句子读不通。"}, {"text": "不成", "is_correct": true, "explanation": "正确答案。「不成」表示反问，意思是“你还要出去吗”，带有不以为然的语气。"}, {"text": "也罢", "is_correct": false, "explanation": "语义：「也罢」表示“算了”的让步，句中没有这种语境，句子读不通。"}, {"text": "似的", "is_correct": false, "explanation": "语义：「似的」表示比喻或“好像”，需要前面有“像”之类的比较对象，不能表示反问，句子读不通。"}], "explanations": {"着呢": "体貌：「着呢」表示状态持续，与“你还要出去”的动作不合，句子读不通。", "不成": "正确答案。「不成」表示反问，意思是“你还要出去吗”，带有不以为然的语气。", "也罢": "语义：「也罢」表示“算了”的让步，句中没有这种语境，句子读不通。", "似的": "语义：「似的」表示比喻或“好像”，需要前面有“像”之类的比较对象，不能表示反问，句子读不通。"}, "sentence_index": 6, "correct_answer": "不成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么多的事，我一天做不成。", "explanation": "这里的“不成”作可能补语，表示“做不到”，不是表示反问的句末语气词。"}, {"text": "下雨了，今天的比赛看来是比不成了。", "explanation": "这里的“不成”作可能补语，表示“无法进行”，不是表示反问的句末语气词。"}, {"text": "钱不够，这次旅行去不成了。", "explanation": "这里的“不成”作可能补语，表示“去不了”，不是表示反问的句末语气词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你还想去他家不成吗？", "corrected_sentence": "你还想去他家不成？", "error_description": "错误在于“不成”后面又加了“吗”。“不成”本身已表示反问，两个疑问语气词不能叠用，应说“你还想去他家不成？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么冷的天，你还要去游泳不成吗？", "corrected_sentence": "这么冷的天，你还要去游泳不成？", "error_description": "错误在于“不成”后面又加了“吗”。“不成”本身已表示反问，不能再叠用疑问语气词“吗”，应说“你还要去游泳不成？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
