INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96489, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "站在两个人中间，帮他们办事的人或公司。", "primary_collocate": null, "pronunciation": "zhōng jiè", "ipa": "tʂʊŋ˥ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我想租房子，先去找中介。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家中介的服务很好。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中介帮我们找到了新房子。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家中介工作。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子要给中介多少钱？", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有通过中介，直接问了房东。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中介带着我们看了三套房子。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要小心，有些中介会骗人。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友介绍的中介很可靠。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把房子交给中介卖了。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "房产中介", "label": "复合"}, {"form": "中介费", "label": "复合"}], "register": "中性", "sense_fingerprint": "帮人办事的中间人或公司，如房屋中介", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96489, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中介", "is_correct": true, "explanation": "正确答案。“中介”读作 zhōng jiè，指帮人找房、办事的人或机构。"}, {"text": "终结", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是结束。"}, {"text": "中间", "is_correct": false, "explanation": "jiān（第一声）与 jiè（第四声）韵母与声调都不同，意思是两者之间。"}, {"text": "中将", "is_correct": false, "explanation": "jiàng 与 jiè 韵母不同（iang 与 ie），声调相同，意思是军衔“中将”。"}], "explanations": {"中介": "正确答案。“中介”读作 zhōng jiè，指帮人找房、办事的人或机构。", "终结": "jié（第二声）与 jiè（第四声）声调不同，意思是结束。", "中间": "jiān（第一声）与 jiè（第四声）韵母与声调都不同，意思是两者之间。", "中将": "jiàng 与 jiè 韵母不同（iang 与 ie），声调相同，意思是军衔“中将”。"}, "sentence_index": null, "correct_answer": "中介"}, "level_3": {"options": [{"text": "中介", "is_correct": true, "explanation": "“中介”指帮人找房、办事的人或机构，与“租房子、找”的语境相合。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不负责租房，“先去找医院”与句意不通。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是买东西的地方，与租房子的目的不合。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能帮人租房子。"}], "explanations": {"中介": "“中介”指帮人找房、办事的人或机构，与“租房子、找”的语境相合。", "医院": "语义：医院不负责租房，“先去找医院”与句意不通。", "超市": "语义：超市是买东西的地方，与租房子的目的不合。", "面包": "语义：面包是食物，不能帮人租房子。"}, "sentence_index": 0, "correct_answer": "中介"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中介是我家的保姆，每天做饭打扫。", "explanation": "这里应该用〈保姆〉。“中介”指替双方办事的人或机构，不是照顾家务的人。"}, {"text": "我们常去这家中介散步，那里的花很多。", "explanation": "这里应该用〈公园〉。“中介”指替双方办事的人或机构，不是可以散步的地方。"}, {"text": "我妈妈是中介，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。“中介”不负责诊治病人，给病人看病要用“医生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中介", "is_correct": true, "explanation": "“中介”能带人看房，与句子中“带着我们看房子”的动作相合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不负责看房，句意不合。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁负责照料花草，与看房无关。"}, {"text": "保安", "is_correct": false, "explanation": "搭配：“保安”一般不负责带人看房，这样搭配不当。"}], "explanations": {"中介": "“中介”能带人看房，与句子中“带着我们看房子”的动作相合。", "厨师": "语义：厨师负责做饭，不负责看房，句意不合。", "园丁": "语义：园丁负责照料花草，与看房无关。", "保安": "搭配：“保安”一般不负责带人看房，这样搭配不当。"}, "sentence_index": 6, "correct_answer": "中介"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中介每天在学校给学生上数学课。", "explanation": "这里应该用〈老师〉。“中介”替双方办事，不负责给学生上课。"}, {"text": "我请了一位中介帮我做饭，他的菜很好吃。", "explanation": "这里应该用〈厨师〉。“中介”指替双方办事，不负责做饭。"}, {"text": "这位中介是我的司机，每天接送我上班。", "explanation": "这里应该用〈司机〉。“中介”指替双方办事的人或机构，不负责开车接送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想租房子，先去找一只中介。", "corrected_sentence": "我想租房子，先去找一家中介。", "error_description": "“中介”指房屋中介机构，量词应用“家”，说“一只中介”不对，应为“一家中介”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个中介地服务很认真。", "corrected_sentence": "这个中介的服务很认真。", "error_description": "“中介”作定语修饰“服务”时要用“的”，不能用“地”，应为“中介的服务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
