INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在双方之间起联系、撮合作用的人或机构。", "primary_collocate": null, "pronunciation": "zhōng jiè", "ipa": "tʂʊŋ˥ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他想出国读书，找了一家留学中介。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个中介帮公司找到了好工人。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她通过婚姻中介认识了现在的丈夫。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中介要在双方之间做好联系。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和工人之间需要一个中介。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个中介只负责联系，不负责签合同。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找工作，就去问了中介。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好中介会听客人的要求。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请中介帮忙联系学校。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家中介介绍过很多老师。", "target_word": "中介", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "留学中介", "label": "复合"}, {"form": "中介费", "label": "复合"}], "register": "中性", "sense_fingerprint": "在双方之间联系、撮合的人或机构，如留学中介", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96490, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中介", "is_correct": true, "explanation": "正确答案。“中介”读作 zhōng jiè，指在双方之间起联系、撮合作用的人或机构。"}, {"text": "终结", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是结束。"}, {"text": "中间", "is_correct": false, "explanation": "jiān（第一声）与 jiè（第四声）韵母与声调都不同，意思是两者之间。"}, {"text": "中将", "is_correct": false, "explanation": "jiàng 与 jiè 韵母不同（iang 与 ie），声调相同，意思是军衔“中将”。"}], "explanations": {"中介": "正确答案。“中介”读作 zhōng jiè，指在双方之间起联系、撮合作用的人或机构。", "终结": "jié（第二声）与 jiè（第四声）声调不同，意思是结束。", "中间": "jiān（第一声）与 jiè（第四声）韵母与声调都不同，意思是两者之间。", "中将": "jiàng 与 jiè 韵母不同（iang 与 ie），声调相同，意思是军衔“中将”。"}, "sentence_index": null, "correct_answer": "中介"}, "level_3": {"options": [{"text": "中介", "is_correct": true, "explanation": "“留学中介”是帮人办理留学事务、起联系作用的机构，符合句意。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅与留学无关，“留学餐厅”句意不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是办理留学事务的机构，句意不通。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“留学”后不能接“公园”，无法构成机构名称。"}], "explanations": {"中介": "“留学中介”是帮人办理留学事务、起联系作用的机构，符合句意。", "餐厅": "语义：餐厅与留学无关，“留学餐厅”句意不通。", "医院": "语义：医院不是办理留学事务的机构，句意不通。", "公园": "搭配：“留学”后不能接“公园”，无法构成机构名称。"}, "sentence_index": 0, "correct_answer": "中介"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在这家中介吃了一顿饭，菜很好吃。", "explanation": "这里应该用〈饭馆〉。“中介”指在双方之间联系的人或机构，不是吃饭的地方。"}, {"text": "我请了一位中介帮我唱歌，他的声音很好听。", "explanation": "这里应该用〈歌手〉。中介负责在双方之间联系，不负责唱歌。"}, {"text": "他想去中介学做饭。", "explanation": "这里应该用〈学校〉。中介负责撮合、办事，学做饭要去学校或培训班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中介", "is_correct": true, "explanation": "“中介”能帮人找工作、办事，与“去问了”的对象相合。"}, {"text": "报纸", "is_correct": false, "explanation": "配价：“问”的对象应是人，“报纸”不能作“问”的对象。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李与找工作无关，句意不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：问月亮与找工作的语境无关，句意不通。"}], "explanations": {"中介": "“中介”能帮人找工作、办事，与“去问了”的对象相合。", "报纸": "配价：“问”的对象应是人，“报纸”不能作“问”的对象。", "行李": "语义：行李与找工作无关，句意不通。", "月亮": "语义：问月亮与找工作的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "中介"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个中介负责生产汽车，每天生产两百辆。", "explanation": "这里应该用〈工厂〉。中介只在双方之间联系，不负责生产。"}, {"text": "中介每天照顾老人，按时给他们吃药。", "explanation": "这里应该用〈保姆〉。中介只在双方之间联系，不负责照顾人。"}, {"text": "这个中介负责管理图书馆，每天整理书架。", "explanation": "这里应该用〈图书管理员〉。中介只在双方之间联系，不负责管理图书馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她想去国外读研，找了一只留学中介。", "corrected_sentence": "她想去国外读研，找了一家留学中介。", "error_description": "“留学中介”指机构时量词应用“家”，说“一只留学中介”不对，应为“一家留学中介”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家中介地服务很认真。", "corrected_sentence": "那家中介的服务很认真。", "error_description": "“中介”作定语修饰“服务”时要用“的”，不能用“地”，应为“中介的服务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
