INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96491, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公司里管人来、人走、工作安排的事。", "primary_collocate": null, "pronunciation": "rén shì", "ipa": "ʐən˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我在公司管人事。", "target_word": "人事", "complexity_tier": "T3", "furigana": "wǒ zài gōngsī guǎn rénshì.", "sentence_source": "generated"}, {"text": "小王负责公司的人事。", "target_word": "人事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天都在忙公司的人事。", "target_word": "人事", "complexity_tier": "T3", "furigana": "tā měi tiān dōu zài máng gōngsī de rénshì.", "sentence_source": "generated"}, {"text": "负责人事的同事今天不在。", "target_word": "人事", "complexity_tier": "T3", "furigana": "fù zé rénshì de tóngshì jīntiān bú zài.", "sentence_source": "generated"}, {"text": "新同事来了，请先去找负责人事的人说一下。", "target_word": "人事", "complexity_tier": "T3", "furigana": "xīn tóngshì lái le, qǐng xiān qù zhǎo fù zé rénshì de rén shuō yíxià.", "sentence_source": "generated"}, {"text": "关于人事的安排，会有人通知你什么时候上班。", "target_word": "人事", "complexity_tier": "T3", "furigana": "guānyú rénshì de ānpái, huì yǒu rén tōngzhī nǐ shénme shíhou shàng bān.", "sentence_source": "generated"}, {"text": "她做过很多年人事，所以很会招人。", "target_word": "人事", "complexity_tier": "T3", "furigana": "tā zuò guò hěn duō nián rénshì, suǒyǐ hěn huì zhāo rén.", "sentence_source": "generated"}, {"text": "最近公司的人事变动让大家很意外。", "target_word": "人事", "complexity_tier": "T3", "furigana": "zuìjìn gōngsī de rénshì ràng dàjiā hěn yìwài.", "sentence_source": "generated"}, {"text": "我想辞职，要先跟负责人事的同事谈一谈。", "target_word": "人事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板把人事交给了一位新经理。", "target_word": "人事", "complexity_tier": "T3", "furigana": "lǎobǎn bǎ rénshì jiāo gěi le yí wèi xīn jīnglǐ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "人事部", "label": "复合"}, {"form": "人事部门", "label": "复合"}, {"form": "人事经理", "label": "复合"}], "register": "中性", "sense_fingerprint": "公司里管员工入职、离职和工作安排的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96491, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人事", "is_correct": true, "explanation": "正确。人事指公司里管理员工的事务，“管”可以接“人事”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是可以管理的事务，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“管”可以接“人事”“财务”，不能接“年龄”。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”是身体的节律，不是可以管理的事务。"}], "explanations": {"人事": "正确。人事指公司里管理员工的事务，“管”可以接“人事”。", "天气": "语义：“天气”是自然现象，不是可以管理的事务，句子不通。", "年龄": "搭配：“管”可以接“人事”“财务”，不能接“年龄”。", "心跳": "语义：“心跳”是身体的节律，不是可以管理的事务。"}, "sentence_index": 0, "correct_answer": "人事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司需要大量人事。", "explanation": "这里应该用〈人才〉。“大量”修饰的是人才这类可以计数的人；人事指事务，不能说“大量人事”。"}, {"text": "她每天早上都要喝人事。", "explanation": "这里应该用〈咖啡〉。“喝”的对象是饮品，人事指人员任免、调动等事务，不能喝。"}, {"text": "今天的人事很蓝。", "explanation": "这里应该用〈天空〉。“蓝”形容天空、颜色，人事指人员任免、调动等事务，不能用“蓝”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人事", "is_correct": true, "explanation": "正确。人事指单位里管人员的事务，“很会招人”与之相符。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”是身体的节律，不是可以从事的工作，句子不通。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”是自然现象，不能作为工作经历，句子不通。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“做过……年”接的是职业或工作，“月亮”不能。"}], "explanations": {"人事": "正确。人事指单位里管人员的事务，“很会招人”与之相符。", "心跳": "语义：“心跳”是身体的节律，不是可以从事的工作，句子不通。", "雨水": "语义：“雨水”是自然现象，不能作为工作经历，句子不通。", "月亮": "搭配：“做过……年”接的是职业或工作，“月亮”不能。"}, "sentence_index": 6, "correct_answer": "人事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的人事很有个性。", "explanation": "这里应该用〈人物〉。“有个性”形容人物，人事指人员任免、调动等事务，不能说“有个性”。"}, {"text": "他在院子里种了很多人事。", "explanation": "这里应该用〈花〉。“种”的对象是花草、树木等，人事指机构内部人员任免等事务，不能种。"}, {"text": "这家餐厅的人事很好吃。", "explanation": "这里应该用〈菜〉。“好吃”形容食物，人事指人员任免、调动等事务，不能用“好吃”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司刚处理完一座人事调整。", "corrected_sentence": "公司刚处理完一项人事调整。", "error_description": "量词错误：“人事调整”应该用量词“项”，这里误用“座”。“座”用于建筑等大型固定物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只人事安排需要经理批准。", "corrected_sentence": "这项人事安排需要经理批准。", "error_description": "量词错误：“人事安排”应该用量词“项”，这里误用“只”。“只”用于动物等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
