INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机构内部有关人员任免、调动、考核等的事务。", "primary_collocate": null, "pronunciation": "rén shì", "ipa": "ʐən˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这所学校的人事由校长决定。", "target_word": "人事", "complexity_tier": "T3", "furigana": "zhè suǒ xuéxiào de rénshì yóu xiàozhǎng juédìng.", "sentence_source": "generated"}, {"text": "这个单位管理人事十分严格。", "target_word": "人事", "complexity_tier": "T3", "furigana": "zhè ge dānwèi guǎnlǐ rénshì shífēn yángé.", "sentence_source": "generated"}, {"text": "他在局里管人事，工作很忙。", "target_word": "人事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各部门已经收到了人事调整的通知。", "target_word": "人事", "complexity_tier": "T3", "furigana": "gè bùmén yǐjīng shōudào le rénshì de tōngzhī.", "sentence_source": "generated"}, {"text": "医院今年对人事进行了改革。", "target_word": "人事", "complexity_tier": "T3", "furigana": "yīyuàn jīnnián duì rénshì jìnxíng le gǎigé.", "sentence_source": "generated"}, {"text": "这次涉及人事的事务由领导小组决定。", "target_word": "人事", "complexity_tier": "T3", "furigana": "zhè cì shèjí rénshì de shìwù yóu lǐngdǎo xiǎozǔ juédìng.", "sentence_source": "generated"}, {"text": "年底单位要对人事进行考核，大家都很认真。", "target_word": "人事", "complexity_tier": "T3", "furigana": "niándǐ dānwèi yào duì rénshì jìnxíng kǎohé, dàjiā dōu hěn rènzhēn.", "sentence_source": "generated"}, {"text": "他对学校的人事没有意见。", "target_word": "人事", "complexity_tier": "T3", "furigana": "tā duì xuéxiào de rénshì méi yǒu yìjiàn.", "sentence_source": "generated"}, {"text": "报纸上写着厅里人事的最新情况。", "target_word": "人事", "complexity_tier": "T3", "furigana": "bàozhǐ shàng xiě zhe tīng lǐ rénshì de zuìxīn qíngkuàng.", "sentence_source": "generated"}, {"text": "这个机关的人事长期存在问题。", "target_word": "人事", "complexity_tier": "T3", "furigana": "zhè ge jīguān de rénshì chángqī cúnzài wèntí.", "sentence_source": "generated"}], "morphological_forms": [{"form": "人事制度", "label": "复合"}, {"form": "人事调动", "label": "复合"}, {"form": "人事部门", "label": "复合"}], "register": "书面", "sense_fingerprint": "机关单位内部人员任免、调动、考核等事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人事", "is_correct": true, "explanation": "正确。人事指机构内部有关人员任免、调动的事务，可以由校长决定。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能由校长决定，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指外形，不是学校可以由校长决定的事务。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不能由校长决定。"}], "explanations": {"人事": "正确。人事指机构内部有关人员任免、调动的事务，可以由校长决定。", "天气": "语义：“天气”是自然现象，不能由校长决定，句子不通。", "身材": "体貌：“身材”指外形，不是学校可以由校长决定的事务。", "体重": "语义：“体重”指身体的重量，不能由校长决定。"}, "sentence_index": 0, "correct_answer": "人事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的人事很充足。", "explanation": "这里应该用〈人力〉。“充足”可以形容人力、物资，人事指事务，不能说“充足”。"}, {"text": "这家店的人事很高。", "explanation": "这里应该用〈人气〉。“人气很高”指受欢迎，“人事很高”不通。"}, {"text": "周末我去超市买了很多人事。", "explanation": "这里应该用〈菜〉。“买”的对象是菜、东西等，人事指机构内部人员任免、调动等事务，不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人事", "is_correct": true, "explanation": "正确。人事指单位内部人员的任免、考核等事务，可以作为考核的对象。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是外形特征，不能作为考核的对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能作为年底考核的对象，句子不通。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“考核”接的是人员或工作，不能说“考核房子”。"}], "explanations": {"人事": "正确。人事指单位内部人员的任免、考核等事务，可以作为考核的对象。", "身高": "体貌：“身高”是外形特征，不能作为考核的对象。", "天气": "语义：“天气”是自然现象，不能作为年底考核的对象，句子不通。", "房子": "搭配：“考核”接的是人员或工作，不能说“考核房子”。"}, "sentence_index": 6, "correct_answer": "人事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的人事增加了三公斤。", "explanation": "这里应该用〈体重〉。“增加了三公斤”说的是体重这类可称量的数量，人事指机构内部人员任免、调动等事务，不能用公斤计量。"}, {"text": "全市的人事有一千万。", "explanation": "这里应该用〈人口〉。人口可以用数字计算；人事是事务，不能用数量表示。"}, {"text": "他喜欢吃人事。", "explanation": "这里应该用〈火锅〉。“吃”的对象是食物，人事指机构内部人员任免、调动等事务，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "关于这台人事调动，大家还要再讨论。", "corrected_sentence": "关于这项人事调动，大家还要再讨论。", "error_description": "量词错误：“人事调动”应该用量词“项”，这里误用“台”。“台”用于机器等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这副人事工作交给了他负责。", "corrected_sentence": "这项人事工作交给了他负责。", "error_description": "量词错误：“人事工作”应该用量词“项”，这里误用“副”。“副”用于成对或成套的物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
