INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96493, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很好，很棒。", "primary_collocate": null, "pronunciation": "jiā", "ipa": "tɕja˥", "syllable_count": 1, "sentences": [{"text": "这家饭店服务佳，客人都很满意。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè jiā fàn diàn fú wù jiā, kè rén dōu hěn mǎn yì.", "sentence_source": "generated"}, {"text": "今天天气佳，适合出门散步。", "target_word": "佳", "complexity_tier": "T3", "furigana": "jīn tiān tiān qì jiā, shì hé chū mén sàn bù.", "sentence_source": "generated"}, {"text": "他的口才佳，大家都爱听他讲话。", "target_word": "佳", "complexity_tier": "T3", "furigana": "tā de kǒu cái jiā, dà jiā dōu ài tīng tā jiǎng huà.", "sentence_source": "generated"}, {"text": "这里的风景佳，吸引了很多游客。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè lǐ de fēng jǐng jiā, xī yǐn le hěn duō yóu kè.", "sentence_source": "generated"}, {"text": "这件作品效果佳，老师给了高分。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè jiàn zuò pǐn xiào guǒ jiā, lǎo shī gěi le gāo fēn.", "sentence_source": "generated"}, {"text": "她的成绩佳，年年都拿奖学金。", "target_word": "佳", "complexity_tier": "T3", "furigana": "tā de chéng jì jiā, nián nián dōu ná jiǎng xué jīn.", "sentence_source": "generated"}, {"text": "这次比赛他的状态佳，一定能赢。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè cì bǐ sài tā de zhuàng tài jiā, yí dìng néng yíng.", "sentence_source": "generated"}, {"text": "这家咖啡店味道佳，我常常去。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè jiā kā fēi diàn wèi dào jiā, wǒ cháng cháng qù.", "sentence_source": "generated"}, {"text": "这种面料手感佳，夏天穿很舒服。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè zhǒng miàn liào shǒu gǎn jiā, xià tiān chuān hěn shū fu.", "sentence_source": "generated"}, {"text": "他的记忆力佳，看过一次就记住了。", "target_word": "佳", "complexity_tier": "T3", "furigana": "tā de jì yì lì jiā, kàn guò yí cì jiù jì zhù le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "最佳", "label": "复合词"}, {"form": "佳作", "label": "复合词"}, {"form": "不佳", "label": "否定形式"}], "register": "书面", "sense_fingerprint": "很好，很棒：书面语，多作谓语，常与极、甚、颇、俱连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96493, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "佳", "is_correct": true, "explanation": "佳：jiā，意思是很好、很棒，与听到的音相符。"}, {"text": "价", "is_correct": false, "explanation": "价：jià（第四声）与 jiā（第一声）声调不同，意思是价格。"}, {"text": "假", "is_correct": false, "explanation": "假：jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的、虚假。"}, {"text": "江", "is_correct": false, "explanation": "江：jiāng 比 jiā 多了韵尾 ng，意思是江河。"}, {"text": "件", "is_correct": false, "explanation": "件：jiàn（第四声）与 jiā 韵尾与声调都不同，意思是量词，指一件事物。"}], "explanations": {"佳": "佳：jiā，意思是很好、很棒，与听到的音相符。", "价": "价：jià（第四声）与 jiā（第一声）声调不同，意思是价格。", "假": "假：jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的、虚假。", "江": "江：jiāng 比 jiā 多了韵尾 ng，意思是江河。", "件": "件：jiàn（第四声）与 jiā 韵尾与声调都不同，意思是量词，指一件事物。"}, "sentence_index": null, "correct_answer": "佳"}, "level_3": {"options": [{"text": "佳", "is_correct": true, "explanation": "佳：很好、很棒，与“客人都很满意”呼应。"}, {"text": "差", "is_correct": false, "explanation": "语义：“服务差”与后句“客人都很满意”矛盾。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“服务”常与“好、差、周到”等搭配，不说“服务冷”。"}, {"text": "糟", "is_correct": false, "explanation": "语义：“服务糟”与后句“客人都很满意”矛盾。"}], "explanations": {"佳": "佳：很好、很棒，与“客人都很满意”呼应。", "差": "语义：“服务差”与后句“客人都很满意”矛盾。", "冷": "搭配：“服务”常与“好、差、周到”等搭配，不说“服务冷”。", "糟": "语义：“服务糟”与后句“客人都很满意”矛盾。"}, "sentence_index": 0, "correct_answer": "佳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的好朋友很佳，我们常常一起玩。", "explanation": "这里应该用〈亲切〉。“佳”多指能力、质量、状况的好，不用来形容人的友善，应说“亲切”。"}, {"text": "她长得很佳，大家都很喜欢她。", "explanation": "这里应该用〈美〉。“佳”不用来形容人的容貌。"}, {"text": "节日的街上很佳，大家都在唱歌。", "explanation": "这里应该用〈热闹〉。“佳”不用来形容街上的热闹气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96493, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "佳", "is_correct": true, "explanation": "佳：jiā，意思是很好、很棒，与听到的音相符。"}, {"text": "甲", "is_correct": false, "explanation": "甲：jiǎ（第三声）与 jiā（第一声）声调不同，意思是甲（天干之一、甲方）。"}, {"text": "间", "is_correct": false, "explanation": "间：jiān 比 jiā 多了韵尾 n，声调相同，意思是房间。"}, {"text": "讲", "is_correct": false, "explanation": "讲：jiǎng 与 jiā 韵尾不同（ng），声调也不同，意思是讲话。"}, {"text": "见", "is_correct": false, "explanation": "见：jiàn（第四声）与 jiā 韵尾与声调都不同，意思是看见。"}], "explanations": {"佳": "佳：jiā，意思是很好、很棒，与听到的音相符。", "甲": "甲：jiǎ（第三声）与 jiā（第一声）声调不同，意思是甲（天干之一、甲方）。", "间": "间：jiān 比 jiā 多了韵尾 n，声调相同，意思是房间。", "讲": "讲：jiǎng 与 jiā 韵尾不同（ng），声调也不同，意思是讲话。", "见": "见：jiàn（第四声）与 jiā 韵尾与声调都不同，意思是看见。"}, "sentence_index": null, "correct_answer": "佳"}, "level_3": {"options": [{"text": "佳", "is_correct": true, "explanation": "佳：很好，与“一定能赢”相符。"}, {"text": "坏", "is_correct": false, "explanation": "语义：“状态坏”与后句“一定能赢”矛盾。"}, {"text": "弱", "is_correct": false, "explanation": "语义：“状态弱”与后句“一定能赢”矛盾。"}, {"text": "低", "is_correct": false, "explanation": "搭配：“状态”一般说“好、差、不错”，不说“状态低”。"}], "explanations": {"佳": "佳：很好，与“一定能赢”相符。", "坏": "语义：“状态坏”与后句“一定能赢”矛盾。", "弱": "语义：“状态弱”与后句“一定能赢”矛盾。", "低": "搭配：“状态”一般说“好、差、不错”，不说“状态低”。"}, "sentence_index": 6, "correct_answer": "佳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我跑得很佳，每次比赛都是第一。", "explanation": "这里应该用〈快〉。“佳”不用来形容速度。"}, {"text": "我家离学校很佳，走路只要五分钟。", "explanation": "这里应该用〈近〉。“佳”不用来形容距离。"}, {"text": "公园里人很佳，周末没有座位。", "explanation": "这里应该用〈多〉。“佳”不用来形容数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅的环境佳极。", "corrected_sentence": "这家餐厅的环境极佳。", "error_description": "词序错误：“极”是程度副词，应放在“佳”前面，说“极佳”，不说“佳极”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次演出的效果很最佳。", "corrected_sentence": "这次演出的效果最佳。", "error_description": "副词重复：“最佳”已经表示最高程度，前面不能再加“很”，应说“最佳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
