INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96494, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好的；美好的。", "primary_collocate": null, "pronunciation": "jiā", "ipa": "tɕja˥", "syllable_count": 1, "sentences": [{"text": "他最近心情佳，常常面带笑容。", "target_word": "佳", "complexity_tier": "T3", "furigana": "tā zuì jìn xīn qíng jiā, cháng cháng miàn dài xiào róng.", "sentence_source": "generated"}, {"text": "这家店的环境佳，客人都愿意久坐。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè jiā diàn de huán jìng jiā, kè rén dōu yuàn yì jiǔ zuò.", "sentence_source": "generated"}, {"text": "今年收成佳，农民都很高兴。", "target_word": "佳", "complexity_tier": "T3", "furigana": "jīn nián shōu chéng jiā, nóng mín dōu hěn gāo xìng.", "sentence_source": "generated"}, {"text": "他的人缘佳，同学们都喜欢他。", "target_word": "佳", "complexity_tier": "T3", "furigana": "tā de rén yuán jiā, tóng xué men dōu xǐ huan tā.", "sentence_source": "generated"}, {"text": "这个小区网络信号佳，视频不卡。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè ge xiǎo qū wǎng luò xìn hào jiā, shì pín bù kǎ.", "sentence_source": "generated"}, {"text": "父亲身体佳，每天都去公园散步。", "target_word": "佳", "complexity_tier": "T3", "furigana": "fù qīn shēn tǐ jiā, měi tiān dōu qù gōng yuán sàn bù.", "sentence_source": "generated"}, {"text": "这款药的疗效佳，患者反映很好。", "target_word": "佳", "complexity_tier": "T3", "furigana": "zhè kuǎn yào de liáo xiào jiā, huàn zhě fǎn yìng hěn hǎo.", "sentence_source": "generated"}, {"text": "今天路况佳，我们提前到了。", "target_word": "佳", "complexity_tier": "T3", "furigana": "jīn tiān lù kuàng jiā, wǒ men tí qián dào le.", "sentence_source": "generated"}, {"text": "孩子胃口佳，一顿能吃两碗饭。", "target_word": "佳", "complexity_tier": "T3", "furigana": "hái zi wèi kǒu jiā, yí dùn néng chī liǎng wǎn fàn.", "sentence_source": "generated"}, {"text": "奶奶睡眠佳，每晚都睡得很香。", "target_word": "佳", "complexity_tier": "T3", "furigana": "nǎi nai shuì mián jiā, měi wǎn dōu shuì de hěn xiāng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "不佳", "label": "否定形式"}, {"form": "欠佳", "label": "否定形式"}, {"form": "佳话", "label": "复合词"}], "register": "书面", "sense_fingerprint": "好的、美好的：书面语，多用于心情、身体、人缘、路况等状况良好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "佳", "is_correct": true, "explanation": "佳：jiā，此处意思是好的、美好的，与听到的音相符。"}, {"text": "甲", "is_correct": false, "explanation": "甲：jiǎ（第三声）与 jiā（第一声）声调不同，意思是甲（天干之一、甲方）。"}, {"text": "间", "is_correct": false, "explanation": "间：jiān 比 jiā 多了韵尾 n，声调相同，意思是房间。"}, {"text": "讲", "is_correct": false, "explanation": "讲：jiǎng 与 jiā 韵尾不同（ng），声调也不同，意思是讲话。"}, {"text": "江", "is_correct": false, "explanation": "江：jiāng 比 jiā 多了韵尾 ng，意思是江河。"}], "explanations": {"佳": "佳：jiā，此处意思是好的、美好的，与听到的音相符。", "甲": "甲：jiǎ（第三声）与 jiā（第一声）声调不同，意思是甲（天干之一、甲方）。", "间": "间：jiān 比 jiā 多了韵尾 n，声调相同，意思是房间。", "讲": "讲：jiǎng 与 jiā 韵尾不同（ng），声调也不同，意思是讲话。", "江": "江：jiāng 比 jiā 多了韵尾 ng，意思是江河。"}, "sentence_index": null, "correct_answer": "佳"}, "level_3": {"options": [{"text": "佳", "is_correct": true, "explanation": "佳：好的、美好的，与“常常面带笑容”呼应。"}, {"text": "差", "is_correct": false, "explanation": "语义：“心情差”与后句“常常面带笑容”明显矛盾。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“心情”不说“冷”，一般说“好、差、低落”。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：形容心情不用“硬”，这个词不能修饰“心情”。"}], "explanations": {"佳": "佳：好的、美好的，与“常常面带笑容”呼应。", "差": "语义：“心情差”与后句“常常面带笑容”明显矛盾。", "冷": "搭配：“心情”不说“冷”，一般说“好、差、低落”。", "硬": "搭配：形容心情不用“硬”，这个词不能修饰“心情”。"}, "sentence_index": 0, "correct_answer": "佳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子很佳，站在人群里很显眼。", "explanation": "这里应该用〈高〉。“佳”用于事物的好坏、美好，不用来形容个子的高低，个子高要说“高”。"}, {"text": "这栋楼的层数很佳，有三十层。", "explanation": "这里应该用〈多〉。“佳”不用来形容数量，层数多要说“多”。"}, {"text": "这间屋子的面积很佳，住三口人很宽敞。", "explanation": "这里应该用〈大〉。“佳”不用来形容面积，面积大要说“大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96494, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "佳", "is_correct": true, "explanation": "佳：jiā，此处意思是好的、美好的，与听到的音相符。"}, {"text": "价", "is_correct": false, "explanation": "价：jià（第四声）与 jiā（第一声）声调不同，意思是价格。"}, {"text": "假", "is_correct": false, "explanation": "假：jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的、虚假。"}, {"text": "件", "is_correct": false, "explanation": "件：jiàn（第四声）与 jiā 韵尾与声调都不同，意思是量词，指一件事物。"}, {"text": "见", "is_correct": false, "explanation": "见：jiàn（第四声）与 jiā 韵尾与声调都不同，意思是看见。"}], "explanations": {"佳": "佳：jiā，此处意思是好的、美好的，与听到的音相符。", "价": "价：jià（第四声）与 jiā（第一声）声调不同，意思是价格。", "假": "假：jiǎ（第三声）与 jiā（第一声）声调不同，意思是假的、虚假。", "件": "件：jiàn（第四声）与 jiā 韵尾与声调都不同，意思是量词，指一件事物。", "见": "见：jiàn（第四声）与 jiā 韵尾与声调都不同，意思是看见。"}, "sentence_index": null, "correct_answer": "佳"}, "level_3": {"options": [{"text": "佳", "is_correct": true, "explanation": "佳：好的，与“患者反映很好”相符。"}, {"text": "低", "is_correct": false, "explanation": "语义：“疗效低”与后句“患者反映很好”矛盾。"}, {"text": "弱", "is_correct": false, "explanation": "语义：“疗效弱”与后句“患者反映很好”矛盾。"}, {"text": "浅", "is_correct": false, "explanation": "搭配：“疗效”不说“浅”，“浅”多用于水、知识等。"}], "explanations": {"佳": "佳：好的，与“患者反映很好”相符。", "低": "语义：“疗效低”与后句“患者反映很好”矛盾。", "弱": "语义：“疗效弱”与后句“患者反映很好”矛盾。", "浅": "搭配：“疗效”不说“浅”，“浅”多用于水、知识等。"}, "sentence_index": 6, "correct_answer": "佳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子很佳，十个人都搬不动。", "explanation": "这里应该用〈重〉。“佳”不用来形容分量，东西沉要说“重”。"}, {"text": "我跑得很佳，每次比赛都是第一。", "explanation": "这里应该用〈快〉。“佳”不用来形容速度。"}, {"text": "这里离车站很佳，走路只要十分钟。", "explanation": "这里应该用〈近〉。“佳”不用来形容距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他最近的状态佳不，要多休息。", "corrected_sentence": "他最近的状态不佳，要多休息。", "error_description": "否定词位置错误：“不”应放在“佳”前面，说“不佳”，不说“佳不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的睡眠质量很最佳，精神很好。", "corrected_sentence": "他的睡眠质量最佳，精神很好。", "error_description": "副词重复：“最佳”已经表示最高程度，前面不能再加“很”，应说“最佳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
