INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西有多有用，能满足我们什么需要。", "primary_collocate": null, "pronunciation": "shǐ yòng jià zhí", "ipa": "ʂɻ̩˨˩ jʊŋ˥˩ tɕja˥˩ ʈʂɻ̩˧˥", "syllable_count": 4, "sentences": [{"text": "这把旧椅子还有使用价值，别扔。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器太旧，已经没有使用价值了。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西以前，我会先想它的使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小工具使用价值很高，每天都用。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书的使用价值在于读，不在于好看。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具太小，使用价值不大。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本词典使用价值大，学生都爱用。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏了的手机没有使用价值，我把它扔了。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，选工具要看它的使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个破箱子虽然旧了，但使用价值还在。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西有用的程度，能满足日常需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用价值", "is_correct": true, "explanation": "“使用价值”指东西有用、能满足需要的程度，与“还有”和“别扔”的语境相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温只属于活的生物，椅子没有体温，句子不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格指人或动物的特点，椅子不能有性格。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”多用于人，不用于椅子，“还有年纪”不通。"}], "explanations": {"使用价值": "“使用价值”指东西有用、能满足需要的程度，与“还有”和“别扔”的语境相符。", "体温": "语义：体温只属于活的生物，椅子没有体温，句子不通。", "性格": "语义：性格指人或动物的特点，椅子不能有性格。", "年纪": "搭配：“年纪”多用于人，不用于椅子，“还有年纪”不通。"}, "sentence_index": 0, "correct_answer": "使用价值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的使用价值很高，大家都想买。", "explanation": "这里应该用〈艺术价值〉。画的价值在于艺术和欣赏，“使用价值”指物品满足日常需要的效用，不用于画。"}, {"text": "这位同事的使用价值很高，大家都愿意跟他合作。", "explanation": "这里应该用〈利用价值〉。“使用价值”只用于物品，说人有用要用“利用价值”。"}, {"text": "这首歌的使用价值很高，大家都在听。", "explanation": "这里应该用〈欣赏价值〉。歌曲的价值在于欣赏，不在于满足生活需要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用价值", "is_correct": true, "explanation": "“使用价值”指词典有用的程度，“这本词典___大”的说法成立。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格的高低说“高”或“低”，不说“大”。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指人的体型，词典没有身材。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，词典没有脾气，与“学生都爱用”的语境也不合。"}], "explanations": {"使用价值": "“使用价值”指词典有用的程度，“这本词典___大”的说法成立。", "价格": "搭配：价格的高低说“高”或“低”，不说“大”。", "身材": "语义：“身材”指人的体型，词典没有身材。", "脾气": "语义：“脾气”指人的性情，词典没有脾气，与“学生都爱用”的语境也不合。"}, "sentence_index": 6, "correct_answer": "使用价值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个破箱子的使用价值很有名，人人都知道。", "explanation": "这里应该用〈大〉。“有名”说人或事物出名，不用于“使用价值”。"}, {"text": "这个破箱子的使用价值很沉重，我抬不动。", "explanation": "这里应该用〈大〉。“沉重”形容重量或心情，不用于“使用价值”。"}, {"text": "我把这个破箱子的使用价值搬到了楼上。", "explanation": "“使用价值”是抽象的用处，不能搬动；应说“把这个破箱子搬到了楼上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种旧工具很使用价值，我们留着吧。", "corrected_sentence": "这种旧工具有使用价值，我们留着吧。", "error_description": "错误：动词“有”被换成副词“很”，“很”不能修饰名词“使用价值”。正确：应为“有使用价值”，表示具有用处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张旧桌子还使用价值，我们先留着。", "corrected_sentence": "这张旧桌子还有使用价值，我们先留着。", "error_description": "错误：“还使用价值”漏掉了动词“有”。正确：应为“还有使用价值”，表示仍然具有用处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
