INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物品能够满足人的某种需要的效用。", "primary_collocate": null, "pronunciation": "shǐ yòng jià zhí", "ipa": "ʂɻ̩˨˩ jʊŋ˥˩ tɕja˥˩ ʈʂɻ̩˧˥", "syllable_count": 4, "sentences": [{"text": "商品要有使用价值，人们才会买。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包的使用价值是让人吃饱。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一件商品有价格，也有使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水的使用价值很大，因为人人都要喝水。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人需要的东西，就没有使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济课上，老师讲了商品的使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一把伞的使用价值是挡雨。", "target_word": "使用价值", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "衣服的使用价值是保暖，也能让人好看。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商品的使用价值不同，价格也会不同。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了这把刀，是看中它的使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "商品满足人某种需要的效用（经济学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用价值", "is_correct": true, "explanation": "“使用价值”指商品满足人需要的效用，与“要有”“人们才会买”相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指生物的温度，商品没有体温。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”形容人的性情，商品不说脾气。"}, {"text": "气色", "is_correct": false, "explanation": "体貌：“气色”指人的脸色，商品没有气色。"}], "explanations": {"使用价值": "“使用价值”指商品满足人需要的效用，与“要有”“人们才会买”相符。", "体温": "语义：体温指生物的温度，商品没有体温。", "脾气": "语义：“脾气”形容人的性情，商品不说脾气。", "气色": "体貌：“气色”指人的脸色，商品没有气色。"}, "sentence_index": 0, "correct_answer": "使用价值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的使用价值是五十元。", "explanation": "这里应该用〈价格〉。使用价值说的是商品的效用，不是用金额表示的价钱。"}, {"text": "这套邮票的使用价值很高，大家都想买。", "explanation": "这里应该用〈收藏价值〉。邮票的价值在于收藏，不在于满足日常需要。"}, {"text": "这张纸币的使用价值是一百元。", "explanation": "这里应该用〈面值〉。纸币上印的一百元是面值，不是使用价值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用价值", "is_correct": true, "explanation": "“使用价值”指伞能满足挡雨需要的效用，与“是挡雨”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用来挡雨，与“是挡雨”的说明不符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或动物的高度，伞没有身高。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能用来挡雨，与“是挡雨”不符。"}], "explanations": {"使用价值": "“使用价值”指伞能满足挡雨需要的效用，与“是挡雨”相符。", "颜色": "语义：“颜色”不能用来挡雨，与“是挡雨”的说明不符。", "身高": "语义：“身高”指人或动物的高度，伞没有身高。", "价格": "语义：“价格”指钱数，不能用来挡雨，与“是挡雨”不符。"}, "sentence_index": 6, "correct_answer": "使用价值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把刀的使用价值是八十块钱。", "explanation": "这里应该用〈价格〉。使用价值指东西的用处，不是用钱数表示的价钱。"}, {"text": "这枚古钱币的使用价值很高，博物馆想收藏。", "explanation": "这里应该用〈收藏价值〉。古钱币被看重的是收藏意义，不是满足日常需要的用处。"}, {"text": "这位歌手的使用价值很高，演唱会票都卖完了。", "explanation": "这里应该用〈人气〉。“使用价值”用于物品的用处，不用来说人受欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种新材料很使用价值，工厂都在用。", "corrected_sentence": "这种新材料有使用价值，工厂都在用。", "error_description": "错误：动词“有”被换成副词“很”，“很”不能修饰名词“使用价值”。正确：应为“有使用价值”，表示具有用处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种商品被使用价值，大家都需要。", "corrected_sentence": "这种商品有使用价值，大家都需要。", "error_description": "错误：“被”后应接动词，不能直接接名词“使用价值”。正确：应为“有使用价值”，表示具有用处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
