INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "马路旁边给人走的小路。", "primary_collocate": null, "pronunciation": "biàn dào", "ipa": "pjɛn˥˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "行人请走便道，不要走马路。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "便道上有很多落叶。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车上了便道。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在便道上慢慢走。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路旁边的便道很窄。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨后，便道上都是水。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把车停在便道上。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着便道往前走。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条便道刚修好。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "便道旁边种着一排树。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "口语", "sense_fingerprint": "马路旁边供行人走的小路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便道", "is_correct": true, "explanation": "“便道”指马路旁供行人走的小路，与“不要走马路”形成对比，搭配自然。"}, {"text": "楼梯", "is_correct": false, "explanation": "语义：楼梯在建筑内，不在马路旁，与“不要走马路”的对比不合。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“走”不接交通工具，应说“乘地铁”。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯是升降设备，行人不能“走”电梯，与“不要走马路”的对比不合。"}], "explanations": {"便道": "“便道”指马路旁供行人走的小路，与“不要走马路”形成对比，搭配自然。", "楼梯": "语义：楼梯在建筑内，不在马路旁，与“不要走马路”的对比不合。", "地铁": "搭配：“走”不接交通工具，应说“乘地铁”。", "电梯": "语义：电梯是升降设备，行人不能“走”电梯，与“不要走马路”的对比不合。"}, "sentence_index": 0, "correct_answer": "便道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "便道里很暗，我摸着墙走。", "explanation": "这里应该用〈楼道〉。便道指马路旁供行人走的路，不指楼里的通道。"}, {"text": "行人应该在便道上过马路。", "explanation": "这里应该用〈人行横道〉。便道沿马路边，不是横穿马路的通道。"}, {"text": "这条便道很高，行人要走很长的台阶才能上去。", "explanation": "这里应该用〈天桥〉。便道是路边的平路，不指高处的人行通道；高处供行人过马路的通道要说“天桥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便道", "is_correct": true, "explanation": "“便道”指马路旁供行人走的路，“请不要把车停在便道上”是禁止占用人行道的提醒，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能停车，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱上不能停车，句意不通。"}, {"text": "河面", "is_correct": false, "explanation": "搭配：“停在…上”要求能承载车辆的地面，河面不能停车。"}], "explanations": {"便道": "“便道”指马路旁供行人走的路，“请不要把车停在便道上”是禁止占用人行道的提醒，句意通顺。", "桌子": "语义：桌子不能停车，句意不通。", "冰箱": "语义：冰箱上不能停车，句意不通。", "河面": "搭配：“停在…上”要求能承载车辆的地面，河面不能停车。"}, "sentence_index": 6, "correct_answer": "便道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客厅的便道很干净。", "explanation": "这里应该用〈地板〉。便道是室外路边供行人走的路，不用于室内。"}, {"text": "抽屉里放着便道。", "explanation": "这里应该用〈钥匙〉。便道是路边的步行路，不能放进抽屉。"}, {"text": "厨房的便道要定期检查。", "explanation": "这里应该用〈管道〉。便道是路边给行人走的路，不指厨房里的管道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路边新修了一条便道们。", "corrected_sentence": "路边新修了一条便道。", "error_description": "用法错误：“便道”是无生命的事物，不能加“们”表示复数，应说“一条便道”，不说“便道们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆便道又窄又长。", "corrected_sentence": "这条便道又窄又长。", "error_description": "量词错误：“便道”应与“条”搭配，“辆”用于车辆，不能说“这辆便道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
