INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大路旁供行人行走的道路；人行道。", "primary_collocate": null, "pronunciation": "biàn dào", "ipa": "pjɛn˥˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "学校门口的便道修得很宽。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢走在便道上。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "便道和马路中间有一排花。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自行车推上了便道。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "便道上的人越来越多。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路前，请先站在便道上。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的便道刚铺了新砖。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天走便道去地铁站。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "便道旁边有一家小花店。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车不能开上便道。", "target_word": "便道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "口语", "sense_fingerprint": "大路旁供行人行走的道路，即人行道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便道", "is_correct": true, "explanation": "“便道”指大路旁供行人走的道路，“学校门口的便道修得很宽”自然。"}, {"text": "课程", "is_correct": false, "explanation": "搭配：“修”接道路、房屋，不接课程。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是桌子，不是门口可以修宽的道路。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是练习任务，不是能修宽的东西。"}], "explanations": {"便道": "“便道”指大路旁供行人走的道路，“学校门口的便道修得很宽”自然。", "课程": "搭配：“修”接道路、房屋，不接课程。", "课桌": "语义：课桌是桌子，不是门口可以修宽的道路。", "作业": "语义：作业是练习任务，不是能修宽的东西。"}, "sentence_index": 0, "correct_answer": "便道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着便道上楼。", "explanation": "这里应该用〈楼梯〉。便道是路边给行人走的路，不能用来上楼。"}, {"text": "我把便道放进了书包里。", "explanation": "这里应该用〈课本〉。便道是路边供行人走的路，不能放进书包。"}, {"text": "书架上摆着很多便道。", "explanation": "这里应该用〈书〉。便道是路边的步行路，不能摆在书架上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便道", "is_correct": true, "explanation": "“便道”指大路旁供行人走的道路，可以铺新砖，搭配自然。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能铺砖，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能铺砖，句意不通。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“铺”接地面、路面，不接水体。"}], "explanations": {"便道": "“便道”指大路旁供行人走的道路，可以铺新砖，搭配自然。", "树": "语义：树不能铺砖，句意不通。", "天空": "语义：天空不能铺砖，句意不通。", "河水": "搭配：“铺”接地面、路面，不接水体。"}, "sentence_index": 6, "correct_answer": "便道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "便道很高，行人走上去很累。", "explanation": "这里应该用〈天桥〉。便道是路边给行人走的平路，不指高架的人行通道。"}, {"text": "教室的便道刚擦过。", "explanation": "这里应该用〈黑板〉。便道是室外路边的步行路，不用于教室。"}, {"text": "天花板上挂着一条便道。", "explanation": "这里应该用〈灯〉。便道是路边供行人走的路，不能挂在天花板上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们走了三条便道们。", "corrected_sentence": "我们走了三条便道。", "error_description": "用法错误：“便道”是无生命的事物，不能加“们”表示复数，应说“三条便道”，不说“便道们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口有一张便道。", "corrected_sentence": "门口有一条便道。", "error_description": "量词错误：应说“一条便道”，“张”用于平面的东西，不用于“便道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
