INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "说“我保证他会做到”的人。", "primary_collocate": null, "pronunciation": "bǎo zhèng rén", "ipa": "pɑʊ˨˩˦ ʈʂɤŋ˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他是我的保证人，我很放心。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王做事靠谱，朋友愿意当他的保证人。", "target_word": "保证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“我是他的保证人。”", "target_word": "保证人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说话算数，我愿意做他的保证人。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人给他当保证人，他很难过。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我相信弟弟，所以做了他的保证人。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的保证人说你一定会来。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他答应老师不再迟到，班长愿意做他的保证人。", "target_word": "保证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈是我最好的保证人，她知道我不会说谎。", "target_word": "保证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁愿意给这个孩子当保证人？", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位保证人", "label": "量词（位）"}, {"form": "保證人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为某人的品行或承诺作保、说他一定能做到的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4a1f6f-7ab9-4f4b-aa6d-3fc7424745ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：人不能是书包，“他是我的书包”不成立。"}, {"text": "保证人", "is_correct": true, "explanation": "正确：保证人是为他人的品行或承诺作保的人，与“我很放心”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“我很放心”要依托能让人信赖的人或事，“是……的天气”不是可以托付的对象。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不能用“是我的……”指人，句子不通。"}], "explanations": {"书包": "语义：人不能是书包，“他是我的书包”不成立。", "保证人": "正确：保证人是为他人的品行或承诺作保的人，与“我很放心”相符。", "天气": "搭配：“我很放心”要依托能让人信赖的人或事，“是……的天气”不是可以托付的对象。", "地铁": "语义：地铁是交通工具，不能用“是我的……”指人，句子不通。"}, "sentence_index": 0, "correct_answer": "保证人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "婚礼上，他是新郎的保证人，并在结婚证上签了字。", "explanation": "这里应该用〈见证人〉。见证人只在场证明事情经过，不对承诺负责；保证人要为某人的品行或承诺作保。"}, {"text": "他是这个孩子的保证人，每天负责接送他上学。", "explanation": "这里应该用〈监护人〉。监护人负责照顾未成年人的日常生活，保证人只为某人的承诺作保，不负责照顾。"}, {"text": "他是我的保证人，每天带我练习跑步。", "explanation": "这里应该用〈教练〉。教练指导训练，保证人不做指导，只为别人的承诺作保。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业不会说话，“作业说你一定会来”不成立。"}, {"text": "窗帘", "is_correct": false, "explanation": "配价：“说”的主语必须能说话，窗帘不能充当说话的人。"}, {"text": "保证人", "is_correct": true, "explanation": "正确：保证人为你的承诺作保，可以说“你一定会来”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不能“说”话，与句子的语境不符。"}], "explanations": {"作业": "语义：作业不会说话，“作业说你一定会来”不成立。", "窗帘": "配价：“说”的主语必须能说话，窗帘不能充当说话的人。", "保证人": "正确：保证人为你的承诺作保，可以说“你一定会来”。", "雨伞": "语义：雨伞是物品，不能“说”话，与句子的语境不符。"}, "sentence_index": 6, "correct_answer": "保证人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的保证人在法庭上替我辩护。", "explanation": "这里应该用〈律师〉。律师代理诉讼、替人辩护；保证人只为某人的品行或承诺作保，不在法庭上辩护。"}, {"text": "他是我的保证人，帮我认识了新朋友。", "explanation": "这里应该用〈介绍人〉。介绍人为人牵线、引荐，保证人是为承诺负责的人，不负责介绍。"}, {"text": "我的保证人每天给我下达任务，我要向他汇报工作。", "explanation": "这里应该用〈上司〉。上司对下属下达任务，保证人与工作安排无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师愿意做他的一把保证人。", "corrected_sentence": "老师愿意做他的一位保证人。", "error_description": "量词误用：“保证人”指人，不能用“把”（“把”多用于有柄的物件），应说“一位保证人”或“一个保证人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子需要一只保证人。", "corrected_sentence": "这个孩子需要一位保证人。", "error_description": "量词错误：“保证人”指人，不能用“只”（“只”多用于动物），应说“一位保证人”或“一个保证人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
