INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96500, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为他人履行义务提供担保的人。", "primary_collocate": null, "pronunciation": "bǎo zhèng rén", "ipa": "pɑʊ˨˩˦ ʈʂɤŋ˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "租房子时，房东要我找一个保证人。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贷款需要有保证人。", "target_word": "保证人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他还不上钱，保证人只好替他还。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我请叔叔为我的贷款当保证人，他同意了。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行要求保证人在合同上签字。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保证人要对借款人的欠款负责。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有工作，银行要他找保证人。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份合同需要两个保证人。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做保证人要小心，别随便签字。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友借钱，我当了保证人，后来替他还了钱。", "target_word": "保证人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位保证人", "label": "量词（位）"}, {"form": "保證人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在贷款、租房、合同中，对他人的债务或义务承担担保责任的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4a1f6f-7ab9-4f4b-aa6d-3fc7424745ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟与“租房子”的语境不符，房东不会要求找闹钟。"}, {"text": "保证人", "is_correct": true, "explanation": "正确：租房时房东要求找能为租金或合同责任担保的人。"}, {"text": "合同", "is_correct": false, "explanation": "语义：合同是文件，不能充当可以找来担保的人，与租房担保的语境不符。"}, {"text": "脸盆", "is_correct": false, "explanation": "语义：脸盆是生活用品，与租房时找担保人的语境不符。"}], "explanations": {"闹钟": "语义：闹钟与“租房子”的语境不符，房东不会要求找闹钟。", "保证人": "正确：租房时房东要求找能为租金或合同责任担保的人。", "合同": "语义：合同是文件，不能充当可以找来担保的人，与租房担保的语境不符。", "脸盆": "语义：脸盆是生活用品，与租房时找担保人的语境不符。"}, "sentence_index": 0, "correct_answer": "保证人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "保证人帮我找到了合适的房子，我很感谢他。", "explanation": "这里应该用〈中介〉。中介负责介绍房源；保证人只为债务或义务担保，不负责找房。"}, {"text": "保证人要照顾未成年的孩子，每天接送他上学。", "explanation": "这里应该用〈监护人〉。监护人负责照顾未成年人；保证人只承担债务或义务的担保责任。"}, {"text": "法庭上他作为保证人，讲述了事发经过。", "explanation": "这里应该用〈证人〉。证人在法庭上陈述所见的事实；保证人只对债务或义务负担保责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利息", "is_correct": false, "explanation": "语义：利息是利钱，不是可以去找的人，与“他没有工作”的语境不符。"}, {"text": "发票", "is_correct": false, "explanation": "语义：发票是收据，不能充当担保的人，与“银行要他找……”的语境不符。"}, {"text": "保证人", "is_correct": true, "explanation": "正确：银行要求借款人找能承担还款责任的保证人。"}, {"text": "签名", "is_correct": false, "explanation": "语义：签名是签字的动作或字迹，不能充当担保的人。"}], "explanations": {"利息": "语义：利息是利钱，不是可以去找的人，与“他没有工作”的语境不符。", "发票": "语义：发票是收据，不能充当担保的人，与“银行要他找……”的语境不符。", "保证人": "正确：银行要求借款人找能承担还款责任的保证人。", "签名": "语义：签名是签字的动作或字迹，不能充当担保的人。"}, "sentence_index": 6, "correct_answer": "保证人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保证人替我打官司，我很感谢他。", "explanation": "这里应该用〈律师〉。律师代理诉讼；保证人只承担债务或义务的担保，不替人打官司。"}, {"text": "保证人把房子租给我，每个月收房租。", "explanation": "这里应该用〈房东〉。房东是出租房屋的人；保证人只在债务或义务上承担责任，不出租房屋。"}, {"text": "保证人借钱给我，我要按期还钱。", "explanation": "这里应该用〈债主〉。债主是借出钱的人；保证人是在借款人违约时承担责任的人，不借钱给人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "房东要我找一只保证人。", "corrected_sentence": "房东要我找一个保证人。", "error_description": "量词错误：“保证人”指人，不能用“只”，应说“一个保证人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友向银行借钱，我当了一张保证人，后来替他还了钱。", "corrected_sentence": "朋友向银行借钱，我当了一个保证人，后来替他还了钱。", "error_description": "量词误用：“保证人”指人，不能用“张”（“张”多用于平面的东西），应改为“一个保证人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '358150e7-3a0f-4a07-97ae-4de879a45ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96501, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96501, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96501, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "银行把钱借给别人，以后再还。", "primary_collocate": null, "pronunciation": "xìn dài", "ipa": "ɕin˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "银行给小公司提供信贷。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的信贷很方便。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向银行申请了一笔信贷。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子可以用信贷，慢慢还钱。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民需要信贷来买种子。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行不给没有工作的人信贷。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信贷让他开了一家小店。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用信贷买了一辆新车。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的信贷要按时还。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司缺钱时，常常去找银行申请信贷。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "银行借给个人或公司的钱，日后要偿还", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96501, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信贷", "is_correct": true, "explanation": "正确。“提供信贷”指银行借出钱，与句子语境相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：银行不提供食物，与银行的业务不符。"}, {"text": "教材", "is_correct": false, "explanation": "语义：银行不提供教材，与银行给小公司的服务不符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“提供”的对象应是资金、服务之类，“体温”不能被提供。"}], "explanations": {"信贷": "正确。“提供信贷”指银行借出钱，与句子语境相符。", "食物": "语义：银行不提供食物，与银行的业务不符。", "教材": "语义：银行不提供教材，与银行给小公司的服务不符。", "体温": "搭配：“提供”的对象应是资金、服务之类，“体温”不能被提供。"}, "sentence_index": 0, "correct_answer": "信贷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月都往银行存信贷，攒下一笔钱。", "explanation": "这里应该用〈存款〉。信贷是银行借出的钱，不能存入银行。"}, {"text": "他拿到了一只信贷，马上去买了车。", "explanation": "这里应该用〈笔〉。信贷用量词“笔”，不用“只”。"}, {"text": "我去银行取信贷。", "explanation": "这里应该用〈钱〉。信贷是银行借出的钱，不能像存款那样去银行取出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信贷", "is_correct": true, "explanation": "正确。“信贷让他开了一家小店”指借来的钱帮他开店，与语境相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒不能帮人开店，与“让他开了一家小店”的因果关系不通。"}, {"text": "鞭炮", "is_correct": false, "explanation": "语义：鞭炮与开店没有因果关系，不能使人开店。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“让”后面要接能促成行动的人或事，“树叶”与“让他开店”搭配不通。"}], "explanations": {"信贷": "正确。“信贷让他开了一家小店”指借来的钱帮他开店，与语境相符。", "感冒": "语义：感冒不能帮人开店，与“让他开了一家小店”的因果关系不通。", "鞭炮": "语义：鞭炮与开店没有因果关系，不能使人开店。", "树叶": "搭配：“让”后面要接能促成行动的人或事，“树叶”与“让他开店”搭配不通。"}, "sentence_index": 6, "correct_answer": "信贷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小公司缺钱时，常常去卖信贷。", "explanation": "这里应该用〈机器〉。信贷是借来的钱，不能像机器那样卖出。"}, {"text": "小公司缺钱时，常常去找朋友要一笔信贷。", "explanation": "这里应该用〈借款〉。信贷是银行等机构的借贷业务，不能向朋友要。"}, {"text": "小公司缺钱时，常常先交一笔信贷。", "explanation": "这里应该用〈保证金〉。信贷是借来的钱，不能当作要交的费用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拿到了一个信贷，买了一辆货车。", "corrected_sentence": "他拿到了一笔信贷，买了一辆货车。", "error_description": "量词错误。“信贷”应用量词“笔”，不能用“个”。正确说法是“一笔信贷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他申请了一笔信贷，准备了开店。", "corrected_sentence": "他申请了一笔信贷，准备开店。", "error_description": "助词错误。“准备”后面不能加“了”，应说“准备开店”，去掉“了”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
