INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "银行等机构以还本付息为条件的借贷活动。", "primary_collocate": null, "pronunciation": "xìn dài", "ipa": "ɕin˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "国家放松了信贷，企业借钱更容易。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的信贷业务越来越多。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年银行收紧信贷，贷款变难了。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信贷增长太快，会有风险。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行专门做农村信贷。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信贷政策影响着很多公司。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行的信贷部门工作。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信贷市场最近很稳定。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行做信贷时，要先看客户的收入。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信贷工作需要认真和细心。", "target_word": "信贷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "银行等机构开展的有偿借贷业务与政策", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信贷", "is_correct": true, "explanation": "正确。“放松了信贷”指放宽银行借贷的限制，企业借钱因此更容易。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“放松”多用于限制、管制，不能用于“作业”。"}, {"text": "皮带", "is_correct": false, "explanation": "语义：放松皮带与企业借钱容易与否没有关系。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重不能“放松”，这一搭配不通。"}], "explanations": {"信贷": "正确。“放松了信贷”指放宽银行借贷的限制，企业借钱因此更容易。", "作业": "搭配：“放松”多用于限制、管制，不能用于“作业”。", "皮带": "语义：放松皮带与企业借钱容易与否没有关系。", "体重": "搭配：体重不能“放松”，这一搭配不通。"}, "sentence_index": 0, "correct_answer": "信贷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的信贷很好，朋友都愿意帮他。", "explanation": "这里应该用〈信用〉。信贷指银行等机构的借贷业务，不能用来形容个人的诚信。"}, {"text": "他的信贷刷爆了，只好先还钱。", "explanation": "这里应该用〈信用卡〉。信贷是银行借贷业务，不是能刷的卡，“刷爆了”只能用于信用卡。"}, {"text": "他给汽车买了信贷。", "explanation": "这里应该用〈保险〉。信贷是借来的钱，不能“购买”，应说“买保险”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信贷", "is_correct": true, "explanation": "正确。“银行的信贷部门”是银行负责贷款业务的部门，与句子相符。"}, {"text": "足球", "is_correct": false, "explanation": "语义：银行没有足球部门，与“在银行工作”的语境不符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：银行没有植物部门，与“银行的……部门”的语境不符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是场所，不能用作“……部门”的名称，搭配不通。"}], "explanations": {"信贷": "正确。“银行的信贷部门”是银行负责贷款业务的部门，与句子相符。", "足球": "语义：银行没有足球部门，与“在银行工作”的语境不符。", "植物": "语义：银行没有植物部门，与“银行的……部门”的语境不符。", "厨房": "搭配：“厨房”是场所，不能用作“……部门”的名称，搭配不通。"}, "sentence_index": 6, "correct_answer": "信贷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "银行向客户收取了信贷。", "explanation": "这里应该用〈手续费〉。信贷是借出的钱，不能被“收取”，收取的应是手续费。"}, {"text": "这个月公司给他多发了五百元信贷。", "explanation": "这里应该用〈工资〉。信贷是银行的借贷业务，不是公司发给员工的钱。"}, {"text": "租房时要交信贷。", "explanation": "这里应该用〈押金〉。信贷是借来的钱，不能作为要交的费用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国家放松了信贷，企业借钱更难了。", "corrected_sentence": "国家收紧了信贷，企业借钱更难了。", "error_description": "搭配与语义错误。放松信贷会让借钱更容易；借钱更难应是“收紧信贷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他办了一笔信贷，准备了开工厂。", "corrected_sentence": "他办了一笔信贷，准备开工厂。", "error_description": "助词错误。“准备”后面不能加“了”，应说“准备开工厂”，去掉“了”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
