INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事调查案件、搜集线索的人。", "primary_collocate": null, "pronunciation": "zhēn tàn", "ipa": "ʈʂən˥ tʰan˥˩", "syllable_count": 2, "sentences": [{"text": "这位侦探花了三天时间调查这个案子。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当一名侦探。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侦探在房间里找到了一把旧钥匙。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察请侦探帮忙查这起失踪案。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位私人侦探每天都跟着他。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侦探仔细看着地上的脚印。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个侦探很聪明，总能发现小线索。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侦探敲了敲门，问里面有没有人。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过很多关于侦探的小说。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老侦探把所有的线索都写在本子上。", "target_word": "侦探", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "私家侦探", "label": "复合词"}, {"form": "侦探小说", "label": "复合词"}], "register": "中性", "sense_fingerprint": "调查案件、搜集线索的职业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侦探", "is_correct": true, "explanation": "正确：“侦探”指调查案件、搜集线索的人，与“调查这个案子”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，不会调查案件，与“调查这个案子”不符。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手的工作是唱歌，与“调查这个案子”的内容无关。"}, {"text": "园丁", "is_correct": false, "explanation": "搭配：“园丁”照料花草，与“调查这个案子”的搭配不成立。"}], "explanations": {"侦探": "正确：“侦探”指调查案件、搜集线索的人，与“调查这个案子”相符。", "厨师": "语义：厨师的工作是做饭，不会调查案件，与“调查这个案子”不符。", "歌手": "语义：歌手的工作是唱歌，与“调查这个案子”的内容无关。", "园丁": "搭配：“园丁”照料花草，与“调查这个案子”的搭配不成立。"}, "sentence_index": 0, "correct_answer": "侦探"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "侦探在工厂车间里负责给机器上油，每天很忙。", "explanation": "这里应该用〈工人〉。给机器上油是〈工人〉的工作；侦探指调查案件、搜集线索的人。"}, {"text": "街口来了一名侦探，正在指挥交通。", "explanation": "这里应该用〈警察〉。侦探只负责调查案件，指挥交通是〈警察〉的工作。"}, {"text": "侦探在法庭上为被告辩护，讲得很有道理。", "explanation": "这里应该用〈律师〉。为被告辩护是〈律师〉的工作，侦探负责调查案件、搜集线索。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侦探", "is_correct": true, "explanation": "正确：“很聪明，总能发现小线索”描写的是查案的人，只有“侦探”合适。"}, {"text": "理发师", "is_correct": false, "explanation": "语义：理发师的工作与发现线索无关，句意不通。"}, {"text": "面包师", "is_correct": false, "explanation": "语义：面包师做面包，与“发现小线索”没有关系。"}, {"text": "洗车工", "is_correct": false, "explanation": "搭配：“洗车工”与“发现小线索”的搭配不成立，洗车工不负责寻找线索。"}], "explanations": {"侦探": "正确：“很聪明，总能发现小线索”描写的是查案的人，只有“侦探”合适。", "理发师": "语义：理发师的工作与发现线索无关，句意不通。", "面包师": "语义：面包师做面包，与“发现小线索”没有关系。", "洗车工": "搭配：“洗车工”与“发现小线索”的搭配不成立，洗车工不负责寻找线索。"}, "sentence_index": 6, "correct_answer": "侦探"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "侦探报道了这场比赛的结果，大家都很关心。", "explanation": "这里应该用〈记者〉。报道新闻是〈记者〉的工作；侦探的工作是调查案件、搜集线索。"}, {"text": "这趟航班是侦探驾驶的，着陆很平稳。", "explanation": "这里应该用〈飞行员〉。驾驶飞机是〈飞行员〉的工作，侦探不驾驶飞机。"}, {"text": "侦探给病人看病，开了药，很认真。", "explanation": "这里应该用〈医生〉。看病、开药是〈医生〉的工作，侦探调查案件、搜集线索。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只侦探找到了偷画的人留下的指纹。", "corrected_sentence": "这位侦探找到了偷画的人留下的指纹。", "error_description": "错误形式：“这只侦探”。“侦探”指人，量词应用“位”或“个”，“只”多用于动物或物品，不用于人。正确形式：“这位侦探”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很聪明侦探，总能找到小线索。", "corrected_sentence": "他是一个很聪明的侦探，总能找到小线索。", "error_description": "错误形式：“很聪明侦探”。形容词“聪明”受“很”修饰后修饰名词时，中间需要结构助词“的”，应为“很聪明的侦探”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
