INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96505, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "竭尽全力去做，使程度或数量达到最高。", "primary_collocate": null, "pronunciation": "jǐn kě néng", "ipa": "tɕin˨˩ kʰɤ˨˩ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "我会尽可能多帮你一点。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尽可能跑得快一点。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你尽可能把字写好。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了考试，她尽可能多做练习。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们尽可能做到最好。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尽可能大声地喊了出来。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她尽可能仔细地检查了作业。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈尽可能让孩子吃好。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，大家要尽可能多读书。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了，但还是尽可能走快些。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全力付出，把程度或数量推到极限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽可能", "is_correct": true, "explanation": "尽可能：在能力范围内尽力做到最多，与“多帮你一点”的句意相符。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与“会”所表示的将来意愿矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指事情出乎意料地发生，不能与“会”所表示的预先打算搭配。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一贯如此的情况，与“会”所指的将来时间矛盾。"}], "explanations": {"尽可能": "尽可能：在能力范围内尽力做到最多，与“多帮你一点”的句意相符。", "已经": "体貌：“已经”表示动作已经完成，与“会”所表示的将来意愿矛盾。", "突然": "语义：“突然”指事情出乎意料地发生，不能与“会”所表示的预先打算搭配。", "从来": "语义：“从来”表示一贯如此的情况，与“会”所指的将来时间矛盾。"}, "sentence_index": 0, "correct_answer": "尽可能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "尽可能有困难，我们也要坚持下去。", "explanation": "这里应该用〈尽管〉。尽可能表示在能力范围内尽力做到，不能表示“即使”的让步；“有困难”不是人能主动去做的事。"}, {"text": "他尽可能高了三公分。", "explanation": "这里应该用〈长〉。尽可能要靠人主动努力去做，身高不能靠努力增加，不能这样用。"}, {"text": "明天尽可能会下雨。", "explanation": "这里应该用〈一定〉。尽可能要求由人主动努力，下雨不由人控制，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽可能", "is_correct": true, "explanation": "尽可能：尽力做到最好，与“仔细地检查”的句意相符。"}, {"text": "一起", "is_correct": false, "explanation": "配价：“一起”需要多个施事共同做，句中只有“她”一个人，搭配不当。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”表示反复持续，句意会变成“反复检查”，与“尽力做到最好”的意思不符。"}, {"text": "猛然", "is_correct": false, "explanation": "语域：“猛然”偏书面，表示突发，与“仔细地”的从容动作不协调。"}], "explanations": {"尽可能": "尽可能：尽力做到最好，与“仔细地检查”的句意相符。", "一起": "配价：“一起”需要多个施事共同做，句中只有“她”一个人，搭配不当。", "不断": "语义：“不断”表示反复持续，句意会变成“反复检查”，与“尽力做到最好”的意思不符。", "猛然": "语域：“猛然”偏书面，表示突发，与“仔细地”的从容动作不协调。"}, "sentence_index": 6, "correct_answer": "尽可能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事尽可能是他做的。", "explanation": "这里应该用〈可能〉。尽可能表示尽力做到的程度，不表示对事情的推测。"}, {"text": "这辆车尽可能坐五个人。", "explanation": "这里应该用〈最多〉。尽可能说的是尽力去做，不能用来说明车辆的人数上限。"}, {"text": "这里尽可能有两个人。", "explanation": "这里应该用〈只有〉。尽可能表示尽力做到的程度，不能表示“仅有”的限定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们尽可能了把工作做好。", "corrected_sentence": "我们尽可能把工作做好。", "error_description": "助词错误。“尽可能”后面不能加“了”，应写作“我们尽可能把工作做好”，去掉“了”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们尽可能了早点交卷，好让老师早点休息。", "corrected_sentence": "我们尽可能早点交卷，好让老师早点休息。", "error_description": "助词错误：“尽可能”后面不能加“了”，应写作“我们尽可能早点交卷”；“了”放在副词后，使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
