INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96506, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在可能的范围内尽量。", "primary_collocate": null, "pronunciation": "jǐn kě néng", "ipa": "tɕin˨˩ kʰɤ˨˩ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "明天请尽可能早点来。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上人多，我们尽可能别迟到。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尽可能少用塑料袋，对环境好。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格尽可能便宜一点吧。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，请尽可能简单地说。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有时间的话，我尽可能去看你。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让我们尽可能少花钱。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事请尽可能保密。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你尽可能多喝水，少喝饮料。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业尽可能今天做完。", "target_word": "尽可能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "受客观条件限制，在可行范围内选取做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8affe85-13e1-4a91-ba83-f38ac8404f62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽可能", "is_correct": true, "explanation": "尽可能：在条件允许的范围内尽量，符合“早点来”的句意。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示已经完成，与“明天”的将来时间矛盾。"}, {"text": "刚", "is_correct": false, "explanation": "体貌：“刚”表示刚刚发生，与“明天”的将来时间矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即，与“明天”的时间安排相互冲突。"}], "explanations": {"尽可能": "尽可能：在条件允许的范围内尽量，符合“早点来”的句意。", "已经": "体貌：“已经”表示已经完成，与“明天”的将来时间矛盾。", "刚": "体貌：“刚”表示刚刚发生，与“明天”的将来时间矛盾。", "马上": "语义：“马上”表示立即，与“明天”的时间安排相互冲突。"}, "sentence_index": 0, "correct_answer": "尽可能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "尽可能天气不好，我们也去爬山。", "explanation": "这里应该用〈尽管〉。尽可能表示尽力做到，不能表示“即使”的让步；天气不好不是人能主动去做的事，不能这样用。"}, {"text": "她尽可能怕黑。", "explanation": "这里应该用〈很〉。尽可能要靠人主动去做，“怕黑”是不能主动控制的感受，不能这样用。"}, {"text": "人尽可能会生病。", "explanation": "这里应该用〈难免〉。尽可能要求人主动努力，生病不由人控制，不能表示“难免”的必然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽可能", "is_correct": true, "explanation": "尽可能：在能力范围内尽量，与“少花钱”的要求相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“让我们”所表示的有意安排矛盾。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意与期望相反，不符合老板一般指令的语境。"}, {"text": "猛然", "is_correct": false, "explanation": "语域：“猛然”偏书面，表示突然发生，不适合这种日常指令的表达。"}], "explanations": {"尽可能": "尽可能：在能力范围内尽量，与“少花钱”的要求相符。", "竟然": "语义：“竟然”表示出乎意料，与“让我们”所表示的有意安排矛盾。", "偏偏": "语义：“偏偏”表示故意与期望相反，不符合老板一般指令的语境。", "猛然": "语域：“猛然”偏书面，表示突然发生，不适合这种日常指令的表达。"}, "sentence_index": 6, "correct_answer": "尽可能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事尽可能是朋友说的。", "explanation": "这里应该用〈可能〉。尽可能表示尽力做到的程度，不表示对事情的推测。"}, {"text": "这间教室尽可能坐五十人。", "explanation": "这里应该用〈最多〉。尽可能说的是尽力去做，不能用来说明教室的容纳上限。"}, {"text": "这间屋子尽可能住两个人。", "explanation": "这里应该用〈只〉。尽可能表示尽力做到，不能表示“仅仅”的限定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你尽可能了早点把材料准备好。", "corrected_sentence": "请你尽可能早点把材料准备好。", "error_description": "助词错误：“尽可能”后面不能直接加“了”。“了”表示动作完成，应放在动词后；正确说法是“请你尽可能早点把材料准备好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板让我们不尽可能省钱。", "corrected_sentence": "老板让我们尽可能省钱。", "error_description": "否定词位置错误：“不”不能放在“尽可能”前面，“不尽可能省钱”不通。应直接说“老板让我们尽可能省钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dfc5cdc-a618-4c3b-8b4a-9af1a3a41d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
