INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按顺序排列成行的清单或表格。", "primary_collocate": null, "pronunciation": "liè biǎo", "ipa": "liɛ˥˩ piɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请看屏幕上的列表。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个列表是按名字排的。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "列表按价格从低到高排列。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机里有一个歌曲列表。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我点开了朋友列表。", "target_word": "列表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的成绩列表贴在墙上。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请在列表里找你的名字。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个列表一共有二十个名字。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把电影按时间排成了一个列表。", "target_word": "列表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上的新闻列表每天都会更新。", "target_word": "列表", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "歌曲列表", "label": "复合"}], "register": "中性", "sense_fingerprint": "按顺序排成一行行的清单或表格，如名单、歌曲单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add11f56-6b71-44e4-ad75-5ff231dc05d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "列表", "is_correct": true, "explanation": "正确：“列表”指按顺序排成行的清单或表格，屏幕上可以显示。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是尝出来的感觉，看不见，不能拿来在屏幕上给人看。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性情，不是可以显示在屏幕上的内容，句意说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是走路的动作，不能显示在屏幕上让人看。"}], "explanations": {"列表": "正确：“列表”指按顺序排成行的清单或表格，屏幕上可以显示。", "味道": "语义：味道是尝出来的感觉，看不见，不能拿来在屏幕上给人看。", "脾气": "语义：脾气是性情，不是可以显示在屏幕上的内容，句意说不通。", "脚步": "语义：脚步是走路的动作，不能显示在屏幕上让人看。"}, "sentence_index": 0, "correct_answer": "列表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭店的列表很厚，大家都在看。", "explanation": "这里应该用〈菜单〉。饭店供客人点菜的单子叫菜单；列表指按行排列的清单，不用来称呼饭店的菜单。"}, {"text": "他把列表存进了银行。", "explanation": "这里应该用〈钱〉。能存进银行的是钱，列表只是一行一行的清单，不能存入银行。"}, {"text": "这本书的列表在最前面。", "explanation": "这里应该用〈目录〉。书前面按页码列出章节的部分叫目录，列表不用来指书的前面部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "列表", "is_correct": true, "explanation": "正确：“列表”是按顺序排的名单，可以在里面找名字。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：名字不会写在冰箱里，冰箱里找不到这样的名单。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，里面没有可以找的名字。"}, {"text": "脸庞", "is_correct": false, "explanation": "语义：脸庞指人的脸，里面没有名字可找，句意说不通。"}], "explanations": {"列表": "正确：“列表”是按顺序排的名单，可以在里面找名字。", "冰箱": "语义：名字不会写在冰箱里，冰箱里找不到这样的名单。", "咖啡": "语义：咖啡是饮料，里面没有可以找的名字。", "脸庞": "语义：脸庞指人的脸，里面没有名字可找，句意说不通。"}, "sentence_index": 6, "correct_answer": "列表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "列表带我们参观景点。", "explanation": "这里应该用〈导游〉。能带人参观景点的是导游，列表只是清单，不能带路。"}, {"text": "下雨了，我撑起列表。", "explanation": "这里应该用〈雨伞〉。能撑开挡雨的是雨伞，列表不能撑起来。"}, {"text": "他对着列表整理头发。", "explanation": "这里应该用〈镜子〉。能照出人影、用来整理头发的是镜子，列表不能照出人影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在手机上找到了一首歌曲列表。", "corrected_sentence": "我在手机上找到了一个歌曲列表。", "error_description": "量词错误：“歌曲列表”的中心词是“列表”，应说“一个”；“首”用于歌曲本身，不用于列表。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在网站上看到了一本新闻列表。", "corrected_sentence": "我在网站上看到了一个新闻列表。", "error_description": "量词错误：“列表”不是书，不能说“一本”，应说“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
