INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能装很多东西的大车。", "primary_collocate": null, "pronunciation": "kǎ chē", "ipa": "kʰa˨˩˦ tʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "一辆卡车停在路边。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车上装着很多水果。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆卡车太大了，进不去。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开卡车已经十年了。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把箱子搬上了卡车。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的卡车走得很慢。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车里坐着三个工人。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在路上看见过一辆红色的卡车。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆卡车能装五吨东西。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车把家具送到了新家。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "大卡车", "label": "复合"}, {"form": "卡车司机", "label": "复合"}], "register": "中性", "sense_fingerprint": "能装很多东西的大车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96509, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卡车", "is_correct": true, "explanation": "卡车：能装很多东西的大车，可以停在路边。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：量词“辆”只用于车辆，不能说“一辆书包”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是车辆，不能停在路边。"}, {"text": "玫瑰", "is_correct": false, "explanation": "语义：玫瑰是花，不能停放在路边。"}], "explanations": {"卡车": "卡车：能装很多东西的大车，可以停在路边。", "书包": "搭配：量词“辆”只用于车辆，不能说“一辆书包”。", "花园": "语义：花园不是车辆，不能停在路边。", "玫瑰": "语义：玫瑰是花，不能停放在路边。"}, "sentence_index": 0, "correct_answer": "卡车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司新买了一条卡车。", "explanation": "这里应该用〈辆〉。〈条〉用于细长的东西，卡车属于车辆，要用〈辆〉。"}, {"text": "工厂门口停着一只卡车。", "explanation": "这里应该用〈辆〉。〈只〉多用于动物或成对的东西，卡车要用〈辆〉。"}, {"text": "仓库里放着一本卡车。", "explanation": "这里应该用〈辆〉。〈本〉用于书籍，卡车要用〈辆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卡车", "is_correct": true, "explanation": "卡车：车厢里能坐人的载货大车，与“里”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里坐不下人，不能说“冰箱里坐着三个工人”。"}, {"text": "摩托车", "is_correct": false, "explanation": "搭配：摩托车是坐在上面的，不用“里”，应说“摩托车上”。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶里不能容纳坐着的人。"}], "explanations": {"卡车": "卡车：车厢里能坐人的载货大车，与“里”相合。", "冰箱": "语义：冰箱里坐不下人，不能说“冰箱里坐着三个工人”。", "摩托车": "搭配：摩托车是坐在上面的，不用“里”，应说“摩托车上”。", "花瓶": "语义：花瓶里不能容纳坐着的人。"}, "sentence_index": 6, "correct_answer": "卡车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路边停着一座卡车。", "explanation": "这里应该用〈辆〉。〈座〉用于山、楼房、桥等大型固定的东西，卡车要用〈辆〉。"}, {"text": "草地上停着一朵卡车。", "explanation": "这里应该用〈辆〉。〈朵〉用于花、云等，卡车要用〈辆〉。"}, {"text": "车间里摆着一张卡车。", "explanation": "这里应该用〈辆〉。〈张〉用于平面的东西，卡车要用〈辆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "物流公司今天派出了一个卡车。", "corrected_sentence": "物流公司今天派出了一辆卡车。", "error_description": "量词错误：“一个卡车”应为“一辆卡车”。卡车是车辆，应用量词“辆”，“个”不能替代。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天修好了那辆能装很多东西卡车。", "corrected_sentence": "他昨天修好了那辆能装很多东西的卡车。", "error_description": "结构助词错误：“能装很多东西卡车”应为“能装很多东西的卡车”。“能装很多东西”是动词短语，修饰名词时要用“的”连接，不能直接接在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
