INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于载运货物的大型汽车。", "primary_collocate": null, "pronunciation": "kǎ chē", "ipa": "kʰa˨˩˦ tʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "工厂每天用卡车运货。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不让卡车通过。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物都装在卡车上了。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆卡车是公司买的。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里有很多卡车经过这里。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车拉着大石头慢慢走。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天开卡车去送货。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种卡车可以运很重的东西。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有一辆卡车坏了。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐卡车去了山里。", "target_word": "卡车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "大卡车", "label": "复合"}, {"form": "卡车司机", "label": "复合"}], "register": "中性", "sense_fingerprint": "载运货物的大型汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卡车", "is_correct": true, "explanation": "卡车：能运货的大车，与“用…运货”相合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不能用来运货。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能用来运货。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛不能用来运货。"}], "explanations": {"卡车": "卡车：能运货的大车，与“用…运货”相合。", "钢琴": "语义：钢琴不能用来运货。", "雨伞": "语义：雨伞不能用来运货。", "蜡烛": "语义：蜡烛不能用来运货。"}, "sentence_index": 0, "correct_answer": "卡车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂新买了一条卡车。", "explanation": "这里应该用〈辆〉。〈条〉用于细长的东西，卡车属于车辆，要用〈辆〉。"}, {"text": "院子里停着一只卡车。", "explanation": "这里应该用〈辆〉。〈只〉多用于动物或成对的东西，卡车要用〈辆〉。"}, {"text": "我们公司买了一本卡车。", "explanation": "这里应该用〈辆〉。〈本〉用于书籍，卡车要用〈辆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卡车", "is_correct": true, "explanation": "卡车：能开的载货大车，与“开”相合。"}, {"text": "小提琴", "is_correct": false, "explanation": "搭配：“开”不搭配乐器，拉小提琴应说“拉”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能开去送货。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能开去送货。"}], "explanations": {"卡车": "卡车：能开的载货大车，与“开”相合。", "小提琴": "搭配：“开”不搭配乐器，拉小提琴应说“拉”。", "书包": "语义：书包不能开去送货。", "花园": "语义：花园不能开去送货。"}, "sentence_index": 6, "correct_answer": "卡车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山脚下停着一座卡车。", "explanation": "这里应该用〈辆〉。〈座〉用于山、楼房、桥等大型固定的东西，卡车要用〈辆〉。"}, {"text": "树下停着一朵卡车。", "explanation": "这里应该用〈辆〉。〈朵〉用于花、云等，卡车要用〈辆〉。"}, {"text": "车间里摆着一张卡车。", "explanation": "这里应该用〈辆〉。〈张〉用于平面的东西，卡车要用〈辆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上有三个卡车开出了仓库。", "corrected_sentence": "早上有三辆卡车开出了仓库。", "error_description": "量词错误：“三个卡车”应为“三辆卡车”，卡车用量词“辆”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机每天早上骑卡车去城里送货。", "corrected_sentence": "司机每天早上开卡车去城里送货。", "error_description": "搭配错误：“骑”用于自行车、摩托车、马等，卡车要说“开卡车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
