INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96511, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开的时候，对别人说再见。", "primary_collocate": null, "pronunciation": "gào bié", "ipa": "kau˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "走以前，他向大家告别。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去机场和朋友告别。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着向妈妈告别。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在门口告别了。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有告别就走了。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子向老师告别后回家了。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要走的时候，我先和房东告别。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们笑着告别，说明年再见。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你走之前，应该跟同学告别。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经告别了朋友，准备上车。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "告别了", "label": "体标"}, {"form": "告别过", "label": "体标"}, {"form": "告别仪式", "label": "复合"}], "register": "中性", "sense_fingerprint": "离开时向人说再见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "告别", "is_correct": true, "explanation": "告别：离开时向大家道别，与“走以前”“向大家”相合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是迎接来人，与“走以前”的离去语境矛盾。"}, {"text": "相逢", "is_correct": false, "explanation": "语义：“相逢”指遇见，与“走”的语境相反。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”不带“向+人”的对象，不能说“向大家出发”。"}], "explanations": {"告别": "告别：离开时向大家道别，与“走以前”“向大家”相合。", "欢迎": "语义：“欢迎”是迎接来人，与“走以前”的离去语境矛盾。", "相逢": "语义：“相逢”指遇见，与“走”的语境相反。", "出发": "配价：“出发”不带“向+人”的对象，不能说“向大家出发”。"}, "sentence_index": 0, "correct_answer": "告别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "开学那天，老师热情地告别了我们。", "explanation": "这里应该用〈欢迎〉。告别是离开时道别，开学那天老师应该欢迎我们，不能说告别。"}, {"text": "朋友刚下飞机，我在出口告别他。", "explanation": "这里应该用〈迎接〉。告别用于分开时，朋友刚到应说迎接他。"}, {"text": "我们把客人请进屋，热情地告别了他们。", "explanation": "这里应该用〈招待〉。告别是离开时道别，客人刚进屋应说招待，不能说告别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "告别", "is_correct": true, "explanation": "告别：要走时与房东道别，与“要走的时候”相合。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与“要走的时候”的语境不符，不能说“先和房东结婚”。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”指初识，与“要走的时候”矛盾。"}, {"text": "辞职", "is_correct": false, "explanation": "配价：“辞职”不带“和+人”的对象，应说“向…辞职”。"}], "explanations": {"告别": "告别：要走时与房东道别，与“要走的时候”相合。", "结婚": "语义：“结婚”与“要走的时候”的语境不符，不能说“先和房东结婚”。", "认识": "语义：“认识”指初识，与“要走的时候”矛盾。", "辞职": "配价：“辞职”不带“和+人”的对象，应说“向…辞职”。"}, "sentence_index": 6, "correct_answer": "告别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上进教室，我先向老师告别。", "explanation": "这里应该用〈问好〉。告别用于离开时道别，早上进教室应向老师问好。"}, {"text": "新老师刚上任，大家就向他告别。", "explanation": "这里应该用〈欢迎〉。告别用于分开时，新老师刚来应表示欢迎。"}, {"text": "新同学刚走进教室，就向大家告别。", "explanation": "这里应该用〈打招呼〉。告别用于离开时道别，新同学刚进教室应向大家打招呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "离开前，我向同事们告别了了。", "corrected_sentence": "离开前，我向同事们告别了。", "error_description": "“了”重复：“告别了”的“了”只需一个，句末已有“了”表示完成，应说“告别了”，不能说“告别了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先大家告别，然后回家。", "corrected_sentence": "我先向大家告别，然后回家。", "error_description": "语序错误：“大家”是“告别”的宾语，不能直接放在“先”与“告别”之间；应说“先向大家告别”或“先告别大家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
