INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96512, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "辞别；与人分手或离开某地。", "primary_collocate": null, "pronunciation": "gào bié", "ipa": "kau˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "他今天要告别家乡，去北京工作。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八岁那年，她告别了小山村。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们快要告别这座城市了。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他告别了老家，一个人去了南方。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她告别过很多地方，但最爱这里。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，大家就要告别学校了。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他含着泪告别了生活多年的小镇。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我就告别北京，回上海。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "告别家乡的那天，天下着雨。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们告别草原，坐火车回城。", "target_word": "告别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "告别了", "label": "体标"}, {"form": "告别过", "label": "体标"}, {"form": "告别仪式", "label": "复合"}], "register": "中性", "sense_fingerprint": "辞别，离开某人或某地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1554b05d-d9ab-4ce5-9570-4174633aa403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "告别", "is_correct": true, "explanation": "告别：与家乡分别，与“去北京工作”相呼应。"}, {"text": "回到", "is_correct": false, "explanation": "语义：“回到家乡”与“去北京工作”方向相反，句意矛盾。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”不带地点宾语，不能说“出发家乡”。"}, {"text": "投靠", "is_correct": false, "explanation": "语义：“投靠”的对象须是人，不能投靠“家乡”。"}], "explanations": {"告别": "告别：与家乡分别，与“去北京工作”相呼应。", "回到": "语义：“回到家乡”与“去北京工作”方向相反，句意矛盾。", "出发": "配价：“出发”不带地点宾语，不能说“出发家乡”。", "投靠": "语义：“投靠”的对象须是人，不能投靠“家乡”。"}, "sentence_index": 0, "correct_answer": "告别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一下火车，大家就齐声告别他。", "explanation": "这里应该用〈迎接〉。告别指离开某人或某地时道别，他刚下火车应说迎接。"}, {"text": "新生刚来学校，老师就向他们告别。", "explanation": "这里应该用〈欢迎〉。告别是离开时道别，新生刚来应表示欢迎。"}, {"text": "他刚到北京，就高兴地告别了北京。", "explanation": "这里应该用〈来到〉。告别表示离开某地，他刚到北京应说来到北京。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "告别", "is_correct": true, "explanation": "告别：含泪离开生活多年的小镇，与“含着泪”“生活多年”相合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示喜迎，与“含着泪”的伤感语境矛盾。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”指迎来，与“含着泪”和“生活多年”的离别语境不合。"}, {"text": "相遇", "is_correct": false, "explanation": "配价：“相遇”后不能直接跟地点宾语，不能说“相遇小镇”。"}], "explanations": {"告别": "告别：含泪离开生活多年的小镇，与“含着泪”“生活多年”相合。", "欢迎": "语义：“欢迎”表示喜迎，与“含着泪”的伤感语境矛盾。", "迎接": "语义：“迎接”指迎来，与“含着泪”和“生活多年”的离别语境不合。", "相遇": "配价：“相遇”后不能直接跟地点宾语，不能说“相遇小镇”。"}, "sentence_index": 6, "correct_answer": "告别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "进门时，我先向主人告别。", "explanation": "这里应该用〈问候〉。告别是离开时道别，进门时应向主人问候。"}, {"text": "游客刚走进博物馆，就告别了博物馆。", "explanation": "这里应该用〈参观〉。告别表示离开某地，游客刚进去应说参观博物馆。"}, {"text": "代表们刚到大厅，市长就热情地告别了他们。", "explanation": "这里应该用〈接见〉。告别是离开时道别，代表刚到大厅应说接见，不能说告别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今年终于告别了了老家。", "corrected_sentence": "他今年终于告别了老家。", "error_description": "“了”重复：动词后的“了”只需一个，应说“终于告别了老家”，不能说“告别了了老家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先家人告别，然后出发。", "corrected_sentence": "他先向家人告别，然后出发。", "error_description": "语序错误：“家人”是“告别”的宾语，不能直接放在“先”与“告别”之间；应说“先向家人告别”或“先告别家人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1307a65-596e-45b0-81ee-73a77a3c735f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
