INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96513, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "饭店里买了吃的，带回家去吃。", "primary_collocate": null, "pronunciation": "wài dài", "ipa": "wai˥˩ tai˥˩", "syllable_count": 2, "sentences": [{"text": "我要一份炒饭，外带。", "target_word": "外带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请问是在这儿吃，还是外带？", "target_word": "外带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的面可以外带吗？", "target_word": "外带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们太忙了，只好外带两份饭回家。", "target_word": "外带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外带的话，我给你打包好。", "target_word": "外带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天下班都外带一份饺子。", "target_word": "外带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天人太多，我们外带吧。", "target_word": "外带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想外带两个菜，回家和家人一起吃。", "target_word": "外带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外带要多等十分钟。", "target_word": "外带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天我外带了一份牛肉面回家吃。", "target_word": "外带", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "外带了", "label": "体标"}, {"form": "外带过", "label": "体标"}, {"form": "外帶", "label": "繁体"}], "register": "口语", "sense_fingerprint": "在饭店买了吃的，带回家吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外带", "is_correct": true, "explanation": "正确：“外带”指在店里买了吃的带走，与“我要一份炒饭”相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，与“我要一份炒饭”的意愿相矛盾。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒”指把液体倒出，与“要一份炒饭”的意思不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：炒饭已经炒好，不能说“煮”，这个动作与炒饭搭配不当。"}], "explanations": {"外带": "正确：“外带”指在店里买了吃的带走，与“我要一份炒饭”相符。", "扔": "语义：“扔”是丢掉，与“我要一份炒饭”的意愿相矛盾。", "倒": "语义：“倒”指把液体倒出，与“要一份炒饭”的意思不符。", "煮": "搭配：炒饭已经炒好，不能说“煮”，这个动作与炒饭搭配不当。"}, "sentence_index": 0, "correct_answer": "外带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天外带了小王一顿饭。", "explanation": "这里应该用〈请〉。外带指买了吃的带出店外，不能用来表示请别人吃饭。"}, {"text": "饭店负责外带上门。", "explanation": "这里应该用〈送〉。外带是顾客自己把买的饭菜带走，不是店家送上门。"}, {"text": "周末我想外带女儿去公园。", "explanation": "这里应该用〈陪〉。外带只指把买来的饮食带出店外，不指带人出门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外带", "is_correct": true, "explanation": "正确：“外带”指买了吃的带走，符合“人太多，我们外带吧”的语境。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”是争执，与“人太多”的提议语境不符，不能作为这里的提议。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是测验学识，与“人太多”没有合理联系，不能作为提议。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”与“人太多”之间不构成合理的提议，这样说不地道。"}], "explanations": {"外带": "正确：“外带”指买了吃的带走，符合“人太多，我们外带吧”的语境。", "吵架": "语义：“吵架”是争执，与“人太多”的提议语境不符，不能作为这里的提议。", "考试": "语义：“考试”是测验学识，与“人太多”没有合理联系，不能作为提议。", "睡觉": "搭配：“睡觉”与“人太多”之间不构成合理的提议，这样说不地道。"}, "sentence_index": 6, "correct_answer": "外带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在店里外带，吃了一份牛肉面。", "explanation": "这里应该用〈堂食〉。外带是打包带出店外，不能说在店里吃。"}, {"text": "我在网上外带了一份饺子，半小时后就到家了。", "explanation": "这里应该用〈外卖〉。外带是顾客自己到店取走，不是由店家送到家里。"}, {"text": "我把这份礼物外带给远方的朋友。", "explanation": "这里应该用〈寄〉。外带只指把买来的饮食带出店外，不指把东西寄给远方的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天外带了一份炒饭回家吃。", "corrected_sentence": "我明天外带一份炒饭回家吃。", "error_description": "错误在“了”：“明天”是将来的事，“外带”后不能用表示完成的“了”；应说“明天外带一份炒饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨了，我们外带过吧。", "corrected_sentence": "下雨了，我们外带吧。", "error_description": "错误在“过”：“过”表示曾经有过的经历，不能用在“吧”表示的提议里；应去掉“过”，说“我们外带吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
