INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学校的学生数很大于那个学校的学生数。", "corrected_sentence": "这个学校的学生数大于那个学校的学生数。", "error_description": "程度副词“很”不能修饰比较动词“大于”，“大于”本身已表示比较。应去掉“很”，说“这个学校的学生数大于那个学校的学生数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
