INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96517, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "特别，比别的更。", "primary_collocate": null, "pronunciation": "yóu", "ipa": "joʊ˧˥", "syllable_count": 1, "sentences": [{"text": "他爱运动，尤爱游泳。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里夏天很热，七月尤热。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢水果，尤喜欢苹果。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的秋天很美，尤以十月为最。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会很多乐器，尤擅钢琴。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都很用功，小王尤用功。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对历史有兴趣，尤对唐朝感兴趣。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天很冷，北方的冬天尤冷。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜都好吃，鱼尤好吃。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爱听音乐，尤爱听老歌。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尤其", "label": "复合"}, {"form": "尤为", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，特别，比别的更", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96517, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尤", "is_correct": true, "explanation": "尤（yóu）是本条目的目标词，副词，表示特别、比别的更。"}, {"text": "有", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有、存在。"}, {"text": "又", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是再次、又。"}, {"text": "优", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是优秀、优良。"}, {"text": "幼", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是年幼。"}], "explanations": {"尤": "尤（yóu）是本条目的目标词，副词，表示特别、比别的更。", "有": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有、存在。", "又": "yòu（第四声）与 yóu（第二声）声调不同，意思是再次、又。", "优": "yōu（第一声）与 yóu（第二声）声调不同，意思是优秀、优良。", "幼": "yòu（第四声）与 yóu（第二声）声调不同，意思是年幼。"}, "sentence_index": null, "correct_answer": "尤"}, "level_3": {"options": [{"text": "却", "is_correct": false, "explanation": "语义：却表示转折，前后应相反，而“爱运动”与“爱游泳”并不对立。"}, {"text": "尤", "is_correct": true, "explanation": "尤：副词，表示特别、格外。此处突出他对游泳的喜爱比对运动更甚。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：已经表示时间上已发生或完成，不与“爱”这类表示长期喜好的动词搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示不常发生，与“爱”这种习惯性的喜好相矛盾。"}], "explanations": {"却": "语义：却表示转折，前后应相反，而“爱运动”与“爱游泳”并不对立。", "尤": "尤：副词，表示特别、格外。此处突出他对游泳的喜爱比对运动更甚。", "已经": "搭配：已经表示时间上已发生或完成，不与“爱”这类表示长期喜好的动词搭配。", "偶尔": "语义：偶尔表示不常发生，与“爱”这种习惯性的喜好相矛盾。"}, "sentence_index": 0, "correct_answer": "尤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都去，他尤去。", "explanation": "这里应该用〈也〉。尤表示程度上格外突出，不表示同类人或事的并列，并列要用〈也〉。"}, {"text": "请你尤说一遍。", "explanation": "这里应该用〈再〉。尤表示程度，不表示再次进行某个动作。"}, {"text": "他们尤来了。", "explanation": "这里应该用〈都〉。尤表示程度上的突出，不表示全部或全体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
