INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96518, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示更加、特别。", "primary_collocate": null, "pronunciation": "yóu", "ipa": "joʊ˧˥", "syllable_count": 1, "sentences": [{"text": "他喜欢动物，尤喜欢小狗。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天花多，四月尤多。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的面条很有名，牛肉面尤有名。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每门课都好，数学尤好。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕黑，一个人在家时尤怕。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市交通不方便，下雨天尤不方便。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都爱玩，男孩尤爱踢球。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌都好听，这一首尤好听。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写字好看，写大字尤好看。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜晚很安静，冬夜尤安静。", "target_word": "尤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尤其", "label": "复合"}, {"form": "尤为", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，表示更加、特别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
