INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很爱吃水果，尤是爱吃草莓。", "corrected_sentence": "他很爱吃水果，尤爱吃草莓。", "error_description": "错误形式：“尤”后多出了“是”。正确形式：说“尤爱吃草莓”。原因：“尤”直接修饰后面的动词，中间不能插入“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们很爱玩，尤很爱玩球。", "corrected_sentence": "孩子们很爱玩，尤爱玩球。", "error_description": "错误形式：“尤”后又加了程度副词“很”。正确形式：去掉“很”，说“尤爱玩球”。原因：“尤”本身已表示程度突出，后面不再接“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
