INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96519, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做工的和做买卖的事。", "primary_collocate": null, "pronunciation": "gōng shāng", "ipa": "kʊŋ˥ ʂaŋ˥", "syllable_count": 2, "sentences": [{"text": "古代重农抑商，工商的人地位不高。", "target_word": "工商", "complexity_tier": "T3", "furigana": "gōngshāng", "sentence_source": "generated"}, {"text": "旧时，许多农家子弟靠工商谋生。", "target_word": "工商", "complexity_tier": "T3", "furigana": "gōngshāng", "sentence_source": "generated"}, {"text": "旧时这个小镇的人大多以工商为业。", "target_word": "工商", "complexity_tier": "T3", "furigana": "gōngshāng", "sentence_source": "generated"}, {"text": "祖上靠工商起家，后来才买了地。", "target_word": "工商", "complexity_tier": "T3", "furigana": "gōngshāng", "sentence_source": "generated"}, {"text": "旧时城里不少人家以工商为生。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八岁那年，他离开农村，进城投身工商。", "target_word": "工商", "complexity_tier": "T3", "furigana": "gōngshāng", "sentence_source": "generated"}, {"text": "有人种地，有人做工商，日子都不错。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，工商的人要吃苦，日子不容易。", "target_word": "工商", "complexity_tier": "T3", "furigana": "gōngshāng", "sentence_source": "generated"}, {"text": "她没有去教书，而是选择了工商这条路。", "target_word": "工商", "complexity_tier": "T3", "furigana": "gōngshāng", "sentence_source": "generated"}, {"text": "在这个港口城市，工商的人最多，人人都忙着挣钱。", "target_word": "工商", "complexity_tier": "T3", "furigana": "gōngshāng", "sentence_source": "generated"}], "morphological_forms": [{"form": "工商界", "label": "复合词"}, {"form": "工商业", "label": "复合词"}], "register": "书面", "sense_fingerprint": "做工与做买卖这类谋生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工商", "is_correct": true, "explanation": "正确：“工商”指做工和做买卖的事，句中说的是这类人地位不高。"}, {"text": "农业", "is_correct": false, "explanation": "语义：“重农”说明农业受重视，“农业的人地位不高”与语境矛盾。"}, {"text": "官员", "is_correct": false, "explanation": "语义：官员的地位通常较高，与句中“地位不高”的语境不符。"}, {"text": "科举", "is_correct": false, "explanation": "搭配：“科举”是选拔官员的制度，不能用来指一类人，与“的人”搭配不当。"}], "explanations": {"工商": "正确：“工商”指做工和做买卖的事，句中说的是这类人地位不高。", "农业": "语义：“重农”说明农业受重视，“农业的人地位不高”与语境矛盾。", "官员": "语义：官员的地位通常较高，与句中“地位不高”的语境不符。", "科举": "搭配：“科举”是选拔官员的制度，不能用来指一类人，与“的人”搭配不当。"}, "sentence_index": 0, "correct_answer": "工商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的工商很便宜，大家都来买。", "explanation": "这里应该用〈商品〉。“工商”指做工与做买卖的活动，不指所卖的东西；说东西便宜要用〈商品〉。"}, {"text": "我哥哥是工商，每天在车间里干活，手上全是老茧。", "explanation": "这里应该用〈工人〉。“工商”指做工与做买卖的事，不直接指人（“工商的人”是指从事这类事的人）；在车间干活的人要说〈工人〉。"}, {"text": "这次工商很难，我们班一半的人都没及格。", "explanation": "这里应该用〈考试〉。“工商”指做工与做买卖的事，不指考试；说考试难要用〈考试〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工商", "is_correct": true, "explanation": "正确：“做工商”与前句“种地”并列，指做工与做买卖的事。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“做天空”不成立，天空不能被“做”。"}, {"text": "星星", "is_correct": false, "explanation": "语义：“做星星”没有意义，与“种地”的并列关系不符。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：“做”不与“西瓜”搭配，西瓜是种出来的，不是“做”出来的。"}], "explanations": {"工商": "正确：“做工商”与前句“种地”并列，指做工与做买卖的事。", "天空": "语义：“做天空”不成立，天空不能被“做”。", "星星": "语义：“做星星”没有意义，与“种地”的并列关系不符。", "西瓜": "搭配：“做”不与“西瓜”搭配，西瓜是种出来的，不是“做”出来的。"}, "sentence_index": 6, "correct_answer": "工商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那座工商每年生产十万辆汽车。", "explanation": "这里应该用〈工厂〉。“工商”指做工与做买卖的事，不指具体的生产单位。"}, {"text": "他是一名工商，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。“工商”不直接指人（“工商的人”是指从事这类事的人）；给病人看病的人要说〈医生〉。"}, {"text": "街角那家工商的菜很好吃，客人很多。", "explanation": "这里应该用〈饭店〉。“工商”不指餐饮场所，做菜卖饭的地方要说〈饭店〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的父亲一辈子工商，攒下了不少钱。", "corrected_sentence": "他的父亲一辈子做工商，攒下了不少钱。", "error_description": "错误形式：“一辈子工商”。“工商”作宾语前需要动词“做”带出，应为“一辈子做工商”，缺少动词“做”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个做工商人很有钱。", "corrected_sentence": "那个做工商的人很有钱。", "error_description": "错误形式：“做工商人”。“做工商”修饰名词“人”时需要结构助词“的”，应为“做工商的人”，漏掉“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
