INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工业和商业的合称。", "primary_collocate": null, "pronunciation": "gōng shāng", "ipa": "kʊŋ˥ ʂaŋ˥", "syllable_count": 2, "sentences": [{"text": "这个城市的工商很发达，人口也不断增加。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工商部门工作了十年。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府出台新政策，支持工商发展。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工商两界的代表一起开了会。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区农业很弱，但工商发展很快。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工商部门提醒市民买东西时要发票。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是工商方面的专家，常常上电视讲课。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革对工商都有好处。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县的工商一年比一年繁荣，居民收入也随之提高。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，这里的工商越来越好，吸引了很多外地人。", "target_word": "工商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工商界", "label": "复合词"}, {"form": "工商业", "label": "复合词"}, {"form": "工商局", "label": "复合词"}], "register": "书面", "sense_fingerprint": "工业和商业的合称，常作定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b2e9c7-fc7a-4df2-bc48-636e68219981') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工商", "is_correct": true, "explanation": "正确：“工商”是工业和商业的合称，“很发达”可以用来形容它。"}, {"text": "文物", "is_correct": false, "explanation": "语义：文物不能“发达”，“很发达”不能用来形容文物。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不能“发达”，句意与“人口也不断增加”的语境也不符。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“发达”不搭配“历史”，不能说“历史很发达”。"}], "explanations": {"工商": "正确：“工商”是工业和商业的合称，“很发达”可以用来形容它。", "文物": "语义：文物不能“发达”，“很发达”不能用来形容文物。", "动物": "语义：动物不能“发达”，句意与“人口也不断增加”的语境也不符。", "历史": "搭配：“发达”不搭配“历史”，不能说“历史很发达”。"}, "sentence_index": 0, "correct_answer": "工商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工商的饺子很好吃，每天都排长队。", "explanation": "这里应该用〈饭馆〉。“工商”是工业和商业的合称，指行业而非具体店铺；卖饺子的地方要说〈饭馆〉。"}, {"text": "他是工商，每天在工厂里管生产。", "explanation": "这里应该用〈厂长〉。“工商”是抽象的统称，不指人；管理工厂的人要说〈厂长〉。"}, {"text": "他的工商很高，大家都很羡慕。", "explanation": "这里应该用〈工资〉。“工商”指工业和商业，不指收入；说收入高要用〈工资〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工商", "is_correct": true, "explanation": "正确：“工商方面”指工业和商业的领域，“专家”可以用于这一领域。"}, {"text": "周末", "is_correct": false, "explanation": "语义：“周末”是时间，不是专业领域，“周末方面的专家”不成立。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：“星期三”是时间，不是专业领域，“星期三方面的专家”不成立。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：“眼泪”不是知识领域，“眼泪方面的专家”句意不通。"}], "explanations": {"工商": "正确：“工商方面”指工业和商业的领域，“专家”可以用于这一领域。", "周末": "语义：“周末”是时间，不是专业领域，“周末方面的专家”不成立。", "星期三": "语义：“星期三”是时间，不是专业领域，“星期三方面的专家”不成立。", "眼泪": "语义：“眼泪”不是知识领域，“眼泪方面的专家”句意不通。"}, "sentence_index": 6, "correct_answer": "工商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工商每天在飞机上为乘客服务，很热情。", "explanation": "这里应该用〈空乘〉。“工商”是工业和商业的合称，不指人；在飞机上为乘客服务的人要说〈空乘〉。"}, {"text": "这家工商去年治好了很多病人。", "explanation": "这里应该用〈医院〉。“工商”不指医疗机构，治病是〈医院〉的工作。"}, {"text": "这个工商每天有很多航班起降。", "explanation": "这里应该用〈机场〉。“工商”不指交通场所，航班起降与“工商”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在工商们部门工作。", "corrected_sentence": "她在工商部门工作。", "error_description": "词缀错误：“工商”是抽象的统称，不能加复数词尾“们”，应说“工商部门”，不说“工商们部门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市有很发达工商，吸引了很多人来。", "corrected_sentence": "这个城市有很发达的工商，吸引了很多人来。", "error_description": "错误形式：“很发达工商”。形容词“发达”受“很”修饰后修饰名词“工商”时，中间需要结构助词“的”，应为“很发达的工商”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4016556-9ab5-4236-927d-eeb20ae2531d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
