INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96521, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿东西去，给别人。", "primary_collocate": null, "pronunciation": "dài gěi", "ipa": "tai̯⁵¹ kei̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "爸爸出差回来，带给我一个小礼物。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这本书带给你。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从北京带给朋友一盒茶叶。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我把你的伞带给你。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把自己做的面包带给邻居。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去看病人时，我带给他一些水果。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李从家里带给同事一些苹果。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这封信带给王老师。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟去上海，带给姐姐一件新衣服。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会把咖啡带给你，你在门口等我。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带给了", "label": "体标（了）"}, {"form": "带给过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把具体的东西拿去送给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带给", "is_correct": true, "explanation": "正确。“带给”表示拿着东西去交给人，与“出差回来”的情境相合。"}, {"text": "带走", "is_correct": false, "explanation": "语义：“带走”指把东西拿离，与后面的“给我”方向相反。"}, {"text": "寄给", "is_correct": false, "explanation": "语义：“寄给”指邮寄，与“出差回来”当面送礼的情境不合。"}, {"text": "换给", "is_correct": false, "explanation": "搭配：“换给”要先有被交换的东西，句中没有，不能只说“换给我一个小礼物”。"}], "explanations": {"带给": "正确。“带给”表示拿着东西去交给人，与“出差回来”的情境相合。", "带走": "语义：“带走”指把东西拿离，与后面的“给我”方向相反。", "寄给": "语义：“寄给”指邮寄，与“出差回来”当面送礼的情境不合。", "换给": "搭配：“换给”要先有被交换的东西，句中没有，不能只说“换给我一个小礼物”。"}, "sentence_index": 0, "correct_answer": "带给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这套旧房子带给儿子。", "explanation": "这里应该用〈留给〉。带给指拿着东西去交给人，房子这样的大件不能拿着送去；把东西留给后人要用留给。"}, {"text": "我把工资带给银行。", "explanation": "这里应该用〈存进〉。带给的对象必须是人，银行是地点；把钱存入账户要用存进。"}, {"text": "我把晚饭带给厨房。", "explanation": "这里应该用〈带到〉。带给的对象必须是人，厨房是地点；表示送到某处要用带到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带给", "is_correct": true, "explanation": "正确。“带给”表示拿去交给同事，与“从家里”的动作相合。"}, {"text": "偷走", "is_correct": false, "explanation": "语义：“偷走”指拿走别人的东西，与“给同事”的方向不合。"}, {"text": "收走", "is_correct": false, "explanation": "语义：“收走”指收回或没收，不能用来表示把苹果送给同事。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语要是食物，“吃掉同事”搭配不通。"}], "explanations": {"带给": "正确。“带给”表示拿去交给同事，与“从家里”的动作相合。", "偷走": "语义：“偷走”指拿走别人的东西，与“给同事”的方向不合。", "收走": "语义：“收走”指收回或没收，不能用来表示把苹果送给同事。", "吃掉": "搭配：“吃掉”的宾语要是食物，“吃掉同事”搭配不通。"}, "sentence_index": 6, "correct_answer": "带给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把座位带给老人。", "explanation": "这里应该用〈让给〉。座位不能拿着去送人；把位置腾出来给别人要用让给。"}, {"text": "我把快递带给你家附近的超市。", "explanation": "这里应该用〈送到〉。带给的对象必须是人，超市是地点；表示送去某处要用送到。"}, {"text": "我把包裹带给老家的村口。", "explanation": "这里应该用〈寄回〉。带给的对象必须是人，村口是地点；把东西寄回某地要用寄回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我带给你了一本书。", "corrected_sentence": "我带给了你一本书。", "error_description": "错误形式“带给你了一本书”，“了”放在了宾语“你”之后，不能跟在宾语后面。正确形式为“带给了你一本书”，“了”应紧跟复合动词“带给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你把这份材料了带给王老师。", "corrected_sentence": "请你把这份材料带给王老师。", "error_description": "错误形式“把这份材料了带给王老师”，“了”插在“材料”和“带给”之间，多余且位置错误，应删去。正确形式为“把这份材料带给王老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
