INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96522, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96522, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某物或某种感受传递给他人。", "primary_collocate": null, "pronunciation": "dài gěi", "ipa": "tai̯⁵¹ kei̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "孩子带给我们很多快乐。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好消息带给大家希望。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐带给她平静的心情。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行带给我很多难忘的回忆。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨天带给这座城市一些凉意。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容带给我们力量。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络带给人们很多方便。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雪带给司机不少麻烦。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事带给他很大的压力。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师总能带给学生信心。", "target_word": "带给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带给了", "label": "体标（了）"}, {"form": "带给过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "使别人得到某种感受、影响或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带给", "is_correct": true, "explanation": "正确。“带给”表示使人得到某种感受或影响，与“很多快乐”相合。"}, {"text": "带走", "is_correct": false, "explanation": "语义：“带走”表示拿离，与“我们很多快乐”的给予方向相反。"}, {"text": "花掉", "is_correct": false, "explanation": "搭配：“花掉”多用于钱或时间，不说“花掉快乐”。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”指拿回原先给出的东西，与孩子带来快乐的意思不合。"}], "explanations": {"带给": "正确。“带给”表示使人得到某种感受或影响，与“很多快乐”相合。", "带走": "语义：“带走”表示拿离，与“我们很多快乐”的给予方向相反。", "花掉": "搭配：“花掉”多用于钱或时间，不说“花掉快乐”。", "收回": "语义：“收回”指拿回原先给出的东西，与孩子带来快乐的意思不合。"}, "sentence_index": 0, "correct_answer": "带给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个好消息带给大家很高兴。", "explanation": "这里应该用〈让〉。带给后面要接名词性的东西（如“快乐”“希望”），“很高兴”是形容词短语，表示使人产生某种状态要用让。"}, {"text": "他把全部精力带给了游戏。", "explanation": "这里应该用〈投入〉。带给的对象一般是人，游戏不是接收者；把精力投入某事要用投入。"}, {"text": "我把时间带给工作。", "explanation": "这里应该用〈花在〉。带给的对象一般是人，工作不是接收者；把时间投入某事要用花在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带给", "is_correct": true, "explanation": "正确。“带给”表示使人得到影响，与“很多方便”相合。"}, {"text": "占用", "is_correct": false, "explanation": "搭配：“占用”搭配时间、空间，不能说“占用方便”。"}, {"text": "收走", "is_correct": false, "explanation": "语义：“收走”指拿走，与“给人们”的方向相反。"}, {"text": "耗费", "is_correct": false, "explanation": "搭配：“耗费”搭配时间、精力、资源，“耗费很多方便”不通。"}], "explanations": {"带给": "正确。“带给”表示使人得到影响，与“很多方便”相合。", "占用": "搭配：“占用”搭配时间、空间，不能说“占用方便”。", "收走": "语义：“收走”指拿走，与“给人们”的方向相反。", "耗费": "搭配：“耗费”搭配时间、精力、资源，“耗费很多方便”不通。"}, "sentence_index": 6, "correct_answer": "带给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "好老师总能带给学生很自信。", "explanation": "这里应该用〈让〉。带给后面要接名词性宾语（如“信心”），“很自信”是形容词短语，表示使人变得怎样要用让。"}, {"text": "好老师总能帮助学生带给信心。", "explanation": "这里应该用〈树立〉。带给表示传递给他人，学生自己获得并确立信心要用树立。"}, {"text": "好老师总能带给学生学习。", "explanation": "这里应该用〈激发〉。带给的宾语应是可以传递的某物或感受，“学习”是动作，不能被带给；激发学生学习要用〈激发〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子带给过了我们很多快乐的回忆。", "corrected_sentence": "孩子带给我们很多快乐的回忆。", "error_description": "错误：“带给”后同时加了“过”和“了”两个体标，汉语动词后不能叠加两个体标。删去“过了”，正确形式为“孩子带给我们很多快乐的回忆。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新网站带给人们了很多方便。", "corrected_sentence": "新网站带给人们很多方便。", "error_description": "错误形式“带给人们了很多方便”，多出的“了”插在宾语“人们”和“很多方便”之间，应删去。正确形式为“带给人们很多方便”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
