INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96524, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通常的规定、做法；一般惯例。", "primary_collocate": null, "pronunciation": "cháng guī", "ipa": "ʈʂʰɑŋ˧˥ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "按常规，学生九点要到学校。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样做不符合常规。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司有公司的常规。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从来不按常规做事。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新来的人要先学会这里的常规。", "target_word": "常规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打破常规需要很大的勇气。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师打破了上课的常规。", "target_word": "常规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "按常规，三天后才能收到信。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是医院的常规，大家都要遵守。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的想法完全不合常规。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "常规武器", "label": "复合"}, {"form": "常规检查", "label": "复合"}], "register": "中性", "sense_fingerprint": "通常的规定和惯例，如按常规、打破常规", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add11f56-6b71-44e4-ad75-5ff231dc05d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常规", "is_correct": true, "explanation": "正确：“按常规”指按照通常的规定或做法，符合这里的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与学生到校时间无关，“按颜色”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道与到校时间无关，“按味道”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性情，不是规定，不能决定学生几点到校。"}], "explanations": {"常规": "正确：“按常规”指按照通常的规定或做法，符合这里的语境。", "颜色": "语义：颜色与学生到校时间无关，“按颜色”说不通。", "味道": "语义：味道与到校时间无关，“按味道”说不通。", "脾气": "语义：脾气是性情，不是规定，不能决定学生几点到校。"}, "sentence_index": 0, "correct_answer": "常规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的常规很好吃。", "explanation": "这里应该用〈味道〉。能“好吃”的是菜的味道，常规指规定或做法，不说“很好吃”。"}, {"text": "这面墙的常规很鲜艳。", "explanation": "这里应该用〈颜色〉。能“鲜艳”的是颜色，常规指规定或做法，不说“很鲜艳”。"}, {"text": "这份报告的常规很高。", "explanation": "这里应该用〈标准〉。能“高”的是标准，常规指通常的做法，不说“常规很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常规", "is_correct": true, "explanation": "正确：“打破常规”指打破通常的规定或做法，与这里的语境相符。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不是规定或做法，无法被“打破”，句意说不通。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“打破”不搭配“座位”，不说“打破座位”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能被“打破”，与这里的语境不合。"}], "explanations": {"常规": "正确：“打破常规”指打破通常的规定或做法，与这里的语境相符。", "眼泪": "语义：眼泪不是规定或做法，无法被“打破”，句意说不通。", "座位": "搭配：“打破”不搭配“座位”，不说“打破座位”。", "名字": "语义：名字不能被“打破”，与这里的语境不合。"}, "sentence_index": 6, "correct_answer": "常规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的英语常规提高得很快。", "explanation": "这里应该用〈水平〉。“提高”用于水平、能力，“常规”是通常的做法，不能说“提高”。"}, {"text": "这台机器的常规很大。", "explanation": "这里应该用〈力量〉。能“大”的是力量，常规指规定或做法，不能用“很大”来形容。"}, {"text": "他把常规放进了冰箱。", "explanation": "这里应该用〈食物〉。能放进冰箱的是食物，常规指规定或做法，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司定了一把常规，所有人都要遵守。", "corrected_sentence": "公司定了一条常规，所有人都要遵守。", "error_description": "量词错误：“常规”属于规定类，应说“一条”；“把”用于有柄的器具，不能用来计量“常规”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他打开了公司的常规，大家都很吃惊。", "corrected_sentence": "他打破了公司的常规，大家都很吃惊。", "error_description": "搭配错误：“常规”常说“打破常规”，表示不按通常的做法；“打开”用于门、盒子等，不能和“常规”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
