INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "戴在头上的东西。", "primary_collocate": null, "pronunciation": "mào zi", "ipa": "maʊ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "他头上戴着一顶黑色的帽子。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门以后，请把帽子摘下来。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的帽子放在桌子上。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顶帽子是我朋友送的。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一顶很大的帽子。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把帽子戴反了。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣架上挂着爸爸的帽子。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，帽子飞走了。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的帽子掉在地上了。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一顶新帽子。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顶", "label": "量词"}, {"form": "草帽", "label": "复合"}, {"form": "帽檐", "label": "复合"}], "register": "中性", "sense_fingerprint": "戴在头上的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96525, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帽子", "is_correct": true, "explanation": "正确答案：mào zi，戴在头上的东西。"}, {"text": "耗子", "is_correct": false, "explanation": "耗子（hào zi）声母 h 与 m 不同，声调相同，意思是老鼠。"}, {"text": "套子", "is_correct": false, "explanation": "套子（tào zi）声母 t 与 m 不同，声调相同，意思是套在外面的罩子。"}, {"text": "泡子", "is_correct": false, "explanation": "泡子（pào zi）声母 p 与 m 不同，声调相同，意思是水洼或小湖，较少用。"}, {"text": "稻子", "is_correct": false, "explanation": "稻子（dào zi）声母 d 与 m 不同，声调相同，意思是稻谷。"}], "explanations": {"帽子": "正确答案：mào zi，戴在头上的东西。", "耗子": "耗子（hào zi）声母 h 与 m 不同，声调相同，意思是老鼠。", "套子": "套子（tào zi）声母 t 与 m 不同，声调相同，意思是套在外面的罩子。", "泡子": "泡子（pào zi）声母 p 与 m 不同，声调相同，意思是水洼或小湖，较少用。", "稻子": "稻子（dào zi）声母 d 与 m 不同，声调相同，意思是稻谷。"}, "sentence_index": null, "correct_answer": "帽子"}, "level_3": {"options": [{"text": "帽子", "is_correct": true, "explanation": "正确：量词“顶”搭配“帽子”，句子说的是戴在头上的帽子。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：量词“顶”不能配“手套”，应说“一副手套”。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜戴在脸上，不戴在头上，句子说不通。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾围在脖子上，不是戴在头上的东西，句子说不通。"}], "explanations": {"帽子": "正确：量词“顶”搭配“帽子”，句子说的是戴在头上的帽子。", "手套": "搭配：量词“顶”不能配“手套”，应说“一副手套”。", "眼镜": "语义：眼镜戴在脸上，不戴在头上，句子说不通。", "围巾": "语义：围巾围在脖子上，不是戴在头上的东西，句子说不通。"}, "sentence_index": 0, "correct_answer": "帽子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨了，他撑着一顶帽子出门。", "explanation": "这里应该用〈雨伞〉。下雨时撑的是雨伞，帽子是戴在头上的，不能“撑”。"}, {"text": "他鼻梁上架着一顶帽子。", "explanation": "这里应该用〈眼镜〉。鼻梁上架的是眼镜，帽子要戴在头上，不能架在鼻梁上。"}, {"text": "他背着一顶帽子上学。", "explanation": "这里应该用〈书包〉。上学背的是书包，帽子是戴在头上的，不能“背”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96525, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帽子", "is_correct": true, "explanation": "正确答案：mào zi，戴在头上的东西。"}, {"text": "豹子", "is_correct": false, "explanation": "豹子（bào zi）声母 b 与 m 不同，意思是豹这种动物。"}, {"text": "号子", "is_correct": false, "explanation": "号子（hào zi）声母 h 与 m 不同，声调相同，意思是劳动时喊的调子。"}, {"text": "罩子", "is_correct": false, "explanation": "罩子（zhào zi）声母 zh 与 m 不同，声调相同，意思是罩在物体外面的东西。"}], "explanations": {"帽子": "正确答案：mào zi，戴在头上的东西。", "豹子": "豹子（bào zi）声母 b 与 m 不同，意思是豹这种动物。", "号子": "号子（hào zi）声母 h 与 m 不同，声调相同，意思是劳动时喊的调子。", "罩子": "罩子（zhào zi）声母 zh 与 m 不同，声调相同，意思是罩在物体外面的东西。"}, "sentence_index": null, "correct_answer": "帽子"}, "level_3": {"options": [{"text": "帽子", "is_correct": true, "explanation": "正确：衣架上挂着的是爸爸的帽子，「挂」与「帽子」搭配，句子通顺。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：衣架上挂的是衣物，挂鞋子不合常理，句子说不通。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子不挂在衣架上，句子说不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“挂”不能用于书，书一般是放或摆，不说“挂着”。"}], "explanations": {"帽子": "正确：衣架上挂着的是爸爸的帽子，「挂」与「帽子」搭配，句子通顺。", "鞋子": "语义：衣架上挂的是衣物，挂鞋子不合常理，句子说不通。", "杯子": "语义：杯子不挂在衣架上，句子说不通。", "书": "搭配：“挂”不能用于书，书一般是放或摆，不说“挂着”。"}, "sentence_index": 6, "correct_answer": "帽子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天冷了，我把帽子围在脖子上。", "explanation": "这里应该用〈围巾〉。围在脖子上的是围巾，帽子是戴在头上的，不能“围”。"}, {"text": "他用一顶帽子写字。", "explanation": "这里应该用〈笔〉。写字要用笔，帽子是戴在头上的，不能用来写字。"}, {"text": "他脚上穿着一顶新帽子。", "explanation": "这里应该用〈鞋〉。脚上穿的是鞋，帽子是戴在头上的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天冷了，我穿上帽子出门。", "corrected_sentence": "天冷了，我戴上帽子出门。", "error_description": "动宾搭配错误：“帽子”要用“戴”，不能用“穿”。“穿”用于衣服、鞋袜。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一会儿上车前，请把帽子摘起来。", "corrected_sentence": "一会儿上车前，请把帽子摘下来。", "error_description": "补语错误：从头上拿下帽子要说“摘下来”，“摘起来”不能表示这个动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
