INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "戴在头上用来保暖、防晒或装饰的物品。", "primary_collocate": null, "pronunciation": "mào zi", "ipa": "maʊ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "冬天很冷，出门要戴帽子。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太阳很大，出门最好戴帽子。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给宝宝织了一顶毛线帽子。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顶帽子上有一朵小花，真好看。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她戴着一顶红帽子，很可爱。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，快把帽子戴上。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边阳光很强，我带了一顶帽子。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顶帽子很暖和，我冬天天天戴。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服配那顶帽子很好看。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都戴着彩色的帽子跳舞。", "target_word": "帽子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顶", "label": "量词"}, {"form": "草帽", "label": "复合"}, {"form": "毛线帽", "label": "复合"}], "register": "中性", "sense_fingerprint": "保暖、防晒或装饰用的头饰物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帽子", "is_correct": true, "explanation": "正确答案：mào zi，保暖、防晒或装饰用的头饰物品。"}, {"text": "耗子", "is_correct": false, "explanation": "耗子（hào zi）声母 h 与 m 不同，声调相同，意思是老鼠。"}, {"text": "套子", "is_correct": false, "explanation": "套子（tào zi）声母 t 与 m 不同，声调相同，意思是套在外面的罩子。"}, {"text": "泡子", "is_correct": false, "explanation": "泡子（pào zi）声母 p 与 m 不同，声调相同，意思是水洼或小湖，较少用。"}], "explanations": {"帽子": "正确答案：mào zi，保暖、防晒或装饰用的头饰物品。", "耗子": "耗子（hào zi）声母 h 与 m 不同，声调相同，意思是老鼠。", "套子": "套子（tào zi）声母 t 与 m 不同，声调相同，意思是套在外面的罩子。", "泡子": "泡子（pào zi）声母 p 与 m 不同，声调相同，意思是水洼或小湖，较少用。"}, "sentence_index": null, "correct_answer": "帽子"}, "level_3": {"options": [{"text": "帽子", "is_correct": true, "explanation": "正确：冬天出门保暖要戴的是帽子，“戴”与“帽子”搭配。"}, {"text": "鞋子", "is_correct": false, "explanation": "配价：“戴”不能带“鞋子”作宾语，鞋子要用“穿”。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：雨伞要用“打”或“撑”，不能用“戴”。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子不能戴在身上，句子说不通。"}], "explanations": {"帽子": "正确：冬天出门保暖要戴的是帽子，“戴”与“帽子”搭配。", "鞋子": "配价：“戴”不能带“鞋子”作宾语，鞋子要用“穿”。", "雨伞": "配价：雨伞要用“打”或“撑”，不能用“戴”。", "杯子": "语义：杯子不能戴在身上，句子说不通。"}, "sentence_index": 0, "correct_answer": "帽子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天很冷，她把帽子围在脖子上。", "explanation": "这里应该用〈围巾〉。围在脖子上的是围巾，帽子是戴在头上的。"}, {"text": "下雨了，她撑着一顶帽子出门。", "explanation": "这里应该用〈雨伞〉。下雨时撑的是雨伞，帽子要戴在头上，不能“撑”。"}, {"text": "她背着一顶帽子上学。", "explanation": "这里应该用〈书包〉。上学背的是书包，帽子是戴在头上的，不能“背”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96526, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帽子", "is_correct": true, "explanation": "正确答案：mào zi，保暖、防晒或装饰用的头饰物品。"}, {"text": "豹子", "is_correct": false, "explanation": "豹子（bào zi）声母 b 与 m 不同，意思是豹这种动物。"}, {"text": "稻子", "is_correct": false, "explanation": "稻子（dào zi）声母 d 与 m 不同，意思是稻谷。"}, {"text": "罩子", "is_correct": false, "explanation": "罩子（zhào zi）声母 zh 与 m 不同，声调相同，意思是罩在物体外面的东西。"}, {"text": "号子", "is_correct": false, "explanation": "号子（hào zi）声母 h 与 m 不同，声调相同，意思是劳动时喊的调子。"}], "explanations": {"帽子": "正确答案：mào zi，保暖、防晒或装饰用的头饰物品。", "豹子": "豹子（bào zi）声母 b 与 m 不同，意思是豹这种动物。", "稻子": "稻子（dào zi）声母 d 与 m 不同，意思是稻谷。", "罩子": "罩子（zhào zi）声母 zh 与 m 不同，声调相同，意思是罩在物体外面的东西。", "号子": "号子（hào zi）声母 h 与 m 不同，声调相同，意思是劳动时喊的调子。"}, "sentence_index": null, "correct_answer": "帽子"}, "level_3": {"options": [{"text": "帽子", "is_correct": true, "explanation": "正确：量词“顶”搭配“帽子”，句子说的是戴在头上的帽子。"}, {"text": "太阳镜", "is_correct": false, "explanation": "搭配：量词“顶”不能配“太阳镜”，应说“一副太阳镜”。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：量词“顶”不能配“书包”，书包一般说“一个”。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：量词“顶”不能配“手机”，手机说“一部”或“一个”。"}], "explanations": {"帽子": "正确：量词“顶”搭配“帽子”，句子说的是戴在头上的帽子。", "太阳镜": "搭配：量词“顶”不能配“太阳镜”，应说“一副太阳镜”。", "书包": "搭配：量词“顶”不能配“书包”，书包一般说“一个”。", "手机": "搭配：量词“顶”不能配“手机”，手机说“一部”或“一个”。"}, "sentence_index": 6, "correct_answer": "帽子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她脚上穿着一顶帽子去跑步。", "explanation": "这里应该用〈鞋〉。脚上穿的是鞋，帽子是戴在头上的。"}, {"text": "下雨了，她打着一顶帽子出门。", "explanation": "这里应该用〈伞〉。下雨时打的是伞，帽子是戴在头上的，不能“打”。"}, {"text": "她鼻梁上架着一顶帽子，很好看。", "explanation": "这里应该用〈眼镜〉。鼻梁上架的是眼镜，帽子要戴在头上，不能架在鼻梁上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
