INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96529, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用对了办法。", "primary_collocate": null, "pronunciation": "dé fǎ", "ipa": "tɤ˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家店经营得法，生意越来越好。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司管理得法，员工都很努力。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教育得法，孩子慢慢改掉了坏习惯。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他处理这件事很得法，没有伤到任何人。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民种地得法，今年的粮食又多了。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他养花得法，花开得又大又红。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理指挥得法，大家很快做完了工作。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察劝说得法，那个人终于放下了刀。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次宣传得法，来买东西的人多了很多。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带孩子得法，孩子从小就很听话。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不得法", "label": "否定"}], "register": "书面", "sense_fingerprint": "经营、管理、处理事情时所用办法对头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96529, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "得法", "is_correct": true, "explanation": "得法（dé fǎ）是本条目的目标词，形容用对了办法，经营、管理合乎要领。"}, {"text": "打法", "is_correct": false, "explanation": "dǎ fǎ 第一个字的韵母与声调都与 dé 不同，意思是做事或比赛的方式。"}, {"text": "答法", "is_correct": false, "explanation": "dá fǎ 第一个字的韵母与 dé 不同，意思是回答问题的方法。"}, {"text": "得分", "is_correct": false, "explanation": "dé fēn 第二个字的韵母与声调都与 fǎ 不同，意思是得到的分数。"}], "explanations": {"得法": "得法（dé fǎ）是本条目的目标词，形容用对了办法，经营、管理合乎要领。", "打法": "dǎ fǎ 第一个字的韵母与声调都与 dé 不同，意思是做事或比赛的方式。", "答法": "dá fǎ 第一个字的韵母与 dé 不同，意思是回答问题的方法。", "得分": "dé fēn 第二个字的韵母与声调都与 fǎ 不同，意思是得到的分数。"}, "sentence_index": null, "correct_answer": "得法"}, "level_3": {"options": [{"text": "懒散", "is_correct": false, "explanation": "语义：懒散指做事没有精神，与“生意越来越好”相矛盾。"}, {"text": "得法", "is_correct": true, "explanation": "得法：形容词，指经营的办法对头，所以生意才越来越好。"}, {"text": "亏本", "is_correct": false, "explanation": "语义：亏本指做生意赔钱，与“生意越来越好”相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "搭配：“经营”后不宜用“随便”评价经营方法，且与“生意越来越好”不协调。"}], "explanations": {"懒散": "语义：懒散指做事没有精神，与“生意越来越好”相矛盾。", "得法": "得法：形容词，指经营的办法对头，所以生意才越来越好。", "亏本": "语义：亏本指做生意赔钱，与“生意越来越好”相矛盾。", "随便": "搭配：“经营”后不宜用“随便”评价经营方法，且与“生意越来越好”不协调。"}, "sentence_index": 0, "correct_answer": "得法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很得法。", "explanation": "这里应该用〈合身〉。得法评价的是做法，不用来形容衣服；衣服穿着合适要说〈合身〉。"}, {"text": "今天的天气很得法。", "explanation": "这里应该用〈好〉。得法评价的是做法，不用来描述天气；形容天气要说〈好〉。"}, {"text": "我的床很得法。", "explanation": "这里应该用〈舒服〉。得法不能用来形容床这类家具；睡在床上的感受要说〈舒服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "糊涂", "is_correct": false, "explanation": "语义：糊涂指头脑不清楚，与“大家很快做完了工作”相矛盾。"}, {"text": "得法", "is_correct": true, "explanation": "得法：形容词，指指挥的办法对头，所以大家才能很快做完工作。"}, {"text": "拖沓", "is_correct": false, "explanation": "语义：拖沓指做事拖延，与“很快做完”相矛盾。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：混乱指秩序不清，与“大家很快做完了工作”相矛盾。"}], "explanations": {"糊涂": "语义：糊涂指头脑不清楚，与“大家很快做完了工作”相矛盾。", "得法": "得法：形容词，指指挥的办法对头，所以大家才能很快做完工作。", "拖沓": "语义：拖沓指做事拖延，与“很快做完”相矛盾。", "混乱": "语义：混乱指秩序不清，与“大家很快做完了工作”相矛盾。"}, "sentence_index": 6, "correct_answer": "得法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顿饭很得法。", "explanation": "这里应该用〈好吃〉。得法评价的是方法、做法，不用来形容饭菜；形容饭菜的味道要说〈好吃〉。"}, {"text": "这个房间很得法。", "explanation": "这里应该用〈干净〉。得法不能用来形容房间这类场所；形容房间的状态要说〈干净〉。"}, {"text": "这首诗很得法。", "explanation": "这里应该用〈优美〉。得法评价的是办事的方法，不用来形容诗歌；形容诗的文字要说〈优美〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板很管理得法，店里的生意一直不错。", "corrected_sentence": "老板管理得法，店里的生意一直不错。", "error_description": "错误形式：“很”放在动作动词“管理”前。正确形式：说“管理得法”。原因：“很”修饰形容词“得法”，不能直接修饰“管理”这类动作动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位厂长组织很的得法，产量一直很稳定。", "corrected_sentence": "这位厂长组织很得法，产量一直很稳定。", "error_description": "错误形式：“很”与“得法”之间多加了“的”。正确形式：说“组织很得法”。原因：程度副词“很”直接修饰形容词，中间不能插入“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
