INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96530, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "方法恰当、合乎要领。", "primary_collocate": null, "pronunciation": "dé fǎ", "ipa": "tɤ˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "他练字很得法，进步特别快。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样跑步才得法，膝盖不会疼。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她背单词很得法，一天能记五十个。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用力不得法，你的手腕才会累。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课得法，学生都爱听。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他复习得法，考试前一点儿也不紧张。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷打太极拳很得法，动作又慢又稳。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练琴不得法，花再多时间也没用。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刷牙得法，牙齿一直很健康。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这样按摩才算得法。", "target_word": "得法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不得法", "label": "否定"}], "register": "书面", "sense_fingerprint": "练习或做动作时技巧恰当，合乎要领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96530, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "得法", "is_correct": true, "explanation": "得法（dé fǎ）是本条目的目标词，形容方法恰当、合乎要领。"}, {"text": "打法", "is_correct": false, "explanation": "dǎ fǎ 第一个字的韵母与声调都与 dé 不同，意思是比赛或球类中的技术打法。"}, {"text": "答法", "is_correct": false, "explanation": "dá fǎ 第一个字的韵母与 dé 不同，意思是回答问题的方法。"}, {"text": "得分", "is_correct": false, "explanation": "dé fēn 第二个字的韵母与声调都与 fǎ 不同，意思是得到的分数。"}], "explanations": {"得法": "得法（dé fǎ）是本条目的目标词，形容方法恰当、合乎要领。", "打法": "dǎ fǎ 第一个字的韵母与声调都与 dé 不同，意思是比赛或球类中的技术打法。", "答法": "dá fǎ 第一个字的韵母与 dé 不同，意思是回答问题的方法。", "得分": "dé fēn 第二个字的韵母与声调都与 fǎ 不同，意思是得到的分数。"}, "sentence_index": null, "correct_answer": "得法"}, "level_3": {"options": [{"text": "马虎", "is_correct": false, "explanation": "语义：马虎指做事不仔细，与“进步特别快”相矛盾。"}, {"text": "得法", "is_correct": true, "explanation": "得法：形容词，指练字时方法恰当、合乎要领，所以进步快。"}, {"text": "慢吞吞", "is_correct": false, "explanation": "语义：慢吞吞指动作迟缓，与“进步特别快”不相符。"}, {"text": "随便", "is_correct": false, "explanation": "搭配：“随便”指不讲究，不用来评价练字的方法是否恰当。"}], "explanations": {"马虎": "语义：马虎指做事不仔细，与“进步特别快”相矛盾。", "得法": "得法：形容词，指练字时方法恰当、合乎要领，所以进步快。", "慢吞吞": "语义：慢吞吞指动作迟缓，与“进步特别快”不相符。", "随便": "搭配：“随便”指不讲究，不用来评价练字的方法是否恰当。"}, "sentence_index": 0, "correct_answer": "得法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯茶很得法。", "explanation": "这里应该用〈好喝〉。得法评价的是做法是否合乎要领，不用来形容饮料；形容茶的味道要说〈好喝〉。"}, {"text": "那张桌子很得法。", "explanation": "这里应该用〈合适〉。得法评价做法是否合乎要领，不用来形容桌子这类物品；桌子适合某种用途要说〈合适〉。"}, {"text": "我的弟弟很得法。", "explanation": "这里应该用〈能干〉。得法评价的是具体做法，不直接用来形容人的能力；形容人的能力要说〈能干〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va