INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笨拙", "is_correct": false, "explanation": "语义：笨拙指动作不灵活，与“动作又慢又稳”的描述相矛盾。"}, {"text": "得法", "is_correct": true, "explanation": "得法：形容词，指打拳时方法恰当、合乎要领，所以动作才又慢又稳。"}, {"text": "散漫", "is_correct": false, "explanation": "语义：散漫指纪律松懈，与“动作又慢又稳”的描述不协调。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：粗糙指做法不精细，与“动作又慢又稳”所描绘的精准控制不符。"}], "explanations": {"笨拙": "语义：笨拙指动作不灵活，与“动作又慢又稳”的描述相矛盾。", "得法": "得法：形容词，指打拳时方法恰当、合乎要领，所以动作才又慢又稳。", "散漫": "语义：散漫指纪律松懈，与“动作又慢又稳”的描述不协调。", "粗糙": "语义：粗糙指做法不精细，与“动作又慢又稳”所描绘的精准控制不符。"}, "sentence_index": 6, "correct_answer": "得法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌很得法。", "explanation": "这里应该用〈好听〉。得法评价的是做法是否合乎要领，不用来形容歌曲；形容歌曲的感受要说〈好听〉。"}, {"text": "那间教室很得法。", "explanation": "这里应该用〈宽敞〉。得法不能用来形容教室这类场所；描述空间大小要说〈宽敞〉。"}, {"text": "我的哥哥很得法。", "explanation": "这里应该用〈聪明〉。得法评价的是具体做法，不直接用来形容人的性格；形容人的头脑要说〈聪明〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打篮球了得法，投篮越来越准。", "corrected_sentence": "他打篮球很得法，投篮越来越准。", "error_description": "错误形式：“很”被换成了“了”。正确形式：说“打篮球很得法”。原因：“得法”是形容词，前面需要程度副词“很”来修饰；“了”是动态助词，不能修饰形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她学游泳很得得法，动作越来越标准。", "corrected_sentence": "她学游泳很得法，动作越来越标准。", "error_description": "错误形式：“很”后多加了一个“得”。正确形式：说“学游泳很得法”。原因：“很得法”中不需要补语标记“得”，多出的“得”使句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
