INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96532, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对国家、朋友或事业尽心尽力，没有二心。", "primary_collocate": null, "pronunciation": "zhōng chéng", "ipa": "ʈʂʊŋ˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他忠诚地为国家工作了三十年。", "target_word": "忠诚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师一生忠诚于教育事业。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "军人要忠诚于自己的国家。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对工作非常忠诚。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生忠诚地守着自己的岗位。", "target_word": "忠诚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对事业忠诚，从不偷懒。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是一位忠诚的志愿者。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要忠诚地完成任务。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对公司忠诚，干了二十年。", "target_word": "忠诚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这名警察对国家十分忠诚。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "忠诚度", "label": "复合"}, {"form": "忠诚地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "对国家、事业或朋友尽心尽力、没有二心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add11f56-6b71-44e4-ad75-5ff231dc05d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96532, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忠诚", "is_correct": true, "explanation": "忠诚 zhōng chéng：对国家、事业或朋友尽心尽力，没有二心。"}, {"text": "章程", "is_correct": false, "explanation": "zhāng 与 zhōng 韵母不同（a 与 o），意思是规章制度。"}, {"text": "征程", "is_correct": false, "explanation": "zhēng 与 zhōng 韵母不同（e 与 o），意思是旅途或历程。"}, {"text": "东城", "is_correct": false, "explanation": "dōng 与 zhōng 声母不同（d 与 zh），是地名，指北京的东城区。"}], "explanations": {"忠诚": "忠诚 zhōng chéng：对国家、事业或朋友尽心尽力，没有二心。", "章程": "zhāng 与 zhōng 韵母不同（a 与 o），意思是规章制度。", "征程": "zhēng 与 zhōng 韵母不同（e 与 o），意思是旅途或历程。", "东城": "dōng 与 zhōng 声母不同（d 与 zh），是地名，指北京的东城区。"}, "sentence_index": null, "correct_answer": "忠诚"}, "level_3": {"options": [{"text": "忠诚", "is_correct": true, "explanation": "忠诚：对国家尽心尽力，符合句意。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“为国家工作三十年”的尽心含义矛盾。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”说声音或场面，不能修饰工作的态度。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”表示没有感情，与为国家尽心工作相矛盾。"}], "explanations": {"忠诚": "忠诚：对国家尽心尽力，符合句意。", "懒惰": "语义：“懒惰”与“为国家工作三十年”的尽心含义矛盾。", "吵闹": "搭配：“吵闹”说声音或场面，不能修饰工作的态度。", "冷漠": "语义：“冷漠”表示没有感情，与为国家尽心工作相矛盾。"}, "sentence_index": 0, "correct_answer": "忠诚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部纪录片忠诚地记录了那段历史。", "explanation": "这里应该用〈忠实〉。忠诚修饰人对人或事的专一，记录历史要求与事实相符，应用忠实。"}, {"text": "他忠诚地说出了自己的看法。", "explanation": "这里应该用〈坦率〉。忠诚表示专一不变，说话直截了当要用坦率。"}, {"text": "他很忠诚地向大家请教问题。", "explanation": "这里应该用〈诚恳〉。忠诚表示对人或事尽心尽力、没有二心，向别人请教时的态度要用诚恳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96532, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忠诚", "is_correct": true, "explanation": "忠诚 zhōng chéng：对国家、事业或朋友尽心尽力，没有二心。"}, {"text": "冲程", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch 与 zh），意思是发动机的冲程。"}, {"text": "中层", "is_correct": false, "explanation": "céng 与 chéng 声母不同（c 与 ch），意思是中间的一层。"}, {"text": "忠臣", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n 与 ng），意思是忠心的大臣。"}, {"text": "工程", "is_correct": false, "explanation": "gōng 与 zhōng 声母不同（g 与 zh），意思是工程项目。"}], "explanations": {"忠诚": "忠诚 zhōng chéng：对国家、事业或朋友尽心尽力，没有二心。", "冲程": "chōng 与 zhōng 声母不同（ch 与 zh），意思是发动机的冲程。", "中层": "céng 与 chéng 声母不同（c 与 ch），意思是中间的一层。", "忠臣": "chén 与 chéng 韵尾不同（n 与 ng），意思是忠心的大臣。", "工程": "gōng 与 zhōng 声母不同（g 与 zh），意思是工程项目。"}, "sentence_index": null, "correct_answer": "忠诚"}, "level_3": {"options": [{"text": "忠诚", "is_correct": true, "explanation": "忠诚：对人或事一心一意，符合“一位……的志愿者”的语境。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格，不能修饰人。"}, {"text": "残忍", "is_correct": false, "explanation": "语义：“残忍”与志愿者的善意形象相反。"}, {"text": "废弃", "is_correct": false, "explanation": "搭配：“废弃”说被抛弃的物品，不能修饰人。"}], "explanations": {"忠诚": "忠诚：对人或事一心一意，符合“一位……的志愿者”的语境。", "昂贵": "搭配：“昂贵”说价格，不能修饰人。", "残忍": "语义：“残忍”与志愿者的善意形象相反。", "废弃": "搭配：“废弃”说被抛弃的物品，不能修饰人。"}, "sentence_index": 6, "correct_answer": "忠诚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很忠诚，做生意从不吃亏。", "explanation": "这里应该用〈精明〉。忠诚说的是对人或事的专一，形容做生意的头脑要用精明。"}, {"text": "这位老师说话很忠诚。", "explanation": "这里应该用〈温和〉。忠诚不描述说话的语气，语气柔和要用温和。"}, {"text": "大家忠诚欢迎他的到来。", "explanation": "这里应该用〈热烈〉。忠诚表示专一不变，欢迎的热情要用热烈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_u