INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "本来就该有的。", "primary_collocate": null, "pronunciation": "yīng yǒu", "ipa": "iŋ˥ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座桥已经失去了应有的作用。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子旧了，没有应有的样子。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩没有达到应有的水平。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，花园又有了应有的生气。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书都放回了应有的位置。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们应有的快乐，一样也不能少。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章缺少应有的内容。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了问题，他却没有应有的反应。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话没有发挥应有的作用。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法没有起到应有的效果。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "应有：事物本来就该有的作用、水平、样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd993da7-f591-4be8-b96c-80369c56fa87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应有", "is_correct": true, "explanation": "正确：应有指桥本来应当具有的作用。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的对象是费用，不说收取作用。"}, {"text": "享有", "is_correct": false, "explanation": "搭配：“享有”的对象是权利、声誉，不说享有桥的作用。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指主动丢掉，与“失去”所表示的被动丢失语境不合。"}], "explanations": {"应有": "正确：应有指桥本来应当具有的作用。", "收取": "搭配：“收取”的对象是费用，不说收取作用。", "享有": "搭配：“享有”的对象是权利、声誉，不说享有桥的作用。", "放弃": "语义：“放弃”指主动丢掉，与“失去”所表示的被动丢失语境不合。"}, "sentence_index": 0, "correct_answer": "应有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地上有一些应有的垃圾。", "explanation": "这里应该用〈乱扔的〉。应有指本来就该有的，垃圾不是地上本来该有的东西。"}, {"text": "桥上出现了几道应有的裂缝。", "explanation": "这里应该用〈新的〉。裂缝是损坏，不是桥本来就该有的。"}, {"text": "这碗汤里有一根应有的头发。", "explanation": "这里应该用〈多余的〉。头发不是汤里本来就该有的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应有", "is_correct": true, "explanation": "正确：应有指文章本来应当具备的内容，与“缺少”相呼应。"}, {"text": "免除", "is_correct": false, "explanation": "搭配：“免除”的对象是义务、责任，不说免除内容。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的对象是费用，不说收取内容。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”表示已经具备，与“缺少”前后矛盾。"}], "explanations": {"应有": "正确：应有指文章本来应当具备的内容，与“缺少”相呼应。", "免除": "搭配：“免除”的对象是义务、责任，不说免除内容。", "收取": "搭配：“收取”的对象是费用，不说收取内容。", "拥有": "语义：“拥有”表示已经具备，与“缺少”前后矛盾。"}, "sentence_index": 6, "correct_answer": "应有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件新衣服上有一个应有的破洞。", "explanation": "这里应该用〈难看的〉。破洞不是新衣服本来就该有的。"}, {"text": "电脑出了一个应有的故障。", "explanation": "这里应该用〈意外的〉。故障不是电脑本来就该有的。"}, {"text": "他的作业里有很多应有的错字。", "explanation": "这里应该用〈不该有的〉。错字不是作业本来就该有的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器应有了的功能都要保留。", "corrected_sentence": "这台机器应有的功能都要保留。", "error_description": "错误在“应有”之后加了“了”。“应有的”是修饰名词的形式，“了”不能附在“应有”后面；应改为“应有的功能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章缺少应有地结构。", "corrected_sentence": "这篇文章缺少应有的结构。", "error_description": "错误在“应有地”。“应有”修饰名词“结构”，要用“的”；“地”只用于修饰动词。应改为“应有的结构”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
