INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "应当具有的；理应有的。", "primary_collocate": null, "pronunciation": "yīng yǒu", "ipa": "iŋ˥ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们要给孩子应有的尊重。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人应有的照顾，家人要做到。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得到了应有的奖励。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司没有应有的责任感。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作做好了，就能得到应有的回报。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生应有的礼貌，他都做到了。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里缺少应有的安全措施。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我们应有的帮助。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为这件事付出了应有的代价。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生应有的耐心，她一点也不缺。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "应有：按道理、按身份应当具有（尊重、权利、责任等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd993da7-f591-4be8-b96c-80369c56fa87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应有", "is_correct": true, "explanation": "正确：应有表示按道理应当具有，此处指孩子应得的尊重。"}, {"text": "索取", "is_correct": false, "explanation": "语义：“索取”是向别人讨要，与“给孩子”的给予方向相反。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的对象是费用、钱款，不说收取尊重。"}, {"text": "免除", "is_correct": false, "explanation": "搭配：“免除”的对象是义务、责任，不能说免除尊重。"}], "explanations": {"应有": "正确：应有表示按道理应当具有，此处指孩子应得的尊重。", "索取": "语义：“索取”是向别人讨要，与“给孩子”的给予方向相反。", "收取": "搭配：“收取”的对象是费用、钱款，不说收取尊重。", "免除": "搭配：“免除”的对象是义务、责任，不能说免除尊重。"}, "sentence_index": 0, "correct_answer": "应有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她无缘无故受到了应有的批评。", "explanation": "这里应该用〈不该有的〉。“无缘无故”说明批评不是她理应得到的，与应有矛盾。"}, {"text": "工人们白白受了应有的冤枉。", "explanation": "这里应该用〈不该受的〉。冤枉本来就不应该受，不能说应有的冤枉。"}, {"text": "他不小心犯了一个应有的错误。", "explanation": "这里应该用〈不该犯的〉。错误不是按理应当具有的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应有", "is_correct": true, "explanation": "正确：应有指本来应当具备的安全措施，与“缺少”前后呼应。"}, {"text": "享有", "is_correct": false, "explanation": "搭配：“享有”后接权利、待遇、声誉，不说享有安全措施。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”表示已经具备，与“缺少”的语境正相反。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的对象是费用、钱款，不说收取安全措施。"}], "explanations": {"应有": "正确：应有指本来应当具备的安全措施，与“缺少”前后呼应。", "享有": "搭配：“享有”后接权利、待遇、声誉，不说享有安全措施。", "拥有": "语义：“拥有”表示已经具备，与“缺少”的语境正相反。", "收取": "搭配：“收取”的对象是费用、钱款，不说收取安全措施。"}, "sentence_index": 6, "correct_answer": "应有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师错怪了他，给了他应有的批评。", "explanation": "这里应该用〈不该有的〉。老师错怪了他，批评就不是他理应得到的。"}, {"text": "这场意外让他遭受了应有的痛苦。", "explanation": "这里应该用〈不必要的〉。意外带来的痛苦不是按理应当具有的。"}, {"text": "她平白无故挨了一顿应有的骂。", "explanation": "这里应该用〈冤枉的〉。“平白无故”说明挨骂不是她理应得到的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都应有了做人的尊严。", "corrected_sentence": "每个人都应有做人的尊严。", "error_description": "错误在“应有”后加了“了”。“应有”表示按理应当具有，后面直接接名词短语，不带“了”；应改为“每个人都应有做人的尊严”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作应有地待遇不能少。", "corrected_sentence": "这份工作应有的待遇不能少。", "error_description": "错误在“应有”之后用了“地”。“应有”修饰名词，要用“的”；“地”用于修饰动词。应改为“应有的待遇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0f7c755-6ccf-47af-baa1-469498754c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
