INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96537, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把话、事实等说成不对的样子，使其失去原意。", "primary_collocate": null, "pronunciation": "niǔ qū", "ipa": "niou̯²¹⁴ tɕʰy⁵⁵", "syllable_count": 2, "sentences": [{"text": "他故意扭曲我的话。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要扭曲事实。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我的意思扭曲了。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事实扭曲了，让大家误会了这件事。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者不应该扭曲别人说的话。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告把产品的优点扭曲了。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人总是扭曲老师的好意。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别扭曲这个故事，真实情况不是这样。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把老师的解释扭曲得面目全非。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸扭曲了这件事的经过。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扭曲了", "label": "体标（了）"}, {"form": "扭曲着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "把话、事实或意思说歪，使其失真", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扭曲", "is_correct": true, "explanation": "正确。“扭曲”指把话说歪，与“故意”相合。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人或帮助，不说“感谢我的话”。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”指搬动实体东西，不能用于话语。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体燃烧，与“话”不相合。"}], "explanations": {"扭曲": "正确。“扭曲”指把话说歪，与“故意”相合。", "感谢": "搭配：“感谢”的对象是人或帮助，不说“感谢我的话”。", "搬运": "语义：“搬运”指搬动实体东西，不能用于话语。", "点燃": "语义：“点燃”指使物体燃烧，与“话”不相合。"}, "sentence_index": 0, "correct_answer": "扭曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把鸡蛋扭曲了。", "explanation": "这里应该用〈打〉。扭曲指把直东西弄弯或说歪，打散鸡蛋要用打。"}, {"text": "他把墙扭曲了一遍。", "explanation": "这里应该用〈涂抹〉。扭曲指弄弯或说歪，给墙面涂东西要用涂抹。"}, {"text": "工人在铁板上扭曲了几个孔。", "explanation": "这里应该用〈穿孔〉。扭曲指弄弯或说歪，在板子上打洞要用穿孔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扭曲", "is_correct": true, "explanation": "正确。“扭曲”指误解或说歪别人的好意，与“总是”的习惯性相合。"}, {"text": "收集", "is_correct": false, "explanation": "搭配：“收集”一般搭配资料、物品，不说“收集好意”。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、温度等，不能说“测量好意”。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：“砍伐”指砍树，与“老师的好意”不相合。"}], "explanations": {"扭曲": "正确。“扭曲”指误解或说歪别人的好意，与“总是”的习惯性相合。", "收集": "搭配：“收集”一般搭配资料、物品，不说“收集好意”。", "测量": "搭配：“测量”的对象是长度、温度等，不能说“测量好意”。", "砍伐": "语义：“砍伐”指砍树，与“老师的好意”不相合。"}, "sentence_index": 6, "correct_answer": "扭曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秘书把这份合同扭曲了一份。", "explanation": "这里应该用〈复印〉。扭曲指弄弯或说歪，复制文件要用复印。"}, {"text": "工人把木板扭曲成几小块。", "explanation": "这里应该用〈切割〉。扭曲指弄弯或说歪，把木板分开要用切割。"}, {"text": "她在手帕上扭曲了一朵花。", "explanation": "这里应该用〈绣〉。扭曲指弄弯或说歪，在布面上做刺绣要用绣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他故意扭曲着了我的话。", "corrected_sentence": "他故意扭曲了我的话。", "error_description": "错误形式“扭曲着了”，“着”和“了”不能叠用；这里表示动作已经完成，只用“了”，正确形式为“扭曲了我的话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "媒体把事实扭曲地很严重。", "corrected_sentence": "媒体把事实扭曲得很严重。", "error_description": "错误形式“扭曲地很严重”，动词后接程度补语要用“得”而非“地”，正确形式为“扭曲得很严重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
