INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96538, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使物体、面容或影像的样子变形走样。", "primary_collocate": null, "pronunciation": "niǔ qū", "ipa": "niou̯²¹⁴ tɕʰy⁵⁵", "syllable_count": 2, "sentences": [{"text": "他疼得脸都扭曲了。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面旧镜子把我的脸扭曲了。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温会使塑料瓶慢慢扭曲。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹过水面，月亮的影子扭曲了。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片的图像都扭曲了。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热空气让远处的房子看起来扭曲了。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块铁板受热后扭曲变形。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕坏了，上面的字都扭曲了。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怪镜子会把人的身体扭曲得不成样子。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生气的时候，笑容有点扭曲。", "target_word": "扭曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扭曲了", "label": "体标（了）"}, {"form": "扭曲着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "样子、影像或面容变形走样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扭曲", "is_correct": true, "explanation": "正确。“扭曲”指样子变形，与“疼得”引起的表情变化相合。"}, {"text": "扭转", "is_correct": false, "explanation": "搭配：“扭转”多用于局面、趋势、方向，不说“脸都扭转了”。"}, {"text": "挺直", "is_correct": false, "explanation": "语义：“挺直”指伸直，与“疼得”时面部的状态不合。"}, {"text": "放松", "is_correct": false, "explanation": "语义：“放松”指舒展不紧张，与“疼得”的状态相反。"}], "explanations": {"扭曲": "正确。“扭曲”指样子变形，与“疼得”引起的表情变化相合。", "扭转": "搭配：“扭转”多用于局面、趋势、方向，不说“脸都扭转了”。", "挺直": "语义：“挺直”指伸直，与“疼得”时面部的状态不合。", "放松": "语义：“放松”指舒展不紧张，与“疼得”的状态相反。"}, "sentence_index": 0, "correct_answer": "扭曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "阳光晒了很久，这件红衣服扭曲了。", "explanation": "这里应该用〈褪色〉。扭曲指形状或样子变形，衣服颜色变淡要用褪色。"}, {"text": "他走路时不小心扭曲了脚。", "explanation": "这里应该用〈扭伤〉。扭曲指物体变形，人的关节受伤要用扭伤。"}, {"text": "糖放进热水后慢慢扭曲了。", "explanation": "这里应该用〈溶解〉。扭曲指形状变样，固体在液体里化开要用溶解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扭曲", "is_correct": true, "explanation": "正确。“扭曲”指弯斜走样，与“变形”搭配通顺。"}, {"text": "腐蚀", "is_correct": false, "explanation": "语义：“腐蚀”指被化学物质侵蚀，与句中“受热”的原因不合。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指遇冷凝固，与“受热”的条件相反。"}, {"text": "磨损", "is_correct": false, "explanation": "语义：“磨损”指因摩擦而耗损，与句中“受热”的原因不合。"}], "explanations": {"扭曲": "正确。“扭曲”指弯斜走样，与“变形”搭配通顺。", "腐蚀": "语义：“腐蚀”指被化学物质侵蚀，与句中“受热”的原因不合。", "冻结": "语义：“冻结”指遇冷凝固，与“受热”的条件相反。", "磨损": "语义：“磨损”指因摩擦而耗损，与句中“受热”的原因不合。"}, "sentence_index": 6, "correct_answer": "扭曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块面包放久了，扭曲了味道。", "explanation": "这里应该用〈变质〉。扭曲指样子变形，不能用来描述味道；食物变坏要用变质。"}, {"text": "这把银勺子氧化后扭曲了。", "explanation": "这里应该用〈变黑〉。扭曲指形状变样，金属表面氧化后颜色变暗要用变黑。"}, {"text": "墙上的漆扭曲了一大块。", "explanation": "这里应该用〈脱落〉。扭曲指形状变形，油漆一块块剥落要用脱落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一用力，脸都扭曲着了。", "corrected_sentence": "他一用力，脸都扭曲了。", "error_description": "错误形式“扭曲着了”，应为“扭曲了”。“着”表示状态的持续，与表示变化实现的“了”不能叠用，此处只用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那块铁板受热后扭曲地很厉害。", "corrected_sentence": "那块铁板受热后扭曲得很厉害。", "error_description": "错误形式“扭曲地很厉害”，补语前应用“得”而非“地”，正确形式为“扭曲得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
