INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96539, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或布在东西上擦过去。", "primary_collocate": null, "pronunciation": "mǒ", "ipa": "mɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "请你用布把桌子抹一下。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手抹了抹头上的汗。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抹掉了脸上的眼泪。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在抹窗台上的灰。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把黑板抹干净了。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿毛巾抹了抹嘴。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板脏了，快拿布来抹一抹。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用袖子抹了一下鼻子。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把镜子上的水抹干。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边哭，一边用手抹眼泪。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抹了", "label": "体标"}, {"form": "抹着", "label": "体标"}, {"form": "抹过", "label": "体标"}, {"form": "抹抹", "label": "重叠"}, {"form": "抹布", "label": "复合"}], "register": "口语", "sense_fingerprint": "用手或布擦拭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抹", "is_correct": true, "explanation": "正确答案：mǒ，用手或布在东西上擦过去。"}, {"text": "磨", "is_correct": false, "explanation": "磨（mó）与抹（mǒ）声调不同，意思是把东西弄碎或弄光滑。"}, {"text": "沫", "is_correct": false, "explanation": "沫（mò）与抹（mǒ）声调不同，意思是泡沫。"}, {"text": "码", "is_correct": false, "explanation": "码（mǎ）韵母 a 与抹的 o 不同，声调相同，意思是数量或堆放。"}], "explanations": {"抹": "正确答案：mǒ，用手或布在东西上擦过去。", "磨": "磨（mó）与抹（mǒ）声调不同，意思是把东西弄碎或弄光滑。", "沫": "沫（mò）与抹（mǒ）声调不同，意思是泡沫。", "码": "码（mǎ）韵母 a 与抹的 o 不同，声调相同，意思是数量或堆放。"}, "sentence_index": null, "correct_answer": "抹"}, "level_3": {"options": [{"text": "抹", "is_correct": true, "explanation": "正确：“抹”表示用布擦桌子，句子通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：桌子不能唱，句子说不通。"}, {"text": "切", "is_correct": false, "explanation": "语义：用布不能切桌子，句子说不通。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“用布”与“摸”不搭配，擦桌子不说“用布摸”。"}], "explanations": {"抹": "正确：“抹”表示用布擦桌子，句子通顺。", "唱": "语义：桌子不能唱，句子说不通。", "切": "语义：用布不能切桌子，句子说不通。", "摸": "搭配：“用布”与“摸”不搭配，擦桌子不说“用布摸”。"}, "sentence_index": 0, "correct_answer": "抹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抹了一口水，觉得很解渴。", "explanation": "这里应该用〈喝〉。喝水要用“喝”，“抹”是用手或布擦过去。"}, {"text": "风在窗台上抹走了灰。", "explanation": "这里应该用〈吹〉。风吹走灰尘要用“吹”，“抹”要靠手或布接触表面。"}, {"text": "他一脚抹开了门。", "explanation": "这里应该用〈踢〉。用脚踢门要用“踢”，“抹”是用手或布擦过去，不能表示用脚开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96539, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抹", "is_correct": true, "explanation": "正确答案：mǒ，用手或布在东西上擦过去。"}, {"text": "墨", "is_correct": false, "explanation": "墨（mò）与抹（mǒ）声调不同，意思是墨水。"}, {"text": "马", "is_correct": false, "explanation": "马（mǎ）韵母 a 与抹的 o 不同，声调相同，意思是马。"}, {"text": "摸", "is_correct": false, "explanation": "摸（mō）声调不同，意思是用手接触。"}], "explanations": {"抹": "正确答案：mǒ，用手或布在东西上擦过去。", "墨": "墨（mò）与抹（mǒ）声调不同，意思是墨水。", "马": "马（mǎ）韵母 a 与抹的 o 不同，声调相同，意思是马。", "摸": "摸（mō）声调不同，意思是用手接触。"}, "sentence_index": null, "correct_answer": "抹"}, "level_3": {"options": [{"text": "抹", "is_correct": true, "explanation": "正确：“抹一抹”表示用布擦地板，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：布不能吃，句子说不通。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”多指熨衣服，不说用布烫地板。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：布不能嚼，句子说不通。"}], "explanations": {"抹": "正确：“抹一抹”表示用布擦地板，句子通顺。", "吃": "语义：布不能吃，句子说不通。", "烫": "搭配：“烫”多指熨衣服，不说用布烫地板。", "嚼": "语义：布不能嚼，句子说不通。"}, "sentence_index": 6, "correct_answer": "抹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个人一起抹着箱子上楼。", "explanation": "这里应该用〈抬〉。抬箱子要用“抬”，“抹”是用手或布擦过去，不能用于抬东西。"}, {"text": "他用剪刀抹了一下纸。", "explanation": "这里应该用〈剪〉。剪纸要用“剪”，“抹”指用手或布擦过去。"}, {"text": "他坐在椅子上抹了一本书。", "explanation": "这里应该用〈看〉。看书要用“看”，“抹”是用手或布擦过去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用手把头上的汗抹了干。", "corrected_sentence": "他用手把头上的汗抹干了。", "error_description": "体标位置错误：「了」应放在补语「干」之后，「抹了干」不通，应说「抹干了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "快用布地板抹一下。", "corrected_sentence": "快用布把地板抹一下。", "error_description": "漏掉“把”字：要表示用布处理地板，应说“把地板抹一下”，“用布地板抹”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
