INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96540, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把膏状或液体等东西涂在物体的表面上。", "primary_collocate": null, "pronunciation": "mǒ", "ipa": "mɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "睡觉前，她在脸上抹了面霜。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前别忘了抹防晒霜。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在伤口上抹了一点药。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在面包上抹了一层果酱。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在晒伤的皮肤上抹了一点芦荟胶。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把药膏抹在红肿的地方。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在手上抹了一点油。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在胳膊上抹了一点驱蚊水。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在嘴唇上抹了一点唇膏。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在蛋糕上抹一点奶油。", "target_word": "抹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抹了", "label": "体标"}, {"form": "抹着", "label": "体标"}, {"form": "抹过", "label": "体标"}, {"form": "抹抹", "label": "重叠"}, {"form": "抹布", "label": "复合"}], "register": "口语", "sense_fingerprint": "涂抹；把东西涂在表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96540, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抹", "is_correct": true, "explanation": "正确答案：mǒ，把东西涂在表面。"}, {"text": "墨", "is_correct": false, "explanation": "墨（mò）与抹（mǒ）声调不同，意思是墨水。"}, {"text": "马", "is_correct": false, "explanation": "马（mǎ）韵母 a 与抹的 o 不同，声调相同，意思是马。"}, {"text": "摸", "is_correct": false, "explanation": "摸（mō）声调不同，意思是用手接触。"}], "explanations": {"抹": "正确答案：mǒ，把东西涂在表面。", "墨": "墨（mò）与抹（mǒ）声调不同，意思是墨水。", "马": "马（mǎ）韵母 a 与抹的 o 不同，声调相同，意思是马。", "摸": "摸（mō）声调不同，意思是用手接触。"}, "sentence_index": null, "correct_answer": "抹"}, "level_3": {"options": [{"text": "抹", "is_correct": true, "explanation": "正确：“抹”表示把面霜涂在脸上，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：面霜不能吃，句子说不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：面霜不能喝，句子说不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不用于在脸上涂东西，“在脸上”后不接“扔”。"}], "explanations": {"抹": "正确：“抹”表示把面霜涂在脸上，句子通顺。", "吃": "语义：面霜不能吃，句子说不通。", "喝": "语义：面霜不能喝，句子说不通。", "扔": "搭配：“扔”不用于在脸上涂东西，“在脸上”后不接“扔”。"}, "sentence_index": 0, "correct_answer": "抹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在墙上抹了一张画。", "explanation": "这里应该用〈贴〉。贴用于纸张、画等平面物品，“抹”用于膏状或液体，不能“抹”一张画。"}, {"text": "妈妈抹着孩子走进了屋子。", "explanation": "这里应该用〈抱〉。抱着孩子要用“抱”，“抹”指用手或布擦过去或涂上，不能表示搂着。"}, {"text": "她在杯子里抹了一点牛奶。", "explanation": "这里应该用〈倒〉。往杯子里加液体用“倒”，“抹”是涂在表面上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96540, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抹", "is_correct": true, "explanation": "正确答案：mǒ，把东西涂在表面。"}, {"text": "磨", "is_correct": false, "explanation": "磨（mó）与抹（mǒ）声调不同，意思是把东西弄碎或弄光滑。"}, {"text": "沫", "is_correct": false, "explanation": "沫（mò）与抹（mǒ）声调不同，意思是泡沫。"}, {"text": "码", "is_correct": false, "explanation": "码（mǎ）韵母 a 与抹的 o 不同，声调相同，意思是数量或堆放。"}], "explanations": {"抹": "正确答案：mǒ，把东西涂在表面。", "磨": "磨（mó）与抹（mǒ）声调不同，意思是把东西弄碎或弄光滑。", "沫": "沫（mò）与抹（mǒ）声调不同，意思是泡沫。", "码": "码（mǎ）韵母 a 与抹的 o 不同，声调相同，意思是数量或堆放。"}, "sentence_index": null, "correct_answer": "抹"}, "level_3": {"options": [{"text": "抹", "is_correct": true, "explanation": "正确：“抹”表示把油涂在手上，句子通顺。"}, {"text": "晒", "is_correct": false, "explanation": "搭配：“晒”不用于在手上涂油，这里不能用“晒”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：油不能在手上煮，句子说不通。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：油不能嚼，句子说不通。"}], "explanations": {"抹": "正确：“抹”表示把油涂在手上，句子通顺。", "晒": "搭配：“晒”不用于在手上涂油，这里不能用“晒”。", "煮": "语义：油不能在手上煮，句子说不通。", "嚼": "语义：油不能嚼，句子说不通。"}, "sentence_index": 6, "correct_answer": "抹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把这幅画抹在客厅的墙上。", "explanation": "这里应该用〈挂〉。画要挂起来，“抹”用于涂在表面的膏状物，不能“抹”一幅画。"}, {"text": "请在桌上抹一块蛋糕。", "explanation": "这里应该用〈摆〉。摆放整块蛋糕要用“摆”，“抹”用于涂在表面的膏状物。"}, {"text": "妈妈把花抹在瓶里。", "explanation": "这里应该用〈插〉。把花放进瓶里要用“插”，“抹”指用手或布擦到或涂在表面上，不能用于放进瓶中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班后，她在脸上抹了着面霜。", "corrected_sentence": "下班后，她在脸上抹了面霜。", "error_description": "体标错误：「了」与「着」不能并用在同一动词后，「抹了着面霜」不通；表示完成应说「抹了面霜」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请饼干上抹一点奶油。", "corrected_sentence": "请在饼干上抹一点奶油。", "error_description": "介词遗漏：表示涂抹的位置要在“抹”前面用“在＋处所”，应说“在饼干上抹一点奶油”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "装", "is_correct": true, "explanation": "反义词：装指把零件组合成整体，与拆（分开）相反。"}, {"text": "搬", "is_correct": false, "explanation": "不是反义词：搬表示移动位置，与拆没有对立关系。"}, {"text": "送", "is_correct": false, "explanation": "不是反义词：送表示交付，与拆没有对立关系。"}, {"text": "修", "is_correct": false, "explanation": "不是反义词：修表示修理，与拆没有对立关系。"}], "correct_answer": "装", "explanations": {"装": "反义词：装指把零件组合成整体，与拆（分开）相反。", "搬": "不是反义词：搬表示移动位置，与拆没有对立关系。", "送": "不是反义词：送表示交付，与拆没有对立关系。", "修": "不是反义词：修表示修理，与拆没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "装", "is_correct": true, "explanation": "反义词：装指把零件组合成整体，与拆（分开）相反。"}, {"text": "吃", "is_correct": false, "explanation": "不是反义词：吃指把食物咽下，与拆没有对立关系。"}, {"text": "读", "is_correct": false, "explanation": "不是反义词：读表示看文字并理解，与拆没有对立关系。"}, {"text": "洗", "is_correct": false, "explanation": "不是反义词：洗表示用水去污，与拆没有对立关系。"}], "correct_answer": "装", "explanations": {"装": "反义词：装指把零件组合成整体，与拆（分开）相反。", "吃": "不是反义词：吃指把食物咽下，与拆没有对立关系。", "读": "不是反义词：读表示看文字并理解，与拆没有对立关系。", "洗": "不是反义词：洗表示用水去污，与拆没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个东西分开，一块一块拿下来。", "primary_collocate": null, "pronunciation": "chāi", "ipa": "ʈʂʰai̯˥", "syllable_count": 1, "sentences": [{"text": "他把旧毛衣拆了，重新织了一件。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在拆旧窗帘上的线。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把玩具车拆成了很多小块。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这个书架拆下来，搬到楼上。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把旧桌子一块一块拆下来。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拆着旧衣服上的扣子。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧电脑，我从来没拆过。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把坏了的钟拆了，看看里面。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我拆一下这张旧床。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明喜欢拆东西，总想看看里面是什么。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拆了", "label": "体标"}, {"form": "拆过", "label": "体标"}, {"form": "拆开", "label": "复合"}, {"form": "拆掉", "label": "复合"}], "register": "口语", "sense_fingerprint": "把整体的东西分开，一块一块拿下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add11f56-6b71-44e4-ad75-5ff231dc05d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆 chāi：把整体的东西分开，一块一块拿下来。"}, {"text": "柴", "is_correct": false, "explanation": "chái 与 chāi 声调不同，意思是柴火。"}, {"text": "猜", "is_correct": false, "explanation": "cāi 与 chāi 声母不同（c 与 ch），意思是猜测。"}, {"text": "筛", "is_correct": false, "explanation": "shāi 与 chāi 声母不同（sh 与 ch），意思是筛子。"}], "explanations": {"拆": "拆 chāi：把整体的东西分开，一块一块拿下来。", "柴": "chái 与 chāi 声调不同，意思是柴火。", "猜": "cāi 与 chāi 声母不同（c 与 ch），意思是猜测。", "筛": "shāi 与 chāi 声母不同（sh 与 ch），意思是筛子。"}, "sentence_index": null, "correct_answer": "拆"}, "level_3": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆：把毛衣拆开重新织，符合句意。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”说移动，不能说把毛衣处理掉后再织。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把东西放进嘴里，与毛衣无关。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚碰撞，不能用于毛衣。"}], "explanations": {"拆": "拆：把毛衣拆开重新织，符合句意。", "搬": "搭配：“搬”说移动，不能说把毛衣处理掉后再织。", "吃": "语义：“吃”指把东西放进嘴里，与毛衣无关。", "踢": "语义：“踢”是用脚碰撞，不能用于毛衣。"}, "sentence_index": 0, "correct_answer": "拆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把树上的苹果拆下来，带回家。", "explanation": "这里应该用〈摘〉。拆指把整体分开，从树上采果实要用摘。"}, {"text": "我想把衣服从衣架上拆下来，穿走。", "explanation": "这里应该用〈取〉。拆指把整体的部件分开，从衣架上拿下衣服要用取。"}, {"text": "我想把脚上的鞋拆下来，换双拖鞋。", "explanation": "这里应该用〈脱〉。拆指分开整体的部件，脱鞋要用脱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆 chāi：把整体的东西分开，一块一块拿下来。"}, {"text": "叉", "is_correct": false, "explanation": "chā 与 chāi 韵母不同，意思是叉子。"}, {"text": "呆", "is_correct": false, "explanation": "dāi 与 chāi 声母不同（d 与 ch），意思是呆板。"}, {"text": "摘", "is_correct": false, "explanation": "zhāi 与 chāi 声母不同（zh 与 ch），意思是摘下。"}], "explanations": {"拆": "拆 chāi：把整体的东西分开，一块一块拿下来。", "叉": "chā 与 chāi 韵母不同，意思是叉子。", "呆": "dāi 与 chāi 声母不同（d 与 ch），意思是呆板。", "摘": "zhāi 与 chāi 声母不同（zh 与 ch），意思是摘下。"}, "sentence_index": null, "correct_answer": "拆"}, "level_3": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆：表示拆开过、分解过，符合“从来没……过”的语境。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”只用于食物，不能用于电脑。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与电脑无关。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”用于动物或婴儿，不能用于电脑。"}], "explanations": {"拆": "拆：表示拆开过、分解过，符合“从来没……过”的语境。", "煮": "搭配：“煮”只用于食物，不能用于电脑。", "唱": "语义：“唱”指发出歌声，与电脑无关。", "喂": "搭配：“喂”用于动物或婴儿，不能用于电脑。"}, "sentence_index": 6, "correct_answer": "拆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都拆一锅汤，给全家喝。", "explanation": "这里应该用〈煮〉。拆指分开或拆下部件，不能用于汤；做汤要用煮。"}, {"text": "她每天都拆碗，从不偷懒。", "explanation": "这里应该用〈洗〉。拆指分开或拆毁，洗碗要用洗。"}, {"text": "他喜欢拆歌，每天都拆一首新歌。", "explanation": "这里应该用〈唱〉。拆不能用于歌曲，唱歌要用唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸把旧抽屉拆上来，换了新的。", "corrected_sentence": "爸爸把旧抽屉拆下来，换了新的。", "error_description": "“拆”后的趋向补语应为“下来”（表示从整体上分离），用“上来”表示方向错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没拆了这种旧收音机。", "corrected_sentence": "我从来没拆过这种旧收音机。", "error_description": "“从来没……过”表示经历，“拆”后应用“过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "建", "is_correct": true, "explanation": "反义词：建指建造，与把建筑拆毁相反。"}, {"text": "写", "is_correct": false, "explanation": "不是反义词：写表示书写，与拆没有对立关系。"}, {"text": "买", "is_correct": false, "explanation": "不是反义词：买表示购入，与拆没有对立关系。"}, {"text": "看", "is_correct": false, "explanation": "不是反义词：看表示视觉感知，与拆没有对立关系。"}], "correct_answer": "建", "explanations": {"建": "反义词：建指建造，与把建筑拆毁相反。", "写": "不是反义词：写表示书写，与拆没有对立关系。", "买": "不是反义词：买表示购入，与拆没有对立关系。", "看": "不是反义词：看表示视觉感知，与拆没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "建", "is_correct": true, "explanation": "反义词：建指建造，与把建筑拆毁相反。"}, {"text": "吃", "is_correct": false, "explanation": "不是反义词：吃指把食物咽下，与拆没有对立关系。"}, {"text": "唱", "is_correct": false, "explanation": "不是反义词：唱表示发出歌声，与拆没有对立关系。"}, {"text": "洗", "is_correct": false, "explanation": "不是反义词：洗表示用水去污，与拆没有对立关系。"}], "correct_answer": "建", "explanations": {"建": "反义词：建指建造，与把建筑拆毁相反。", "吃": "不是反义词：吃指把食物咽下，与拆没有对立关系。", "唱": "不是反义词：唱表示发出歌声，与拆没有对立关系。", "洗": "不是反义词：洗表示用水去污，与拆没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把合在一起的东西打开或毁掉。", "primary_collocate": null, "pronunciation": "chāi", "ipa": "ʈʂʰai̯˥", "syllable_count": 1, "sentences": [{"text": "我拆了信，里面有一张照片。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子急着拆礼物。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座旧桥明年要拆了。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把那间旧房子拆了。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递到了，你先拆一下。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈拆过很多信，这封最重要。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的老房子都要拆。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁拆了我的信？", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别拆我的礼物，我想自己打开。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人明天来拆这堵旧墙。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拆了", "label": "体标"}, {"form": "拆过", "label": "体标"}, {"form": "拆开", "label": "复合"}, {"form": "拆除", "label": "复合"}], "register": "口语", "sense_fingerprint": "打开封好的东西，或把建筑拆毁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add11f56-6b71-44e4-ad75-5ff231dc05d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆 chāi：打开封好的东西，或把建筑拆毁。"}, {"text": "柴", "is_correct": false, "explanation": "chái 与 chāi 声调不同，意思是柴火。"}, {"text": "猜", "is_correct": false, "explanation": "cāi 与 chāi 声母不同（c 与 ch），意思是猜测。"}, {"text": "叉", "is_correct": false, "explanation": "chā 与 chāi 韵母不同，意思是叉子。"}], "explanations": {"拆": "拆 chāi：打开封好的东西，或把建筑拆毁。", "柴": "chái 与 chāi 声调不同，意思是柴火。", "猜": "cāi 与 chāi 声母不同（c 与 ch），意思是猜测。", "叉": "chā 与 chāi 韵母不同，意思是叉子。"}, "sentence_index": null, "correct_answer": "拆"}, "level_3": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆：打开信封取出信件，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉信就看不到里面的照片，与句意矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不用于信件。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把东西放进嘴里，与信件无关。"}], "explanations": {"拆": "拆：打开信封取出信件，符合句意。", "烧": "语义：烧掉信就看不到里面的照片，与句意矛盾。", "洗": "搭配：“洗”不用于信件。", "吃": "语义：“吃”指把东西放进嘴里，与信件无关。"}, "sentence_index": 0, "correct_answer": "拆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里拆了一个鸡蛋，放进锅里炒。", "explanation": "这里应该用〈打〉。拆指打开封好的东西或拆毁建筑，打鸡蛋要用打。"}, {"text": "他在院子里拆出一口井。", "explanation": "这里应该用〈挖〉。拆指拆开或拆毁，挖井要用挖。"}, {"text": "她从树上拆下一朵花。", "explanation": "这里应该用〈摘〉。拆指分开整体，从树上采花要用摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆 chāi：打开封好的东西，或把建筑拆毁。"}, {"text": "筛", "is_correct": false, "explanation": "shāi 与 chāi 声母不同（sh 与 ch），意思是筛子。"}, {"text": "呆", "is_correct": false, "explanation": "dāi 与 chāi 声母不同（d 与 ch），意思是呆板。"}, {"text": "摘", "is_correct": false, "explanation": "zhāi 与 chāi 声母不同（zh 与 ch），意思是摘下。"}], "explanations": {"拆": "拆 chāi：打开封好的东西，或把建筑拆毁。", "筛": "shāi 与 chāi 声母不同（sh 与 ch），意思是筛子。", "呆": "dāi 与 chāi 声母不同（d 与 ch），意思是呆板。", "摘": "zhāi 与 chāi 声母不同（zh 与 ch），意思是摘下。"}, "sentence_index": null, "correct_answer": "拆"}, "level_3": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆：把老房子拆毁，符合“都要……”的句意。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是人或动物的动作，老房子不能跑。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与老房子无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与老房子无关。"}], "explanations": {"拆": "拆：把老房子拆毁，符合“都要……”的句意。", "跑": "语义：“跑”是人或动物的动作，老房子不能跑。", "喝": "语义：“喝”指饮用，与老房子无关。", "唱": "语义：“唱”指发出歌声，与老房子无关。"}, "sentence_index": 6, "correct_answer": "拆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都拆这盆花。", "explanation": "这里应该用〈浇〉。拆指拆开或拆毁，给花浇水要用浇。"}, {"text": "孩子们在操场上拆球。", "explanation": "这里应该用〈踢〉。拆不能用于球类，踢球要用踢。"}, {"text": "厨房里正在拆水。", "explanation": "这里应该用〈烧〉。拆不能用于水，烧水要用烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拆了开那封信，读了起来。", "corrected_sentence": "他拆开了那封信，读了起来。", "error_description": "“开”是“拆”的结果补语，应说“拆开了”，“了”不能放在“开”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座旧楼上个月已经拆着了。", "corrected_sentence": "这座旧楼上个月已经拆了。", "error_description": "“拆”表示已完成的动作，应用“了”，“着”表示动作持续，不能在这里用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
