INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96545, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己愿意拿出钱，送给要帮忙的人。", "primary_collocate": null, "pronunciation": "juān kuǎn", "ipa": "tɕyɛn˥ kʰuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想给这个孩子捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都愿意为生病的老师捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班昨天给他捐款了。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们听说后，都来给她捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常常捐款，从不对别人说。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想帮他，就可以捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把奖金的一半拿出来捐款了。", "target_word": "捐款", "complexity_tier": "T3", "furigana": "tā bǎ jiǎngjīn de yíbàn ná chūlái juānkuǎn le。", "sentence_source": "generated"}, {"text": "小王请大家给病人捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带我去银行捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捐款了", "label": "体标"}, {"form": "捐了款", "label": "体标"}, {"form": "捐款人", "label": "复合"}], "register": "中性", "sense_fingerprint": "自愿拿钱送给需要帮助的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add11f56-6b71-44e4-ad75-5ff231dc05d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96545, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捐款", "is_correct": true, "explanation": "正确。“捐款”是自愿拿钱送人，与“给这个孩子”的意思相合。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：“罚款”是因违规而被处罚交钱，不是自愿送给孩子的钱。"}, {"text": "欠款", "is_correct": false, "explanation": "语义：“欠款”是欠别人的钱，不是送给别人的钱。"}, {"text": "扣款", "is_correct": false, "explanation": "语义：“扣款”是从款项中扣除，与自愿送给孩子的钱意思相反。"}], "explanations": {"捐款": "正确。“捐款”是自愿拿钱送人，与“给这个孩子”的意思相合。", "罚款": "语义：“罚款”是因违规而被处罚交钱，不是自愿送给孩子的钱。", "欠款": "语义：“欠款”是欠别人的钱，不是送给别人的钱。", "扣款": "语义：“扣款”是从款项中扣除，与自愿送给孩子的钱意思相反。"}, "sentence_index": 0, "correct_answer": "捐款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我向银行捐款买了一套房子。", "explanation": "这里应该用〈借款〉。捐款是自愿把钱给公益或需要帮助的人，不能用来向银行借钱买房。"}, {"text": "他把邻居家的玻璃打碎了，要捐款五十元。", "explanation": "这里应该用〈赔款〉。捐款是自愿给予，因损坏而必须付的钱要用赔款。"}, {"text": "我在超市买完东西，直接捐款结了账。", "explanation": "这里应该用〈付款〉。捐款是无偿给公益或救助对象的钱，结账付钱要用付款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96545, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捐款", "is_correct": true, "explanation": "正确。“捐款”是自愿出钱帮人，与“想帮他”的意思相合。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是晚到，不能用来帮助别人。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”是丢掉工作，与“想帮他”的意思相反。"}, {"text": "罢工", "is_correct": false, "explanation": "语义：“罢工”是停止工作以表示抗议，与帮助无关。"}], "explanations": {"捐款": "正确。“捐款”是自愿出钱帮人，与“想帮他”的意思相合。", "迟到": "语义：“迟到”是晚到，不能用来帮助别人。", "失业": "语义：“失业”是丢掉工作，与“想帮他”的意思相反。", "罢工": "语义：“罢工”是停止工作以表示抗议，与帮助无关。"}, "sentence_index": 6, "correct_answer": "捐款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校在操场上捐款，请大家来收钱。", "explanation": "这里应该用〈募捐〉。捐款是出钱的一方，向大家征集钱要用募捐。"}, {"text": "我昨天往老家的银行卡上捐款两千元。", "explanation": "这里应该用〈汇款〉。捐款是无偿给公益或救助对象的钱，往家人的银行卡上转钱要用汇款。"}, {"text": "他把积蓄拿去捐款，想赚更多钱。", "explanation": "这里应该用〈投资〉。捐款不是为了赚钱，想赚钱要用投资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年捐款三个。", "corrected_sentence": "他去年捐款三次。", "error_description": "量词错误：“捐款”计次要用动量词“次”，错误形式“三个”，正确形式“三次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每年都把灾区捐款。", "corrected_sentence": "他每年都给灾区捐款。", "error_description": "介词错误：错误形式“把灾区捐款”，正确形式“给灾区捐款”。“捐款”不能用“把”引出对象，表示捐给谁要用“给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
