INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取消；拿掉；向后退走。", "primary_collocate": null, "pronunciation": "chè", "ipa": "ʈʂʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "公司把他的职务撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定撤这个广告。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板撤了他的职。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把这条旧规定撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察慢慢往后撤。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们发现不对，马上撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这条消息撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队今晚就要撤。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家快点往后撤。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站已经把那张图片撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撤了", "label": "体标"}, {"form": "撤掉", "label": "复合"}, {"form": "撤走", "label": "复合"}, {"form": "撤退", "label": "复合"}], "register": "中性", "sense_fingerprint": "取消职务或内容，或向后退走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add11f56-6b71-44e4-ad75-5ff231dc05d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤”（chè，第四声）意思是撤走、取消或后退。"}, {"text": "车", "is_correct": false, "explanation": "车（chē，第一声）与撤（chè，第四声）声调不同，意思是车辆。"}, {"text": "扯", "is_correct": false, "explanation": "扯（chě，第三声）与撤（chè，第四声）声调不同，意思是拉、扯。"}, {"text": "舍", "is_correct": false, "explanation": "舍（shè）与撤（chè）声母不同（sh 与 ch），意思是房屋或舍弃。"}, {"text": "册", "is_correct": false, "explanation": "册（cè）与撤（chè）声母不同（c 与 ch），意思是书册。"}], "explanations": {"撤": "正确。“撤”（chè，第四声）意思是撤走、取消或后退。", "车": "车（chē，第一声）与撤（chè，第四声）声调不同，意思是车辆。", "扯": "扯（chě，第三声）与撤（chè，第四声）声调不同，意思是拉、扯。", "舍": "舍（shè）与撤（chè）声母不同（sh 与 ch），意思是房屋或舍弃。", "册": "册（cè）与撤（chè）声母不同（c 与 ch），意思是书册。"}, "sentence_index": null, "correct_answer": "撤"}, "level_3": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤了”表示取消职务，与“职务”搭配。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的对象是房屋、器物等具体的东西，“职务”不能拆。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”要挂在某处，不能说“挂了他的职务”。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”是咽下，与取消职务的意思不符。"}], "explanations": {"撤": "正确。“撤了”表示取消职务，与“职务”搭配。", "拆": "搭配：“拆”的对象是房屋、器物等具体的东西，“职务”不能拆。", "挂": "搭配：“挂”要挂在某处，不能说“挂了他的职务”。", "吞": "语义：“吞”是咽下，与取消职务的意思不符。"}, "sentence_index": 0, "correct_answer": "撤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上撤一杯牛奶。", "explanation": "这里应该用〈喝〉。撤表示取消、拿掉或后退，喝牛奶要用喝。"}, {"text": "他一直向前撤，走出了房间。", "explanation": "这里应该用〈进〉。撤是向后退，不能说向前撤。"}, {"text": "他的手机突然撤了，只好去买一部新的。", "explanation": "这里应该用〈坏〉。撤表示取消、拿走或后退，不能说手机撤了，手机坏了要说坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤”（chè，第四声）意思是撤走、取消或后退。"}, {"text": "测", "is_correct": false, "explanation": "测（cè）与撤（chè）声母不同（c 与 ch），意思是测量。"}, {"text": "策", "is_correct": false, "explanation": "策（cè）与撤（chè）声母不同（c 与 ch），意思是计策。"}, {"text": "射", "is_correct": false, "explanation": "射（shè）与撤（chè）声母不同（sh 与 ch），意思是发射。"}, {"text": "设", "is_correct": false, "explanation": "设（shè）与撤（chè）声母不同（sh 与 ch），意思是设置。"}], "explanations": {"撤": "正确。“撤”（chè，第四声）意思是撤走、取消或后退。", "测": "测（cè）与撤（chè）声母不同（c 与 ch），意思是测量。", "策": "策（cè）与撤（chè）声母不同（c 与 ch），意思是计策。", "射": "射（shè）与撤（chè）声母不同（sh 与 ch），意思是发射。", "设": "设（shè）与撤（chè）声母不同（sh 与 ch），意思是设置。"}, "sentence_index": null, "correct_answer": "撤"}, "level_3": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤”表示取消或拿掉消息，与“请把这条消息”相合。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”用于液体或容器里的东西，“消息”不能倒。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”要扛着有形的东西，“消息”不能扛。"}, {"text": "叠", "is_correct": false, "explanation": "语义：“叠”是把东西折起来，与取消消息的意思不符。"}], "explanations": {"撤": "正确。“撤”表示取消或拿掉消息，与“请把这条消息”相合。", "倒": "搭配：“倒”用于液体或容器里的东西，“消息”不能倒。", "扛": "搭配：“扛”要扛着有形的东西，“消息”不能扛。", "叠": "语义：“叠”是把东西折起来，与取消消息的意思不符。"}, "sentence_index": 6, "correct_answer": "撤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把钱撤给了希望小学。", "explanation": "这里应该用〈送〉。撤是取消或拿走，不能用来把钱送给别人。"}, {"text": "他向大家撤了一个笑容。", "explanation": "这里应该用〈露出〉。撤表示取消或拿掉，笑容要说露出。"}, {"text": "他把脸撤干净了，然后出门了。", "explanation": "这里应该用〈洗〉。撤表示拿走或取消，洗脸要用洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们慢慢往前撤。", "corrected_sentence": "士兵们慢慢往后撤。", "error_description": "方向错误：错误形式“往前撤”，正确形式“往后撤”。“撤”表示向后退，不能说往前撤。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把旧规定撤了掉。", "corrected_sentence": "他们把旧规定撤掉了。", "error_description": "补语位置错误：错误形式“撤了掉”，正确形式“撤掉了”。“撤掉”是动补结构，“掉”要紧跟动词，之后再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89b920c-187d-4c5e-8c9f-909d93c69efc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
