INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96549, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "你出生和小时候长大的地方。", "primary_collocate": null, "pronunciation": "gù xiāng", "ipa": "ku˥˩ ɕiɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "我的故乡是一个小城市。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他十八岁就离开了故乡。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很想念故乡的菜。", "target_word": "故乡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过年的时候，我一定会回故乡。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故乡的冬天很冷，常常下雪。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的故乡在哪儿？", "target_word": "故乡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在国外住了十年，还是常常想起故乡。", "target_word": "故乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐火车回到了故乡的小镇。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故乡的河边有一棵很大的树。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她给我看过很多故乡的照片。", "target_word": "故乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第二故乡", "label": "复合"}, {"form": "故乡情", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己出生并长大的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大学", "is_correct": false, "explanation": "语义：“大学”是学校，不是城市，不能说“是一个小城市”。"}, {"text": "故乡", "is_correct": true, "explanation": "故乡指出生或长大的地方，可以是一个小城市，与句意相合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不是城市，句子语义不通。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人的容貌，不能用来说“是一个小城市”。"}], "explanations": {"大学": "语义：“大学”是学校，不是城市，不能说“是一个小城市”。", "故乡": "故乡指出生或长大的地方，可以是一个小城市，与句意相合。", "手机": "语义：“手机”是通讯工具，不是城市，句子语义不通。", "外貌": "体貌：“外貌”指人的容貌，不能用来说“是一个小城市”。"}, "sentence_index": 0, "correct_answer": "故乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的故乡在三楼。", "explanation": "这里应该用〈家〉。故乡指出生或长大的地方，是较大的地域，不能指一个楼层；〈家〉才指住的地方。"}, {"text": "他去故乡留学了。", "explanation": "这里应该用〈国外〉。故乡指出生或长大的地方，不能作为留学的目的地；去外国留学要说〈国外〉。"}, {"text": "我心里有一把故乡。", "explanation": "这里应该用〈个〉。〈把〉用于有柄的器具，故乡不能用〈把〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宾馆", "is_correct": false, "explanation": "语义：“宾馆”是短期住宿的地方，与“住了十年”的长期生活不符，一般不会常常想起。"}, {"text": "故乡", "is_correct": true, "explanation": "故乡指出生或长大的地方，离开多年后仍会常常想起，与句意相合。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“想起”后接人、事或地方，不能接“星期”这样的时间单位。"}, {"text": "遥控器", "is_correct": false, "explanation": "语义：“遥控器”是电器，不是可以怀念的人或地方，句子语义不通。"}], "explanations": {"宾馆": "语义：“宾馆”是短期住宿的地方，与“住了十年”的长期生活不符，一般不会常常想起。", "故乡": "故乡指出生或长大的地方，离开多年后仍会常常想起，与句意相合。", "星期": "搭配：“想起”后接人、事或地方，不能接“星期”这样的时间单位。", "遥控器": "语义：“遥控器”是电器，不是可以怀念的人或地方，句子语义不通。"}, "sentence_index": 6, "correct_answer": "故乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间小屋是鲁迅的故乡，游客每天都来参观。", "explanation": "这里应该用〈故居〉。故居指以前住过的房子，故乡指出生或长大的地方，不能指一间屋子。"}, {"text": "他每天骑车去故乡上课。", "explanation": "这里应该用〈学校〉。故乡是出生或长大的地方，不是上课的场所。"}, {"text": "他给孩子讲了一个有趣的故乡。", "explanation": "这里应该用〈故事〉。故乡是地方，不能用来讲述，讲的应是〈故事〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我心里一直有一张故乡。", "corrected_sentence": "我心里一直有一个故乡。", "error_description": "量词错误：“张”用于纸、桌子等平面的东西，故乡不能用“张”来数，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他回了过一次故乡。", "corrected_sentence": "他回过一次故乡。", "error_description": "体标错误：“了”和“过”不能同时用在动词后。表示曾经有过的经历只用“过”，应说“回过一次故乡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
