INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出生或长期生活过的地方；家乡。", "primary_collocate": null, "pronunciation": "gù xiāng", "ipa": "ku˥˩ ɕiɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "他离开故乡已经三十年了。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家一生都在写故乡。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在上海工作多年，却始终想念故乡。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对游子来说，故乡永远是心里最温暖的地方。", "target_word": "故乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人晚年回到故乡，过着安静的生活。", "target_word": "故乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这座城市生活了很多年，这里也像他的故乡。", "target_word": "故乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让很多人离开了故乡。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "诗人常常在诗里写自己的故乡。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他退休以后，想回故乡盖一间房子。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那首歌让我想起了遥远的故乡。", "target_word": "故乡", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "第二故乡", "label": "复合"}, {"form": "故乡情", "label": "复合"}], "register": "书面", "sense_fingerprint": "出生地或长期生活过、有感情的地方，即家乡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1e8414-7582-4dbe-a81b-3a8bac0d7e80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，不是可以离开的地方，句子不通。"}, {"text": "故乡", "is_correct": true, "explanation": "故乡指出生或长期生活过的地方，人可以离开，与句意相合。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：“容貌”指人的外表，不是可以离开的地方，形状与意义都不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：人不可能离开空气三十年，“空气”作为离开的对象语义不通。"}], "explanations": {"星期": "语义：“星期”是时间单位，不是可以离开的地方，句子不通。", "故乡": "故乡指出生或长期生活过的地方，人可以离开，与句意相合。", "容貌": "体貌：“容貌”指人的外表，不是可以离开的地方，形状与意义都不符。", "空气": "语义：人不可能离开空气三十年，“空气”作为离开的对象语义不通。"}, "sentence_index": 0, "correct_answer": "故乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷给我讲了一个很长的故乡。", "explanation": "这里应该用〈故事〉。故乡指出生或长期生活过的地方，不能用来讲述。"}, {"text": "他心里有一匹故乡。", "explanation": "这里应该用〈个〉。〈匹〉用于马、布等，故乡不能用〈匹〉来数。"}, {"text": "老师让我们写一篇故乡。", "explanation": "这里应该用〈作文〉。故乡是地方，不是可以写的文章，写的应是关于故乡的〈作文〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是人可以离开的地方，句子语义不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“离开”不能带“时间”这样的抽象时间词作宾语。"}, {"text": "故乡", "is_correct": true, "explanation": "故乡指出生或长期生活过的地方，战争使人被迫离开，与句意相合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是报酬，不是可以离开的地方或人，句子语义不通。"}], "explanations": {"天空": "语义：“天空”不是人可以离开的地方，句子语义不通。", "时间": "搭配：“离开”不能带“时间”这样的抽象时间词作宾语。", "故乡": "故乡指出生或长期生活过的地方，战争使人被迫离开，与句意相合。", "工资": "语义：“工资”是报酬，不是可以离开的地方或人，句子语义不通。"}, "sentence_index": 6, "correct_answer": "故乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座老屋是他的故乡，游客每天都来参观。", "explanation": "这里应该用〈故居〉。故居指以前住过的房子，故乡指出生或长期生活过的地方，不能指一座房子。"}, {"text": "他每天八点去故乡上课。", "explanation": "这里应该用〈学校〉。故乡是地方，不是上课的场所。"}, {"text": "他去派出所补办了故乡。", "explanation": "这里应该用〈身份证〉。故乡是地方，不是可以补办的证件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里一直有一台故乡。", "corrected_sentence": "他心里一直有一个故乡。", "error_description": "量词错误：“台”用于机器、演出等，故乡不能用“台”来数，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经想念了过故乡。", "corrected_sentence": "他曾经想念过故乡。", "error_description": "体标错误：“了”和“过”不能同时用在动词后。表示曾经有过的经历只用“过”，应说“曾经想念过故乡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfe32493-c973-42f0-afee-277cef151bce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
