INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96551, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人该怎么做，该怎么做人。", "primary_collocate": null, "pronunciation": "jiào dǎo", "ipa": "tɕjɑʊ˥˩ tɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爸爸教导我做人要诚实。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常教导孩子要尊敬老人。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母教导我们要帮助别人。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教导他，做人要善良。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人教导年轻人要讲信用。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她教导女儿遇事要冷静。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷总是教导我们别骄傲。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他教导学生要诚实做人。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父教导徒弟，做事先做人。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会教导孩子要有礼貌。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "教导了", "label": "体标"}, {"form": "教导着", "label": "体标"}, {"form": "教导过", "label": "体标"}], "register": "书面", "sense_fingerprint": "告诫并教人如何做人处事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96551, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教导", "is_correct": true, "explanation": "正确：“教导”指告诫并教人如何做人，与“做人要诚实”相合。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：“拜访”指登门看望，与“做人要诚实”这类训诫内容不合。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”的对象是火或食物，不能带“我做人要诚实”这样的小句。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复器物，与“做人”无关。"}], "explanations": {"教导": "正确：“教导”指告诫并教人如何做人，与“做人要诚实”相合。", "拜访": "语义：“拜访”指登门看望，与“做人要诚实”这类训诫内容不合。", "烧": "搭配：“烧”的对象是火或食物，不能带“我做人要诚实”这样的小句。", "修理": "语义：“修理”指修复器物，与“做人”无关。"}, "sentence_index": 0, "correct_answer": "教导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天教导家里的花按时浇水。", "explanation": "这里应该用〈照料〉。“教导”是告诉人该怎样做、该怎样做人，照料花草要用“照料”。"}, {"text": "他教导这台机器按时保养。", "explanation": "这里应该用〈维护〉。“教导”是告诉人该怎样做人，机器的日常保养要用“维护”。"}, {"text": "护士每天教导病房里的床单。", "explanation": "这里应该用〈更换〉。“教导”的对象是人，床单只能更换、整理，不能“教导”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教导", "is_correct": true, "explanation": "正确：“教导”指告诫并教人如何做人，与“总是……我们别骄傲”的劝诫内容相合。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要车辆等物件作宾语，不能接“我们别骄傲”。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是植物或土地，不能用于“我们别骄傲”。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造房屋或设施，与劝人谦虚的语境不合。"}], "explanations": {"教导": "正确：“教导”指告诫并教人如何做人，与“总是……我们别骄傲”的劝诫内容相合。", "驾驶": "配价：“驾驶”需要车辆等物件作宾语，不能接“我们别骄傲”。", "浇灌": "搭配：“浇灌”的对象是植物或土地，不能用于“我们别骄傲”。", "修建": "语义：“修建”指建造房屋或设施，与劝人谦虚的语境不合。"}, "sentence_index": 6, "correct_answer": "教导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师教导我作业写得好。", "explanation": "这里应该用〈夸奖〉。“教导”是告诫、教人做人，表扬别人的表现要用“夸奖”。"}, {"text": "厨师教导这锅汤要慢慢熬。", "explanation": "这里应该用〈熬〉。“教导”的对象是人，熬汤要用“熬”。"}, {"text": "我教导他的诚实。", "explanation": "这里应该用〈欣赏〉。“教导”是告诉别人该怎样做人，赞赏别人的品格要用“欣赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲常被教导我做人要诚实。", "corrected_sentence": "父亲常教导我做人要诚实。", "error_description": "错误：“教导”前多加了“被”，而“教导”后面直接带受教者“我”，应用主动句。正确：“父亲常教导我……”，受教者紧跟在“教导”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶总是教导给我们别骄傲。", "corrected_sentence": "奶奶总是教导我们别骄傲。", "error_description": "错误：“教导”与受教者之间多加了“给”。正确：“教导＋人＋别／要……”，受教者直接放在“教导”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
