INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "教育引导；指点。", "primary_collocate": null, "pronunciation": "jiào dǎo", "ipa": "tɕjɑʊ˥˩ tɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师耐心地教导我们写作文。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅教导徒弟怎样用机器。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教导学生如何读书。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常教导弟弟怎样学习。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练教导队员怎样跑步。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老主任教导年轻医生怎样接诊病人。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教导我们怎样查字典。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你教导我这么多。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐耐心教导妹妹理解数学题。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真教导新同事怎样工作。", "target_word": "教导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "教导了", "label": "体标"}, {"form": "教导着", "label": "体标"}, {"form": "教导过", "label": "体标"}], "register": "书面", "sense_fingerprint": "指点并引导别人学习做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教导", "is_correct": true, "explanation": "正确：“教导”指耐心指点、引导别人学习做事，与“耐心地……写作文”相合。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或卫生，不能带“我们写作文”这样的动作宾语。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，与“写作文”的指点语境不符。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是场所或展览，不能直接带“我们写作文”这个动作短语。"}], "explanations": {"教导": "正确：“教导”指耐心指点、引导别人学习做事，与“耐心地……写作文”相合。", "打扫": "搭配：“打扫”的对象是场所或卫生，不能带“我们写作文”这样的动作宾语。", "发明": "语义：“发明”指创造新事物，与“写作文”的指点语境不符。", "参观": "配价：“参观”的宾语是场所或展览，不能直接带“我们写作文”这个动作短语。"}, "sentence_index": 0, "correct_answer": "教导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天教导这辆车的轮胎。", "explanation": "这里应该用〈检查〉。“教导”的对象是人，查看车胎要用“检查”。"}, {"text": "他负责教导这个项目的日常工作。", "explanation": "这里应该用〈指导〉。“教导”的对象是人，“项目”“工作”这类事务要用“指导”。"}, {"text": "工人认真教导这扇门的锁。", "explanation": "这里应该用〈修理〉。“教导”的对象是人，修锁要用“修理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教导", "is_correct": true, "explanation": "正确：“教导”指指点、引导别人学习做事，与“我们怎样查字典”的学习内容相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能带“我们怎样查字典”这样的短语。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”需要具体物件作宾语，不能接“我们怎样查字典”这类小句。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复坏掉的器物，与“查字典”的教学语境不合。"}], "explanations": {"教导": "正确：“教导”指指点、引导别人学习做事，与“我们怎样查字典”的学习内容相合。", "吃": "搭配：“吃”的对象是食物，不能带“我们怎样查字典”这样的短语。", "搬": "配价：“搬”需要具体物件作宾语，不能接“我们怎样查字典”这类小句。", "修理": "语义：“修理”指修复坏掉的器物，与“查字典”的教学语境不合。"}, "sentence_index": 6, "correct_answer": "教导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校教导学生的兴趣。", "explanation": "这里应该用〈培养〉。“教导”指口头指点、告诫，培养兴趣要用“培养”。"}, {"text": "工人教导施工进度。", "explanation": "这里应该用〈监督〉。“教导”针对人的指点引导，监督施工进度要用“监督”。"}, {"text": "医生教导病人的伤口。", "explanation": "这里应该用〈护理〉。“教导”针对人的指点引导，护理伤口要用“护理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师教导我们怎样的查资料。", "corrected_sentence": "老师教导我们怎样查资料。", "error_description": "错误：“怎样”后多加了“的”，修饰动词“查资料”时“怎样”不带“的”。正确：“教导＋人＋怎样＋动词”，“怎样”直接放在动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班主任教导给我们怎样整理笔记。", "corrected_sentence": "班主任教导我们怎样整理笔记。", "error_description": "错误：“教导”与受教者之间多加了“给”。正确：“教导＋人＋怎样＋动词”，受教者直接放在“教导”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
