INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96553, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把家里的事或吃的东西弄好。", "primary_collocate": null, "pronunciation": "liào lǐ", "ipa": "ljɑʊ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈生病了，爸爸一个人料理家务。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边工作，一边料理家里的事。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下班后还要料理家里的大小事。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把家里的事料理得很好。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我出差的时候，请你帮我料理一下家里的事。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会做饭，也不会料理自己的生活。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐结婚后，把家里的事都料理得井井有条。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人腿不好，孩子们轮流来料理家务。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人料理着全家的一日三餐。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出国了，家里的事都由妈妈料理。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "料理了", "label": "体标"}, {"form": "料理过", "label": "体标"}], "register": "口语", "sense_fingerprint": "料理：动词，安排处理家务、家里的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "料理", "is_correct": true, "explanation": "正确：“料理”指办理、处置家务，与“一个人……家务”相合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复坏掉的器物，不指处理家务。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能带“家务”。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”的对象是子女或幼小的人，不能带“家务”。"}], "explanations": {"料理": "正确：“料理”指办理、处置家务，与“一个人……家务”相合。", "修理": "语义：“修理”指修复坏掉的器物，不指处理家务。", "翻译": "搭配：“翻译”的对象是语言或文字，不能带“家务”。", "抚养": "搭配：“抚养”的对象是子女或幼小的人，不能带“家务”。"}, "sentence_index": 0, "correct_answer": "料理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天料理孩子的心情。", "explanation": "这里应该用〈调节〉。“料理”指办理家务、处置事务，调节情绪要用“调节”。"}, {"text": "她每天下班后料理书桌。", "explanation": "这里应该用〈整理〉。“料理”侧重办理家务和生活事务，收拾书桌要用“整理”。"}, {"text": "他每天早上料理一本小说。", "explanation": "这里应该用〈阅读〉。“料理”指办理家务、处置生活事务，看书要用“阅读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "料理", "is_correct": true, "explanation": "正确：“料理”指办理、处置家务，与“把家里的事都……得井井有条”相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能带“家里的事”。"}, {"text": "打听", "is_correct": false, "explanation": "语义：“打听”指探问消息，与把家务安排得井井有条的意思不合。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要车辆等物件作宾语，不能接“家里的事”。"}], "explanations": {"料理": "正确：“料理”指办理、处置家务，与“把家里的事都……得井井有条”相合。", "吃": "搭配：“吃”的对象是食物，不能带“家里的事”。", "打听": "语义：“打听”指探问消息，与把家务安排得井井有条的意思不合。", "驾驶": "配价：“驾驶”需要车辆等物件作宾语，不能接“家里的事”。"}, "sentence_index": 6, "correct_answer": "料理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她料理了一个月的假期。", "explanation": "这里应该用〈度过〉。“料理”指办理、处置家务事务，时间的流逝要用“度过”。"}, {"text": "爸爸下班后料理了那场精彩的比赛。", "explanation": "这里应该用〈观看〉。“料理”指办理家务事务，看比赛要用“观看”。"}, {"text": "作家正在料理那部小说的情节。", "explanation": "这里应该用〈构思〉。“料理”指办理家务事务，编写情节要用“构思”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把家里的杂事料理很利落。", "corrected_sentence": "他把家里的杂事料理得很利落。", "error_description": "错误：“把……料理”后面缺少补语标记“得”。正确：“把＋宾语＋料理得＋补语”，补语前必须加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把全家的事料理的很有条理。", "corrected_sentence": "她把全家的事料理得很有条理。", "error_description": "错误：补语标记用成了“的”。正确：“把＋宾语＋料理得＋补语”，补语标记必须是“得”，不是“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
