INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96554, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "烹调好的菜肴，常指日本、法国等外国风格的菜。", "primary_collocate": null, "pronunciation": "liào lǐ", "ipa": "ljɑʊ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "我最喜欢吃清淡的料理。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的料理很有创意。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们一起去尝尝那家店的料理吧。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在东京学过做料理的手艺。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道料理看起来很漂亮，味道也不错。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的料理比饭店的还好吃。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的料理又辣又香。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想尝尝这道新料理吗？", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位厨师最会做各种料理。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的料理都是爷爷亲手做的。", "target_word": "料理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日本料理", "label": "复合"}, {"form": "中国料理", "label": "复合"}, {"form": "料理店", "label": "复合"}], "register": "通用", "sense_fingerprint": "料理：名词，烹调好的菜肴，常指日本、法国等外国菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31e5a0b0-d7c0-4069-ac51-54595fc811ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "料理", "is_correct": true, "explanation": "正确：“料理”指烹调好的菜肴，与“吃清淡的”相合。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃音乐”。"}, {"text": "空调", "is_correct": false, "explanation": "语义：“空调”是家电，不是可以吃的东西，与饮食语境不合。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“吃”后面不能接“书”，“吃清淡的书”不成立。"}], "explanations": {"料理": "正确：“料理”指烹调好的菜肴，与“吃清淡的”相合。", "音乐": "搭配：“吃”的对象是食物，不能说“吃音乐”。", "空调": "语义：“空调”是家电，不是可以吃的东西，与饮食语境不合。", "书": "搭配：“吃”后面不能接“书”，“吃清淡的书”不成立。"}, "sentence_index": 0, "correct_answer": "料理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去建材市场买了一批料理。", "explanation": "这里应该用〈建材〉。“料理”指做好的菜肴，建筑材料要用“建材”。"}, {"text": "他在操场上踢料理。", "explanation": "这里应该用〈足球〉。“料理”指做好的菜肴，踢的对象是球，要用“足球”。"}, {"text": "他点了一杯料理。", "explanation": "这里应该用〈饮料〉。“料理”指做好的菜肴，饮品要用“饮料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "料理", "is_correct": true, "explanation": "正确：“料理”指烹调好的菜肴，与“又辣又香”描述的味道相合。"}, {"text": "服务员", "is_correct": false, "explanation": "语义：“服务员”是人，不能用“又辣又香”来形容。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“又辣又香”形容味道，“窗户”没有味道，搭配不当。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“房间”不能用“又辣又香”来描述，这种说法不成立。"}], "explanations": {"料理": "正确：“料理”指烹调好的菜肴，与“又辣又香”描述的味道相合。", "服务员": "语义：“服务员”是人，不能用“又辣又香”来形容。", "窗户": "搭配：“又辣又香”形容味道，“窗户”没有味道，搭配不当。", "房间": "搭配：“房间”不能用“又辣又香”来描述，这种说法不成立。"}, "sentence_index": 6, "correct_answer": "料理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在琴行买了一套料理。", "explanation": "这里应该用〈乐器〉。“料理”指做好的菜肴，琴类乐器要用“乐器”。"}, {"text": "妈妈去超市买了一把料理。", "explanation": "这里应该用〈蔬菜〉。“料理”指做好的菜肴，买未加工的蔬菜要说“蔬菜”。"}, {"text": "他是这家店的料理。", "explanation": "这里应该用〈老板〉。“料理”指做好的菜肴，指人要用“老板”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想尝一只清淡的料理。", "corrected_sentence": "我想尝一道清淡的料理。", "error_description": "错误：“料理”作菜肴时量词用了“只”。正确：菜肴要用量词“道”或“份”，“只”用于动物或成对的器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店地料理很有特色。", "corrected_sentence": "这家店的料理很有特色。", "error_description": "错误：名词“料理”前的修饰语用了“地”。正确：名词前的定语用“的”，“地”用于动词、形容词前作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57f04fec-9798-4b89-8386-5d89168aaa28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
