INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96555, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "绕着一个中心一圈一圈地转。", "primary_collocate": null, "pronunciation": "xuán zhuǎn", "ipa": "ɕɥɛn³⁵ ʈʂwan²¹⁴", "syllable_count": 2, "sentences": [{"text": "小女孩在舞台上不停地旋转。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇在天花板上慢慢旋转。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陀螺在桌子上快速旋转。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她旋转着跳舞，裙子飘了起来。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游乐场的大转盘一圈一圈地旋转。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在草地中间，开心地旋转。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶在水面上不停地旋转。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机里的衣服一直在旋转。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞者向左旋转了三圈。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的彩灯在夜里不停旋转。", "target_word": "旋转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "旋转了", "label": "体标（了）"}, {"form": "旋转着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "人或物体原地一圈一圈地转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd30c85d-4a0f-4f98-a131-765ce0ab0f38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96555, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旋转", "is_correct": true, "explanation": "“旋转”指绕中心一圈一圈地转，与“不停地”描述的持续转动相符。"}, {"text": "停下", "is_correct": false, "explanation": "语义：“停下”与“不停地”意思相反，句中要求持续转动。"}, {"text": "站立", "is_correct": false, "explanation": "语义：“站立”是静止的姿势，不能描述在舞台上不停地转动。"}, {"text": "静止", "is_correct": false, "explanation": "搭配：“不停地”不能修饰“静止”，句意自相矛盾。"}], "explanations": {"旋转": "“旋转”指绕中心一圈一圈地转，与“不停地”描述的持续转动相符。", "停下": "语义：“停下”与“不停地”意思相反，句中要求持续转动。", "站立": "语义：“站立”是静止的姿势，不能描述在舞台上不停地转动。", "静止": "搭配：“不停地”不能修饰“静止”，句意自相矛盾。"}, "sentence_index": 0, "correct_answer": "旋转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天旋转着去上班。", "explanation": "“旋转”指原地绕中心转动，不能表示行进到某个地方；去上班应该说“走”或“骑车”。"}, {"text": "他认真旋转了这个问题，想了很久。", "explanation": "“旋转”在这里被误用成了“琢磨、思考”的意思。它只指物体绕中心一圈一圈地转，不能用来表示在脑中反复考虑问题，这里应该用“琢磨”或“思考”。"}, {"text": "这家公司的业务在过去一年里旋转了三倍。", "explanation": "“旋转”指物体绕中心转圈，不能表示数量的增加；这里应该用“增长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旋转", "is_correct": true, "explanation": "“旋转”表示树叶在水面上绕中心打转，与“不停地”描述的持续转动相符。"}, {"text": "挺立", "is_correct": false, "explanation": "搭配：“挺立”指直立不动，与“不停地”的持续转动矛盾。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指变成固体，与树叶在水面上不停运动的情景矛盾。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”与“不停地”表示的持续运动相反。"}], "explanations": {"旋转": "“旋转”表示树叶在水面上绕中心打转，与“不停地”描述的持续转动相符。", "挺立": "搭配：“挺立”指直立不动，与“不停地”的持续转动矛盾。", "凝固": "语义：“凝固”指变成固体，与树叶在水面上不停运动的情景矛盾。", "停滞": "语义：“停滞”与“不停地”表示的持续运动相反。"}, "sentence_index": 6, "correct_answer": "旋转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钟摆在墙上来回旋转。", "explanation": "“旋转”是绕中心转圈，钟摆只是来回摆动，这里应该用“摆动”。"}, {"text": "他旋转着写完了作业。", "explanation": "“旋转”在这里被误用成了“完成、做”的意思。它只指物体绕中心转圈，不能用来表示完成作业，这里应该用“完成”或“做”。"}, {"text": "这条河旋转着流向大海。", "explanation": "“旋转”指物体绕中心转圈，这里却被误用为“河水顺河道向前行进”的意思。河水顺流而下不能用它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电扇在屋顶上旋转起了来。", "corrected_sentence": "电扇在屋顶上旋转起来了。", "error_description": "错误形式是“旋转起了来”，“起来”是复合趋向补语，不能拆开插入“了”。正确形式是“旋转起来了”，“了”应放在“起来”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在台上旋转几了圈。", "corrected_sentence": "他在台上旋转了几圈。", "error_description": "错误形式是“旋转几了圈”，“了”放在了数量词“几”和“圈”之间。“了”是动态助词，应紧跟动词，正确形式为“旋转了几圈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59b03684-fa8f-4c6a-ad64-753ee474e536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“既有”与“新”相对：既有指原来就有的，新指后来出现的。"}, {"text": "陌生", "is_correct": false, "explanation": "“陌生”指不熟悉，与“既有”的“原已拥有”义没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“既有”无反义关系。"}, {"text": "重要", "is_correct": false, "explanation": "“重要”指作用大，与“既有”的意思没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "“既有”与“新”相对：既有指原来就有的，新指后来出现的。", "陌生": "“陌生”指不熟悉，与“既有”的“原已拥有”义没有反义关系。", "简单": "“简单”指不复杂，与“既有”无反义关系。", "重要": "“重要”指作用大，与“既有”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“既有”与“新”相对：既有指原本就有，新指后来新增的。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或不吵闹，与“既有”无反义关系。"}, {"text": "方便", "is_correct": false, "explanation": "“方便”指便于做事，与“既有”的意思没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“既有”无反义关系。"}], "correct_answer": "新", "explanations": {"新": "“既有”与“新”相对：既有指原本就有，新指后来新增的。", "安静": "“安静”指没有声音或不吵闹，与“既有”无反义关系。", "方便": "“方便”指便于做事，与“既有”的意思没有反义关系。", "简单": "“简单”指不复杂，与“既有”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "已经有了的。", "primary_collocate": null, "pronunciation": "jì yǒu", "ipa": "tɕi˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们先用既有的材料做这件事。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把既有的问题先解决好。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想放弃既有的成绩。", "target_word": "既有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司想用既有的人手完成工作。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先看看既有的资料。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书只写了既有的研究结果。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，先复习既有的知识，再学新的。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既有的钱不够，我们还要再借一点。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠着既有的经验，很快找到了办法。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院要在既有的条件下多帮病人。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "已经拥有、现成存在的（材料、资料、条件、经验等），常与新的相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '506a5831-e979-43c6-b820-ed0eec4d2a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既有", "is_correct": true, "explanation": "正确。既有表示原来已经有的，修饰“材料”，符合句意。"}, {"text": "善良", "is_correct": false, "explanation": "语义：材料不能是善良的，“善良”只用于形容人。"}, {"text": "焦急", "is_correct": false, "explanation": "语义：材料没有情绪，“焦急”描述人的心情，不能修饰材料。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰材料。"}], "explanations": {"既有": "正确。既有表示原来已经有的，修饰“材料”，符合句意。", "善良": "语义：材料不能是善良的，“善良”只用于形容人。", "焦急": "语义：材料没有情绪，“焦急”描述人的心情，不能修饰材料。", "清脆": "搭配：“清脆”形容声音，不能修饰材料。"}, "sentence_index": 0, "correct_answer": "既有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司要招聘既有的员工，补充新岗位。", "explanation": "这里应该用〈新〉。招聘要找新加入的员工，既有指原来就有，不能招聘原有的员工。"}, {"text": "工厂要设计既有的设备，好尽快投产。", "explanation": "这里应该用〈新〉。设计要的是新的设备，既有指原来就有，不能用于要设计出来的东西。"}, {"text": "他们研制了既有的药，还没有人用过。", "explanation": "这里应该用〈新型〉。研制出来的药还没有人用过，不能说既有，既有指原来就有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既有", "is_correct": true, "explanation": "正确。复习的是原已学过的知识，既有指原来就有，符合句意。"}, {"text": "全新", "is_correct": false, "explanation": "语义：复习的内容必须是学过的，“全新”的知识无法复习，与“复习”矛盾。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”描述人的情绪，不修饰“知识”。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”指空间或时间距离大，不能修饰“知识”，与“复习”的语境不合。"}], "explanations": {"既有": "正确。复习的是原已学过的知识，既有指原来就有，符合句意。", "全新": "语义：复习的内容必须是学过的，“全新”的知识无法复习，与“复习”矛盾。", "高兴": "搭配：“高兴”描述人的情绪，不修饰“知识”。", "遥远": "语义：“遥远”指空间或时间距离大，不能修饰“知识”，与“复习”的语境不合。"}, "sentence_index": 6, "correct_answer": "既有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我们今天早上刚研发出来的既有产品。", "explanation": "这里应该用〈最新〉。既有指原来就有，今天早上刚研发出来的产品是最新的，不能说既有。"}, {"text": "这个安排是昨天刚定下来的，却是既有的安排。", "explanation": "这里应该用〈新〉。既有指原来就有，昨天刚定下来的安排是新的，不能说既有。"}, {"text": "这座楼明年才开始盖，是我们既有的楼。", "explanation": "这里应该用〈新〉。既有指原来就有，明年才开始盖的楼还不存在，不能说既有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们决定沿用既有地方案。", "corrected_sentence": "我们决定沿用既有的方案。", "error_description": "“既有”修饰名词时应用“的”，不能用“地”。应为“沿用既有的方案”，“既有地方案”误用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们计划沿用既有地系统。", "corrected_sentence": "我们计划沿用既有的系统。", "error_description": "“既有”修饰名词时应用“的”，不能用“地”。应为“沿用既有的系统”，“既有地系统”误用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“既有”与“新”相对：既有指原本就有，新指后来新增的。"}, {"text": "陌生", "is_correct": false, "explanation": "“陌生”指不熟悉，与“既有”无反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白，与“既有”的意思没有反义关系。"}, {"text": "重要", "is_correct": false, "explanation": "“重要”指作用大，与“既有”无反义关系。"}], "correct_answer": "新", "explanations": {"新": "“既有”与“新”相对：既有指原本就有，新指后来新增的。", "陌生": "“陌生”指不熟悉，与“既有”无反义关系。", "清楚": "“清楚”指明白，与“既有”的意思没有反义关系。", "重要": "“重要”指作用大，与“既有”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“既有”与“新”相对：既有指原本就有，新指后来新增的。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音，与“既有”无反义关系。"}, {"text": "方便", "is_correct": false, "explanation": "“方便”指便于做事，与“既有”无反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“既有”无反义关系。"}], "correct_answer": "新", "explanations": {"新": "“既有”与“新”相对：既有指原本就有，新指后来新增的。", "安静": "“安静”指没有声音，与“既有”无反义关系。", "方便": "“方便”指便于做事，与“既有”无反义关系。", "简单": "“简单”指不复杂，与“既有”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "原来就有的。", "primary_collocate": null, "pronunciation": "jì yǒu", "ipa": "tɕi˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "新路修好后，既有的小路还会留着。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁会连上既有的线路。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校在既有的老楼旁边建了新楼。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新规定不会改变既有的做法。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府决定保留既有的老街。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把新桌子放在既有的桌子旁边。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新公园保留了既有的老树。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的老师没有改变班里既有的习惯。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人先检查既有的水管，再装新的。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新软件可以和既有的系统一起用。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "原本就存在的（制度、设施、做法、习惯等），与后来新增的相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '506a5831-e979-43c6-b820-ed0eec4d2a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既有", "is_correct": true, "explanation": "正确。既有表示原本就有的小路，与“新路”对照，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：小路不能是聪明的，“聪明”只用于形容人或动物。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，不能修饰小路。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：“嫩”多用于植物或食物的质地，一般不说嫩的小路。"}], "explanations": {"既有": "正确。既有表示原本就有的小路，与“新路”对照，符合句意。", "聪明": "语义：小路不能是聪明的，“聪明”只用于形容人或动物。", "热情": "语义：“热情”形容人的态度，不能修饰小路。", "嫩": "搭配：“嫩”多用于植物或食物的质地，一般不说嫩的小路。"}, "sentence_index": 0, "correct_answer": "既有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校要建立既有的制度，以改进教学。", "explanation": "这里应该用〈新〉。建立要的是新的制度，既有指原来就有，不能用于建立。"}, {"text": "这条生产线今天刚建好，是工厂既有的生产线。", "explanation": "这里应该用〈新〉。既有指原来就有，今天刚建好的生产线是新的，不能说既有。"}, {"text": "我们研发既有的机器，帮助员工减少工作量。", "explanation": "这里应该用〈新型〉。研发要的是新型机器，既有指原来就有，研发出来的东西不能说既有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既有", "is_correct": true, "explanation": "正确。既有表示原来就有的老树，符合“保留”的语境。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”与“老树”矛盾，保留下来的老树不能说新的。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：树不会愤怒，“愤怒”只用于形容人的情绪。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰树。"}], "explanations": {"既有": "正确。既有表示原来就有的老树，符合“保留”的语境。", "新": "语义：“新”与“老树”矛盾，保留下来的老树不能说新的。", "愤怒": "语义：树不会愤怒，“愤怒”只用于形容人的情绪。", "清脆": "搭配：“清脆”形容声音，不能修饰树。"}, "sentence_index": 6, "correct_answer": "既有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个系统是上个月刚开发的，却是既有的系统。", "explanation": "这里应该用〈最新〉。既有指原来就有，上个月刚开发的系统是最新的，不能说既有。"}, {"text": "这座桥是今年才通车的，却是既有的桥。", "explanation": "这里应该用〈崭新〉。既有指原来就有，今年才通车的桥是崭新的，不能说既有。"}, {"text": "这条规定是昨天刚颁布的，却是既有的规定。", "explanation": "这里应该用〈新〉。既有指原来就有，昨天刚颁布的规定是新的，不能说既有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校决定保留既有地制度。", "corrected_sentence": "学校决定保留既有的制度。", "error_description": "“既有”修饰名词时应用“的”，不能用“地”。应为“保留既有的制度”，“既有地制度”误用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f4ca81-e3cc-44f0-bbc2-d2181b6543c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
