INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96559, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对的事和不对的事。", "primary_collocate": null, "pronunciation": "shì fēi", "ipa": "ʂɻ̩˥˩ feɪ˥", "syllable_count": 2, "sentences": [{"text": "孩子要学会分清是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们明辨是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪小，还不懂是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个有原则的人，从不颠倒是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官的工作就是判断是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的是非，法院会说清楚。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很公平，说话从不混淆是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上消息很多，我们要学会辨别是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不分是非，把错事也说成对的。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上讲了很多故事，让孩子知道是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "是非曲直", "label": "复合"}, {"form": "是非题", "label": "复合"}, {"form": "是是非非", "label": "重叠"}], "register": "书面", "sense_fingerprint": "事情的对与错，需要分辨的道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "是非", "is_correct": true, "explanation": "正确。「分清是非」是固定说法，指分辨对与错，与「分清」搭配自然。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是具体的物件，不是可以分辨对错或界限的对象，不能被「分清」。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：「分清」后接的应是可以辨别的对错、界限或类别，「电话」搭配不通。"}, {"text": "面貌", "is_correct": false, "explanation": "语义：「面貌」指外表样子，不是需要辨别的道理，与「分清」不合。"}], "explanations": {"是非": "正确。「分清是非」是固定说法，指分辨对与错，与「分清」搭配自然。", "窗户": "语义：窗户是具体的物件，不是可以分辨对错或界限的对象，不能被「分清」。", "电话": "搭配：「分清」后接的应是可以辨别的对错、界限或类别，「电话」搭配不通。", "面貌": "语义：「面貌」指外表样子，不是需要辨别的道理，与「分清」不合。"}, "sentence_index": 0, "correct_answer": "是非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个苹果的是非很甜。", "explanation": "这里应该用〈味道〉。「是非」指道理上的对错，不能用来形容食物的味道。"}, {"text": "他的是非很高，打篮球很好。", "explanation": "这里应该用〈个子〉。「是非」指道理上的对错，不能用来说人的身高。"}, {"text": "今天的是非很好，我们去爬山吧。", "explanation": "这里应该用〈天气〉。「是非」指道理上的对错，不能用来说天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是非", "is_correct": true, "explanation": "正确。「混淆是非」指把对错弄颠倒，与「公平」「说话」的语境相合。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是物品，不是可以被混淆的对错或道理，「混淆」不能用于它。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：「混淆」后接的应是容易弄错的事理或事物，「花园」搭配不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是动作留下的声音或痕迹，不能与「说话」一起被「混淆」。"}], "explanations": {"是非": "正确。「混淆是非」指把对错弄颠倒，与「公平」「说话」的语境相合。", "窗帘": "语义：窗帘是物品，不是可以被混淆的对错或道理，「混淆」不能用于它。", "花园": "搭配：「混淆」后接的应是容易弄错的事理或事物，「花园」搭配不通。", "脚步": "语义：脚步是动作留下的声音或痕迹，不能与「说话」一起被「混淆」。"}, "sentence_index": 6, "correct_answer": "是非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古人常说是非有报。", "explanation": "这里应该用〈善恶〉。「善恶有报」是固定说法，「是非」不能与「有报」搭配。"}, {"text": "这件衣服的是非很贵。", "explanation": "这里应该用〈价格〉。「是非」指道理上的对错，不能用来指价钱。"}, {"text": "这把椅子的是非很结实。", "explanation": "这里应该用〈质地〉。「是非」指道理上的对错，不能用来形容家具的结实程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大人应该教孩子分辨一个是非。", "corrected_sentence": "大人应该教孩子分辨是非。", "error_description": "错误形式：「是非」前加了「一个」。正确形式：说「分辨是非」。原因：「是非」指对与错，是抽象名词，在「分辨是非」这个说法里不能加数量词「一个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很会分辨是非们。", "corrected_sentence": "他很会分辨是非。", "error_description": "错误形式：「是非」后加了「们」。正确形式：说「分辨是非」。原因：「是非」是抽象名词，不能加「们」表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
