INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人与人之间因闲话、争执而引起的口舌纠纷。", "primary_collocate": null, "pronunciation": "shì fēi", "ipa": "ʂɻ̩˥˩ feɪ˥", "syllable_count": 2, "sentences": [{"text": "他爱说闲话，总是惹出是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里是非多，我很少说话。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不在背后搬弄是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了躲开是非，他搬到了乡下。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居之间有了是非，要好好说开。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人最爱传是非，大家都不喜欢他。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很小心，免得惹来是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是两个人的是非，别人不要多嘴。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年他一直远离村里的是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿卷进朋友之间的是非。", "target_word": "是非", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "是非曲直", "label": "复合"}, {"form": "是非题", "label": "复合"}, {"form": "是是非非", "label": "重叠"}], "register": "书面", "sense_fingerprint": "人与人之间因闲话引起的口舌纠纷；不指对错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6d4133-df4d-4531-a654-0ada28ca850a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "是非", "is_correct": true, "explanation": "正确。「惹出是非」指引起口舌纠纷，与「爱说闲话」的语境相合。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：「惹出」指引起某种事端，「花朵」不是事端，与「爱说闲话」的语境毫无关联。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：「惹出」后接的是纠纷、麻烦一类，「工资」不能被「惹出」。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是物品，与人际间的闲话无关，不能被「惹出」。"}], "explanations": {"是非": "正确。「惹出是非」指引起口舌纠纷，与「爱说闲话」的语境相合。", "花朵": "语义：「惹出」指引起某种事端，「花朵」不是事端，与「爱说闲话」的语境毫无关联。", "工资": "搭配：「惹出」后接的是纠纷、麻烦一类，「工资」不能被「惹出」。", "灯泡": "语义：灯泡是物品，与人际间的闲话无关，不能被「惹出」。"}, "sentence_index": 0, "correct_answer": "是非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两人的争执里，他有一张是非。", "explanation": "这里不能用〈张〉。「张」用于平面的东西；指口舌纠纷时应用〈场〉。"}, {"text": "这场争论里，他有一支是非。", "explanation": "这里不能用〈支〉。「支」用于笔、队伍等；「是非」指口舌纠纷时应用〈场〉或〈桩〉。"}, {"text": "这场口角里，他有一根是非。", "explanation": "这里不能用〈根〉。「根」用于细长的东西；「是非」指口舌纠纷时应用〈场〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是非", "is_correct": true, "explanation": "正确。「惹来是非」指招来口舌纠纷，与「说话很小心，免得」的语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头与「惹来」搭配不通，也与「说话很小心」的语境无关。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：「惹来」后接的是纠纷、麻烦，「脚印」不能被「惹来」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与人际间的口舌无关，不能被「惹来」。"}], "explanations": {"是非": "正确。「惹来是非」指招来口舌纠纷，与「说话很小心，免得」的语境相合。", "石头": "语义：石头与「惹来」搭配不通，也与「说话很小心」的语境无关。", "脚印": "搭配：「惹来」后接的是纠纷、麻烦，「脚印」不能被「惹来」。", "天气": "语义：天气与人际间的口舌无关，不能被「惹来」。"}, "sentence_index": 6, "correct_answer": "是非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的是非很甜。", "explanation": "这里应该用〈味道〉。「是非」指人与人之间的口舌纠纷，不能用来形容食物的味道。"}, {"text": "这幅画的是非很鲜艳。", "explanation": "这里应该用〈颜色〉。「是非」指人与人之间的口舌纠纷，不能用来形容颜色。"}, {"text": "她的是非很温柔。", "explanation": "这里应该用〈性格〉。「是非」指人与人之间的口舌纠纷，不能用来形容人的性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他惹了一只是非，连朋友都不理他了。", "corrected_sentence": "他惹了一场是非，连朋友都不理他了。", "error_description": "量词错误：「是非」指口舌纠纷时，应用量词〈场〉，不能用〈只〉。正确形式是「一场是非」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最爱惹是非们，大家都躲着他。", "corrected_sentence": "他最爱惹是非，大家都躲着他。", "error_description": "错误形式：「是非」后加了「们」。正确形式：说「惹是非」。原因：「是非」是抽象名词，不能加「们」表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '700d6463-221c-4cf7-a67f-13221cf8f93b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
