INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96561, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "常常发生，很多次。", "primary_collocate": null, "pronunciation": "shí cháng", "ipa": "ʂʅ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这里的天气时常变化，出门要带伞。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人时常吵架，可是很快就和好。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路上时常有小石头滚下来。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河时常发大水。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟时常把作业忘在学校里。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，这里时常停电。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近时常能听到火车的声音。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他时常生病，所以身体不太好。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我小时候时常哭。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子时常一个人在院子里玩。", "target_word": "时常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某种情况多次反复发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '860bde18-c4ed-4c06-9a8b-433c8f6b3c60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96561, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时常", "is_correct": true, "explanation": "正确答案。时常 shí cháng，意思是常常发生、多次反复。"}, {"text": "失常", "is_correct": false, "explanation": "第一个音节声调不同：shī（第一声）与 shí（第二声），意思是不正常、反常。"}, {"text": "市场", "is_correct": false, "explanation": "两个音节的声调都不同：shì（第四声）、chǎng（第三声），意思是交易的场所。"}, {"text": "职场", "is_correct": false, "explanation": "第一个音节声母由 sh 变为 zh：zhí（第二声），第二个音节声调变为第三声，意思是工作的场所。"}], "explanations": {"时常": "正确答案。时常 shí cháng，意思是常常发生、多次反复。", "失常": "第一个音节声调不同：shī（第一声）与 shí（第二声），意思是不正常、反常。", "市场": "两个音节的声调都不同：shì（第四声）、chǎng（第三声），意思是交易的场所。", "职场": "第一个音节声母由 sh 变为 zh：zhí（第二声），第二个音节声调变为第三声，意思是工作的场所。"}, "sentence_index": null, "correct_answer": "时常"}, "level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词或“都”连用，单独用在“变化”前不自然。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示急忙去做，天气不能“赶紧变化”，句子说不通。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”指本人亲手去做，天气不是人，不能“亲自变化”。"}, {"text": "时常", "is_correct": true, "explanation": "正确答案。“时常”表示天气经常变化，与句意相符。"}], "explanations": {"从来": "搭配：“从来”多与否定词或“都”连用，单独用在“变化”前不自然。", "赶紧": "搭配：“赶紧”表示急忙去做，天气不能“赶紧变化”，句子说不通。", "亲自": "语义：“亲自”指本人亲手去做，天气不是人，不能“亲自变化”。", "时常": "正确答案。“时常”表示天气经常变化，与句意相符。"}, "sentence_index": 0, "correct_answer": "时常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥时常建成了。", "explanation": "这里应该用〈终于〉。〈时常〉表示反复出现，“建成”只能发生一次；应说“这座桥终于建成了”，表示经过很久后才完成。"}, {"text": "他刚刚时常打电话给我。", "explanation": "这里不能用〈时常〉。〈时常〉表示反复发生，与“刚刚”指刚发生的一次相矛盾；若想说近来多次，可以用〈最近〉。"}, {"text": "我的哥哥时常是公司经理。", "explanation": "这里应该用〈一直〉。〈时常〉表示反复出现，“是公司经理”是持续不变的身份，应说“我哥哥一直是公司经理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04e3df3-5733-47b8-a008-a3876f512985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
